window.ACM_LIBRARY = {"updated":"2026-10-23","items":[{"id":"daily-26-10-23","title":"小红的整数操作","source":"日常训练","platform":"本地题档","date":"2026-10-23","group":"daily","category":"数学与数论","tags":["gcd","比例不变量","整数区间"],"level":"基础","summary":"同时乘除保持最简比例不变；约去最大公约数后，可达整数对均为该最简整数对的正整数倍，转为求倍数 k 的可行区间。","caution":"原稿用 / 约分会转成浮点，且 k 上界用了向上取整；应使用 // 约分，以 ceil(l/min(x,y)) 与 floor(r/max(x,y)) 为界，计数需截到至少 0。","versions":[{"name":"hyper 原稿","language":"Python","status":"original","path":"daily/hyper/26.10.23-小红的整数操作.py","code":"import math\r\n\r\nx,y,l,r=map(int,input().split())\r\n\r\ngcd=math.gcd(x,y)\r\n\r\nx/=gcd\r\ny/=gcd\r\n\r\na=min(x,y)\r\nb=max(x,y)\r\nans=k_min=k_max=0\r\n\r\nk_min=(l-1)//a+1\r\nk_max=(r-1)//b+1\r\nprint(int(k_max-k_min+1))"}],"statement":"/media/pages/study/ACM/daily-26-10-23.png","links":[],"hasIssues":true},{"id":"daily-26-10-22","title":"病毒感染","source":"日常训练","platform":"本地题档","date":"2026-10-22","group":"daily","category":"图与树","tags":["树的重心","子树大小","迭代DFS"],"level":"进阶","summary":"先得到父子遍历序，逆序计算子树大小，检查删点后的最大连通块是否至多 n/2。","caution":"这份代码以树为前提；一般图需要 visited 与不同算法。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.10.22-病毒感染.cpp","code":"#include <bits/stdc++.h>\r\n#include <utility>\r\n#include <vector>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\n\r\nvoid solve() {\r\n    ll n,m;\r\n    cin>>n>>m;\r\n    vector<vector<ll>> tree(n+1);\r\n    for (ll i=0;i<m;i++){\r\n        ll a,b;\r\n        cin>>a>>b;\r\n        tree[a].push_back(b);\r\n        tree[b].push_back(a);\r\n    }\r\n\r\n    vector<ll> parent(n+1,0),order;\r\n    order.push_back(1);\r\n    for (int i=0;i<(int)order.size();i++){\r\n        ll u=order[i];\r\n        for (auto v : tree[u]){\r\n            if (v==parent[u]) continue;\r\n            parent[v]=u;\r\n            order.push_back(v);\r\n        }\r\n    }\r\n\r\n    vector<ll> ans;\r\n    vector<ll> sum(n+1,1);\r\n    \r\n    for (ll i=(ll)order.size()-1;i>0;i--){\r\n        ll u=order[i];\r\n        sum[parent[u]]+=sum[u];\r\n    }\r\n\r\n    for (ll u=1;u<=n;u++){\r\n        ll maxPart=n-sum[u];\r\n        for (ll v : tree[u]){\r\n            if (v==parent[u]) continue;\r\n            maxPart=max(maxPart,sum[v]);\r\n        }\r\n        if (maxPart<=n/2) ans.push_back(u);\r\n    }\r\n    for (auto x : ans) cout<<x<<\" \";\r\n}\r\n\r\nint main() {\r\n    int T=1;\r\n    // cin >> T;\r\n    while (T--) solve();\r\n    return 0;\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-10-22.png","links":[],"hasIssues":false},{"id":"daily-26-10-21","title":"杨辉三角","source":"日常训练","platform":"本地题档","date":"2026-10-21","group":"daily","category":"数学与数论","tags":["组合恒等式","快速幂"],"level":"进阶","summary":"用组合恒等式把求和化为 n(n−1)·2^(n−3)，再快速幂取模。","caution":"n=1、n=2 单独返回，避免出现负指数。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.10.21-杨辉三角.cpp","code":"#include <bits/stdc++.h>\r\n#include <iostream>\r\n#include <vector>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\nconst ll mod=99824353;\r\n\r\nll qpow(ll a,ll b){\r\n    ll tmp=1;\r\n    while (b) {\r\n        if (b&1) tmp=tmp*a%mod;\r\n        a=a*a%mod;\r\n        b=b>>1;\r\n    }\r\n    return tmp;\r\n}\r\n\r\nvoid solve() {\r\n    ll n;\r\n    cin>>n;\r\n    if (n==1){\r\n        cout<<0;\r\n        return;\r\n    }\r\n    if (n==2){\r\n        cout<<1;\r\n        return;\r\n    }\r\n    ll ans=(n%mod)*((n-1)%mod)%mod;\r\n    ans=ans*qpow(2,n-3)%mod;\r\n    cout<<ans;\r\n}\r\n\r\nint main() {\r\n    int T=1;\r\n    // cin >> T;\r\n    while (T--) solve();\r\n    return 0;\r\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"daily/AI/26.10.21-杨辉三角-AI.cpp","code":"#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\n\nconst ll mod=99824353; // 按题目给出的模数计算。\n\n// 快速幂：求 a^b 对 mod 取模的结果，时间复杂度 O(log b)。\nll qpow(ll a,ll b){\n    ll ans=1;\n    while (b){\n        // b 的当前最低位为 1，说明需要乘上当前的 a。\n        if (b&1) ans=ans*a%mod;\n        a=a*a%mod;\n        b>>=1;\n    }\n    return ans;\n}\n\nvoid solve(){\n    ll n;\n    cin>>n;\n\n    // 第 1 行为 [1]，只有下标 0，答案为 0^2*1=0。\n    if (n==1){\n        cout<<0<<'\\n';\n        return;\n    }\n    // 第 2 行为 [1,1]，答案为 0^2*1+1^2*1=1。\n    if (n==2){\n        cout<<1<<'\\n';\n        return;\n    }\n\n    /*\n    第 n 行有 n 个数，令 m=n-1，则 a[i]=C(m,i)。\n    C(m,i) 表示从 m 个不同元素中选择 i 个的方案数。\n\n    把 i^2 拆成 i*(i-1)+i：\n        sum i^2*C(m,i)\n      = sum i*(i-1)*C(m,i) + sum i*C(m,i)。\n\n    利用组合数恒等式：\n        i*C(m,i) = m*C(m-1,i-1)，\n        i*(i-1)*C(m,i) = m*(m-1)*C(m-2,i-2)。\n    再利用一整行组合数之和 sum C(t,j)=2^t，得到：\n        答案 = m*(m-1)*2^(m-2) + m*2^(m-1)\n             = m*(m+1)*2^(m-2)\n             = n*(n-1)*2^(n-3)。\n\n    这里 n>=3，指数非负；n=1、2 已经在前面单独处理。\n    n 最大为 10^18，不能建立杨辉三角，直接用公式和快速幂。\n    */\n\n    // 先分别取模再相乘，不能直接计算 n*(n-1)，否则会溢出。\n    // 每次相乘的两个数均小于 mod，乘积在 long long 范围内。\n    ll ans=(n%mod)*((n-1)%mod)%mod;\n    ans=ans*qpow(2,n-3)%mod;\n    cout<<ans<<'\\n';\n}\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    solve();\n    return 0;\n}\n\n// 时间复杂度 O(log n)，额外空间复杂度 O(1)。\n"}],"statement":"/media/pages/study/ACM/daily-26-10-21.png","links":[],"hasIssues":false},{"id":"daily-26-10-20","title":"矩形游戏","source":"日常训练","platform":"本地题档","date":"2026-10-20","group":"daily","category":"数学与数论","tags":["质因数分解","贪心"],"level":"进阶","summary":"按从小到大的质因子逐次缩小剩余量，累加每一步的贡献。","caution":"解释为何优先除小质因子；最后剩余的大质因子需要补贡献。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.10.20-矩形游戏.cpp","code":"#include <bits/stdc++.h>\r\n#include <cmath>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\n\r\nvoid solve() {\r\n    ll n;\r\n    cin>>n;\r\n    ll ans=n,tmp=n;\r\n    for (ll i=2;i<=sqrt(n);i++){\r\n        while (tmp%i==0) {\r\n            tmp/=i;\r\n            ans+=tmp;\r\n        }\r\n    }\r\n    if (tmp>1) ans++;\r\n    cout<<ans;\r\n}\r\n\r\nint main() {\r\n    int T=1;\r\n    // cin >> T;\r\n    while (T--) solve();\r\n    return 0;\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-10-20.png","links":[],"hasIssues":false},{"id":"daily-26-10-19","title":"小红的环形字符串","source":"日常训练","platform":"本地题档","date":"2026-10-19","group":"daily","category":"字符串","tags":["栈","环形消除","双指针"],"level":"进阶","summary":"先用栈消去相邻相同字符，再用双指针处理剩余串首尾可消除的部分。","caution":"原稿在判断 l<r 前读取 tmp[l]、tmp[r]；全消除时空串访问越界，需先检查边界。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.10.19-小红的环形字符串-hyper.cpp","code":"#include <bits/stdc++.h>\r\n#include <stack>\r\n#include <string>\r\n#include <vector>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nvoid solve() {\r\n    int n;\r\n    cin>>n;\r\n    string s;\r\n    cin>>s;\r\n    ll ans=n;\r\n    if (n==1){\r\n        cout<<0<<'\\n';\r\n        return;\r\n    }\r\n\r\n    stack<char> st;\r\n    for (char c : s){\r\n        if (st.empty()) st.push(c);\r\n        else if (c==st.top()) st.pop();\r\n        else st.push(c);\r\n    }\r\n    string tmp=\"\";\r\n    while (!st.empty()) {\r\n        tmp=st.top()+tmp;\r\n        st.pop();\r\n    }\r\n    ll l=0;\r\n    ll r=tmp.size()-1;\r\n    while (tmp[l]==tmp[r] and l<r) {\r\n        l++;\r\n        r--;\r\n    }\r\n    ans-=r-l+1;\r\n    cout<<ans<<'\\n';\r\n}\r\n\r\nint main() {\r\n    int T=1;\r\n    // cin >> T;\r\n    while (T--) solve();\r\n    return 0;\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-10-19.png","links":[],"hasIssues":true},{"id":"daily-26-10-18","title":"余数求和","source":"日常训练","platform":"本地题档","date":"2026-10-18","group":"daily","category":"数学与数论","tags":["整除分块","等差数列"],"level":"进阶","summary":"把 k mod i 写成 k−floor(k/i)·i，按商相等的区间整块求和。","caution":"商为 0 时及时结束；区间乘积应考虑中间溢出。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.10.18-余数求和-hyper.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nvoid solve() {\r\n    ll n,k;\r\n    cin>>n>>k;\r\n    ll ans=n*k;\r\n    for (ll l=1,r;l<=n;l=r+1){\r\n        ll t=k/l;\r\n        if (t==0) break;\r\n        r=min(n,k/t);\r\n        ans-=(k/l)*(l+r)*(r-l+1)/2;\r\n    }\r\n    cout<<ans;\r\n}\r\n\r\nint main() {\r\n    int T=1;\r\n    // cin >> T;\r\n    while (T--) solve();\r\n    return 0;\r\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"daily/AI/26.10.18-余数求和-AI.cpp","code":"#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\n\nll calc(ll n,ll k){\n    // k%i = k-(k/i)*i，所以答案为 n*k 减去所有 (k/i)*i。\n    // 先把每一项都当成 k，接下来按区间扣掉多算的部分。\n    ll ans=n*k;\n    for (ll l=1,r;l<=n;l=r+1){\n        ll d=k/l; // 当前这一块相同的商。\n        // i>k 时，k/i=0；这些位置的余数就是 k，已经包含在 ans 中。\n        // 同时避免后面计算 k/d 时除以零。\n        if (d==0) break;\n\n        // 从 l 开始，floor(k/i)=d 的最右位置为 floor(k/d)。\n        // 例如 k=10，l=4 时 d=2，那么 i=4、5 的商都为 2，r=5。\n        // 题目只累加到 n，所以还要用 n 限制右端点。\n        r=min(n,k/d);\n\n        // 一整块的贡献为 d*(l+(l+1)+...+r)，用等差数列求和。\n        ll sum=(l+r)*(r-l+1)/2;\n        ans-=d*sum;\n    }\n    return ans;\n    // 商相同的连续区间只有 O(sqrt(k)) 块，空间 O(1)。\n    // n*k、等差数列求和及乘积均使用 long long，本题范围内不会溢出。\n}\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    ll n,k;\n    cin>>n>>k;\n    cout<<calc(n,k)<<'\\n'; // 本题只有一组数据，答案可能为 0。\n    return 0;\n}\n"}],"statement":"/media/pages/study/ACM/daily-26-10-18.png","links":[],"hasIssues":false},{"id":"daily-26-10-17","title":"加减","source":"日常训练","platform":"本地题档","date":"2026-10-17","group":"daily","category":"贪心与双指针","tags":["中位数","前缀和","滑动窗口"],"level":"进阶","summary":"排序后窗口统一成中位数的代价最小，用前缀和 O(1) 计算代价并移动左端点。","caution":"两侧代价公式易差 1；窗口缩小到单点时费用应为 0。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.10.17-加减-hyper.cpp","code":"#include <bits/stdc++.h>\r\n#include <numeric>\r\n#include <vector>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nvoid solve() {\r\n    ll n,k;\r\n    cin>>n>>k;\r\n    vector<ll> a(n+1,0),pre(n+1,0);   \r\n    for (ll i=1;i<=n;i++) cin>>a[i];\r\n    sort(a.begin()+1,a.end());\r\n    for (int i=1;i<=n;i++) pre[i]=pre[i-1]+a[i];\r\n    ll ans=1;\r\n    auto cost = [&](int l,int r)->ll{\r\n        int mid=(l+r)/2;\r\n        ll lcost=a[mid]*(mid-l)-(pre[mid-1]-pre[l-1]);\r\n        ll rcost=(pre[r]-pre[mid])-a[mid]*(r-mid);\r\n        return lcost+rcost;\r\n    };\r\n\r\n    ll l=1;\r\n    for (ll r=1;r<=n;r++){\r\n        while (cost(l,r)>k and l<r) l++;\r\n        ans=max(ans,r-l+1);\r\n    }\r\n\r\n    cout<<ans;\r\n}\r\n\r\nint main() {\r\n    int T=1;\r\n    // cin >> T;\r\n    while (T--) solve();\r\n    return 0;\r\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"daily/AI/26.10.17-加减-AI.cpp","code":"#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\n\nvoid solve(){\n    int n;\n    ll k;\n    cin>>n>>k;\n    vector<ll> a(n+1),pre(n+1,0);\n    for (int i=1;i<=n;i++) cin>>a[i];\n    sort(a.begin()+1,a.end());\n    for (int i=1;i<=n;i++) pre[i]=pre[i-1]+a[i];\n\n    // 改成同一个数的代价为绝对差之和，取中位数最省操作，不是平均数。\n    // 对固定目标，优先选择离它最近的数，排序后存在连续区间的最优选择。\n    // 因此只需寻找能在 k 次操作内变成相同数的最长有序区间。\n    auto cost=[&](int l,int r)->ll{\n        int mid=(l+r)/2; // 偶数长度取左中位数，同样最优。\n        // 左边全部增加到 a[mid]，右边全部减少到 a[mid]。\n        // 中位数自身代价为 0，使用前缀和 O(1) 计算两侧的总操作数。\n        ll left=a[mid]*(mid-l)-(pre[mid-1]-pre[l-1]);\n        ll right=(pre[r]-pre[mid])-a[mid]*(r-mid);\n        return left+right;\n    };\n\n    int l=1,ans=0;\n    for (int r=1;r<=n;r++){\n        // 加入右端后，最小代价不会降低；移除左端后，最小代价不会增加。\n        // 超过预算就右移 l，恰好使用 k 次也合法，不能写成 >=k。\n        while (cost(l,r)>k) l++;\n        ans=max(ans,r-l+1);\n    }\n    cout<<ans<<'\\n';\n    // 排序 O(n log n)，双指针扫描 O(n)，空间 O(n)。\n    // k、前缀和与代价均使用 long long，避免 int 溢出。\n}\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    solve(); // 本题只有一组数据。\n    return 0;\n}\n"}],"statement":"/media/pages/study/ACM/daily-26-10-17.png","links":[],"hasIssues":false},{"id":"daily-26-10-16","title":"小红的偶子串","source":"日常训练","platform":"本地题档","date":"2026-10-16","group":"daily","category":"动态规划","tags":["字符串","线性DP"],"level":"基础","summary":"若相邻字符相同，用 dp[i−2]+2 延长可配对的偶数长度子串。","caution":"固定数组容量依赖题面长度；应明确状态表示以免与普通最大子段和混淆。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.10.16-小红的偶子串.cpp","code":"#include <bits/stdc++.h>\r\n#include <vector>\r\nusing namespace std;\r\n\r\nconst int N = 2e5;\r\n\r\nint main(){\r\n    vector<int> kadane(N+5);\r\n    string str;\r\n    cin>>str;\r\n    str='0'+str;\r\n    int res=0;\r\n\r\n    kadane[1]=0,kadane[0]=0;\r\n    for( size_t i = 2; i < str.size(); i ++ ){\r\n        if( str[i] == str[i-1] )\r\n            kadane[i] = kadane[i-2] + 2;\r\n        res = max(res, kadane[i]);\r\n    }\r\n    cout << res;\r\n    return 0;\r\n}\r\n"}],"statement":"/media/pages/study/ACM/daily-26-10-16.png","links":[],"hasIssues":false},{"id":"daily-26-10-6","title":"区间增量与单点求值","source":"日常训练","platform":"本地题档","date":"2026-10-06","group":"daily","category":"数据结构","tags":["区间修改","差分","树状数组"],"level":"进阶","summary":"原稿逐个增加区间元素，再回答单点查询；可用差分与树状数组优化。","caution":"当前实现单次修改为 O(n)，总量大时有超时风险；模板速查附树状数组写法。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.10.6-区间增量与单点求值-hyper.cpp","code":"#include <bits/stdc++.h>\r\n#include <vector>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\n\r\nint main(){\r\n    ll n,q;\r\n    cin>>n>>q;\r\n    vector<ll> a(n+1);\r\n    for (ll i=1;i<=n;i++) cin>>a[i];\r\n    for (ll i=1;i<=q;i++){\r\n        int op;\r\n        cin>>op;\r\n        if (op==1){\r\n            ll l,r,x;\r\n            cin>>l>>r>>x;\r\n            for (ll j=l;j<=r;j++){\r\n                a[j]+=x;\r\n            }\r\n        }\r\n        else{\r\n            ll x;\r\n            cin>>x;\r\n            cout<<a[x]<<'\\n';\r\n        }\r\n    }\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-10-6.png","links":[],"hasIssues":true},{"id":"daily-26-10-5","title":"小红的循环移位","source":"日常训练","platform":"本地题档","date":"2026-10-05","group":"daily","category":"字符串","tags":["循环移位","整除规则"],"level":"基础","summary":"枚举旋转次数，用旋转后末两位判断能否被 4 整除。","caution":"长度为 1 时不能把同一个数位当作两位数，需要单独核对。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.10.5-小红的循环移位-hyper.cpp","code":"#include <bits/stdc++.h>\r\n#include <ratio>\r\nusing namespace std;\r\n\r\nint main() {\r\n    string s;\r\n    cin>>s;\r\n    int n=(int)s.size();\r\n    int ans=-1;\r\n    for (int i=0;i<n;i++){\r\n        int a=(n-2+i)%n;\r\n        int b=(n-1+i)%n;\r\n        int t=(s[a]-'0')*10+s[b]-'0';\r\n        if (t%4==0){\r\n            ans=i;\r\n            break;\r\n        }\r\n    }\r\n    cout<<ans;\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-10-5.png","links":[],"hasIssues":true},{"id":"daily-26-10-4","title":"小绿的房子","source":"日常训练","platform":"本地题档","date":"2026-10-04","group":"daily","category":"图与树","tags":["树直径","BFS","离心率"],"level":"进阶","summary":"三次 BFS 找到直径两端，节点最远距离等于到这两个端点距离的较大值。","caution":"保留的 O(n²) 注释稿可对照理解；正式思路用线性遍历。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.10.4-小绿的房子-hyper.cpp","code":"/*\r\n超时版本\r\nO(n**2)\r\n\r\n#include <bits/stdc++.h>\r\n#include <vector>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nvoid find_distance(const vector<vector<int>>& tree,int pre,int u,int& max_dis,int tmp){\r\n    max_dis=max(max_dis,tmp);\r\n    for (int v : tree[u]){\r\n        if (v!=pre) find_distance(tree,u,v,max_dis,tmp+1);\r\n    }\r\n}\r\n\r\nint main() {\r\n    int n;\r\n    cin>>n;\r\n    vector<vector<int>> tree(n+1);\r\n    for (int i=1;i<n;i++){\r\n        int u,v;\r\n        cin>>u>>v;\r\n        tree[u].push_back(v);\r\n        tree[v].push_back(u);\r\n    }\r\n    int ans=0;\r\n    for (int i=1;i<=n;i++){\r\n        int max_dis=0;\r\n        find_distance(tree,0,i,max_dis,0);\r\n        if (max_dis<=2) ans++;\r\n    }\r\n    cout<<ans;\r\n}\r\n*/\r\n\r\n#include <bits/stdc++.h>\r\n#include <vector>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nint bfs(const vector<vector<int>>& tree,int u,vector<int>& dist){\r\n    int farthest=u;\r\n    queue<int> q;\r\n    q.push(u);\r\n    dist[u]=0;\r\n    while (!q.empty()) {\r\n        int v=q.front();\r\n        q.pop();\r\n\r\n        if (dist[v]>dist[farthest]) farthest=v;\r\n\r\n        for (int x : tree[v]){\r\n            if (dist[x]==-1){\r\n                dist[x]=dist[v]+1;\r\n                q.push(x);\r\n            }\r\n        }\r\n    }\r\n    return farthest;\r\n}\r\n\r\nint main() {\r\n    int n;\r\n    cin>>n;\r\n    vector<vector<int>> tree(n+1);\r\n    vector<int> dist1(n+1,-1),distA(n+1,-1),distB(n+1,-1);\r\n    int ans=0;\r\n    for (int i=1;i<n;i++){\r\n        int u,v;\r\n        cin>>u>>v;\r\n        tree[u].push_back(v);\r\n        tree[v].push_back(u);   \r\n    }\r\n    int A=bfs(tree,1,dist1);\r\n    int B=bfs(tree,A,distA);\r\n    bfs(tree,B,distB);\r\n    for (int i=1;i<=n;i++){\r\n        if (distA[i]<=2 and distB[i]<=2) ans++;\r\n    }\r\n    cout<<ans;\r\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"daily/AI/26.10.4-小绿的房子-AI.cpp","code":"#include <bits/stdc++.h>\r\n#include <vector>\r\nusing namespace std;\r\n\r\n/*\r\n * ============================== 题意 ==============================\r\n * 给出一棵有 n 个结点的树（可以想成 n 个房子由 n-1 条路连通）。\r\n * 求有多少个结点 u，满足：从 u 出发，到树上任意其他结点的距离都不超过 2。\r\n * 换句话说，就是统计所有「到其他点的最远距离（偏心距）<= 2」的结点个数。\r\n *\r\n * ============================ 暴力做法 ============================\r\n * 对每个结点都单独跑一次 DFS/BFS，求出它到所有点的最远距离，复杂度 O(n^2)，\r\n * n 较大时会超时（同目录下的 26.10.4-小绿的房子-hyper.cpp 就是这种写法）。\r\n *\r\n * ====================== 本代码的做法（O(n)）======================\r\n * 用到的关键结论：\r\n *   树上离任意点 u 最远的那个点，一定是「树的直径」的两个端点之一。\r\n * 所以先求出直径的两个端点 A、B，那么 u 到所有点的最远距离就等于\r\n *       max( u 到 A 的距离, u 到 B 的距离 )\r\n * 这样一来，只需要做 3 次 BFS 就能算出所有结点的答案。\r\n */\r\n\r\n// 从 start 出发做一次 BFS（广度优先搜索：一层一层地向外扩散）。\r\n// 传出参数 dist：最终 dist[v] 表示 start 到 v 的距离，-1 表示还没访问到。\r\n// 返回值：距离 start 最远的那个结点的编号。\r\nint bfs(const vector<vector<int>>& tree, int start, vector<int>& dist) {\r\n    // 邻接表的下标从 1 开始，所以结点个数 = tree.size() - 1\r\n    int n = (int)tree.size() - 1;\r\n    // 把距离数组整体重置为 -1，表示「所有点都还没访问过」\r\n    dist.assign(n + 1, -1);\r\n\r\n    queue<int> q;\r\n    // 起点入队；起点到自己的距离是 0\r\n    dist[start] = 0;\r\n    q.push(start);\r\n\r\n    // farthest 用来记录目前找到的、离起点最远的结点\r\n    int farthest = start;\r\n    while (!q.empty()) {\r\n        int u = q.front();\r\n        q.pop();\r\n\r\n        // BFS 是按距离从小到大出队的，所以最后一个出队的点就是最远点；\r\n        // 这里「边出队边比较」的效果相同，写法更直观。\r\n        if (dist[u] > dist[farthest]) {\r\n            farthest = u;\r\n        }\r\n\r\n        // 枚举 u 的所有邻居 v\r\n        for (int v : tree[u]) {\r\n            // dist[v] == -1 表示 v 还没被访问过，此时 u 相当于 v 的父亲\r\n            if (dist[v] == -1) {\r\n                // v 比 u 离起点再多走一步\r\n                dist[v] = dist[u] + 1;\r\n                q.push(v);\r\n            }\r\n        }\r\n    }\r\n\r\n    return farthest;\r\n}\r\n\r\nint main() {\r\n    int n;\r\n    cin >> n;\r\n\r\n    // 邻接表存树：tree[u] 中保存所有与 u 直接相连的结点\r\n    vector<vector<int>> tree(n + 1);\r\n    for (int i = 1; i < n; i++) {   // n 个结点的树恰好有 n - 1 条边\r\n        int u, v;\r\n        cin >> u >> v;\r\n        tree[u].push_back(v);       // 无向边，两个方向都要存\r\n        tree[v].push_back(u);\r\n    }\r\n\r\n    // dist1 只是第 1 次 BFS 的中间结果；distA / distB 是最后要用到的两组距离\r\n    vector<int> dist1, distA, distB;\r\n\r\n    // 第 1 次 BFS：从任意点（这里取 1 号点）出发，找到离它最远的点 A。\r\n    // 性质：这个 A 一定是树的一条直径的端点。\r\n    int A = bfs(tree, 1, dist1);\r\n\r\n    // 第 2 次 BFS：从 A 出发，找到离 A 最远的点 B —— 直径的另一个端点。\r\n    // 同时得到 distA[i] = A 到 i 的距离。\r\n    int B = bfs(tree, A, distA);\r\n\r\n    // 第 3 次 BFS：从 B 出发，得到 distB[i] = B 到 i 的距离。\r\n    bfs(tree, B, distB);\r\n\r\n    int ans = 0;\r\n    for (int i = 1; i <= n; i++) {\r\n        // 由直径的性质：i 到所有点的最远距离 = max(i 到 A 的距离, i 到 B 的距离)\r\n        // 若这个最远距离 <= 2，说明 i 到任意其他结点都在 2 步以内，符合题意\r\n        if (max(distA[i], distB[i]) <= 2) {\r\n            ans++;\r\n        }\r\n    }\r\n\r\n    cout << ans;\r\n    return 0;\r\n}\r\n"}],"statement":"/media/pages/study/ACM/daily-26-10-4.png","links":[],"hasIssues":false},{"id":"daily-26-10-3","title":"小苯的数组构造","source":"日常训练","platform":"本地题档","date":"2026-10-03","group":"daily","category":"构造","tags":["前缀最大值","贪心"],"level":"基础","summary":"扫描维护前缀最大值，输出把当前值补到该最大值所需的增量。","caution":"初始最大值要低于所有合法输入；不应把输入默认成非负。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.10.3-小苯的数组构造-hyper.cpp","code":"#include <bits/stdc++.h>\r\n#include <vector>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll MAX=1e10;\r\nconst ll MIN=-1e10;\r\n\r\nint main() {\r\n    int n;\r\n    cin>>n;\r\n    ll premax=MIN;\r\n    vector<ll> a(n+1,0);\r\n\r\n    for (int i=1;i<=n;i++){\r\n        cin>>a[i];\r\n        premax=max(a[i],premax);\r\n        cout<<premax-a[i]<<\" \";\r\n    }\r\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"daily/AI/26.10.3-小苯的数组构造-AI.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    int n;\r\n    cin >> n;\r\n\r\n    vector<long long> a(n);\r\n    for (long long &x : a) cin >> x;\r\n\r\n    /*\r\n     * 设 prefixMax = max(a[1], a[2], ..., a[i])。\r\n     * 令 b[i] = prefixMax - a[i]，\r\n     * 则修改后的第 i 项为 a[i] + b[i] = prefixMax。\r\n     *\r\n     * prefixMax 随 i 增大只会增大或不变，因此修改后的数组非递减。\r\n     *\r\n     * 又因为任何合法方案都可以整体平移 b（不会改变极差），\r\n     * 可以令 min(b) = 0。此时修改后的第 i 项必须不小于 prefixMax，\r\n     * 所以其相对 a[i] 至少要增加 prefixMax - a[i]。\r\n     * 因此上述构造得到的极差就是最小值。\r\n     */\r\n\r\n    long long prefixMax = LLONG_MIN;\r\n    for (int i = 0; i < n; ++i) {\r\n        prefixMax = max(prefixMax, a[i]);\r\n\r\n        if (i) cout << ' ';\r\n        cout << prefixMax - a[i];\r\n    }\r\n    cout << '\\n';\r\n}\r\n"}],"statement":"/media/pages/study/ACM/daily-26-10-3.png","links":[],"hasIssues":false},{"id":"daily-26-10-2","title":"数学考试","source":"日常训练","platform":"本地题档","date":"2026-10-02","group":"daily","category":"动态规划","tags":["阶段DP","滚动数组"],"level":"进阶","summary":"每道题先计算当前状态的得分，再枚举保持、减 Q、加 W 三种状态转移。","caution":"同一轮必须读旧数组、写新数组，不能把同一道题重复转移。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.10.2-数学考试-hyper.cpp","code":"#include <algorithm>\r\n#include <bits/stdc++.h>\r\n#include <vector>\r\nusing namespace std;\r\nusing ll = long long;\r\nint main() {\r\n    int n,K;\r\n    cin>>n>>K;\r\n    vector<ll> dp(K+1,0);\r\n    vector<ll> tmp(K+1,0);\r\n    vector<ll> ndp(K+1,0);\r\n    for (int i=0;i<n;i++){\r\n        ll a,b,Q,W;\r\n        cin>>a>>b>>Q>>W;\r\n        for (int p=0;p<=K;p++){\r\n            ll add=(p>b) ? 0 : (a*p);\r\n            tmp[p]=dp[p]+add;\r\n        }\r\n        for (int p=0;p<=K;p++){\r\n            ll cur=0;\r\n            cur=max(tmp[p],cur);\r\n            if (p-Q>=0) cur=max(tmp[p-Q],cur);\r\n            if (p+W<=K) cur=max(tmp[p+W],cur);\r\n            ndp[p]=cur;\r\n        }\r\n        dp.swap(ndp);\r\n    }\r\n    cout << *max_element(dp.begin(), dp.end()) << '\\n';\r\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"daily/AI/26.10.2-数学考试-AI.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    int n, K;\r\n    cin >> n >> K;\r\n\r\n    /*\r\n     * 状态定义：\r\n     * dp[p] = 完成已经处理过的题目后，当前压力为 p 时能获得的最大经验。\r\n     *\r\n     * 初始压力可以在 0~K 中任意选择，所以第一题开始前：\r\n     * dp[0] = dp[1] = ... = dp[K] = 0。\r\n     *\r\n     * best[p] 表示“以压力 p 完成当前题目并拿到得分后”的最大经验。\r\n     * ndp 保存完成压力变化之后的新状态。\r\n     */\r\n    vector<ll> dp(K + 1, 0);\r\n    vector<ll> best(K + 1, 0);\r\n    vector<ll> ndp(K + 1, 0);\r\n\r\n    for (int i = 0; i < n; ++i) {\r\n        ll a, b, Q, W;\r\n        cin >> a >> b >> Q >> W;\r\n\r\n        /*\r\n         * 第一步：先计算答题得分。\r\n         *\r\n         * 当前压力为 p 时：\r\n         * - 如果 p <= b，则可以做对，获得 a * p 经验；\r\n         * - 如果 p > b，则压力超过题目承受范围，获得 0 经验。\r\n         *\r\n         * 题目规定必须先用当前压力完成第 i 题，答题完成后才能改变压力，\r\n         * 所以这里先把得分加入 dp[p]，得到 best[p]。\r\n         */\r\n        for (int p = 0; p <= K; ++p) {\r\n            ll gain = (p <= b ? a * p : 0);\r\n            best[p] = dp[p] + gain;\r\n        }\r\n\r\n        /*\r\n         * 第二步：答题结束后选择新的压力。\r\n         *\r\n         * 假设答题后的新压力为 p，那么旧压力只能是：\r\n         * 1. p         ：保持压力不变；\r\n         * 2. p - Q     ：旧压力增加 Q 后变成 p，需要 p >= Q；\r\n         * 3. p + W     ：旧压力减少 W 后变成 p，需要 p + W <= K。\r\n         *\r\n         * 因此 ndp[p] 取三种来源中的最大值。\r\n         */\r\n        for (int p = 0; p <= K; ++p) {\r\n            // 情况 1：保持压力不变。\r\n            ll cur = best[p];\r\n\r\n            // 情况 2：从 p-Q 增加 Q 到 p。\r\n            if (p >= Q) cur = max(cur, best[p - Q]);\r\n\r\n            // 情况 3：从 p+W 减少 W 到 p。\r\n            if (p + W <= K) cur = max(cur, best[p + W]);\r\n\r\n            ndp[p] = cur;\r\n        }\r\n\r\n        // 当前题目处理完成后，ndp 成为下一题开始前的 dp。\r\n        dp.swap(ndp);\r\n    }\r\n\r\n    // 所有题目完成后，最终压力可以任意，取所有状态中的最大值。\r\n    cout << *max_element(dp.begin(), dp.end()) << '\\n';\r\n}\r\n"}],"statement":"/media/pages/study/ACM/daily-26-10-2.png","links":[],"hasIssues":false},{"id":"daily-26-10-1","title":"求树的根","source":"日常训练","platform":"本地题档","date":"2026-10-01","group":"daily","category":"图与树","tags":["有向树","入度","叶子"],"level":"基础","summary":"有向边标记孩子，未作为孩子出现的点为根，没有孩子的点为叶子。","caution":"单节点树同时是根和叶子；输出叶子前按编号排序。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.10.1-求树的根.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nint main() {\r\n    ll n;\r\n    cin>>n;\r\n    vector<vector<ll>> edges(n+1);\r\n    for (int i=1;i<n;i++){\r\n        ll a,b;\r\n        cin>>a>>b;\r\n        edges[a].push_back(b); \r\n    }    \r\n    vector<bool> ifroot(n+1,true);\r\n    vector<bool> ifleaf(n+1,true);\r\n    for (int i=1;i<=n;i++){\r\n        if(!edges[i].empty()){\r\n            ifleaf[i]=false;\r\n            for (ll x : edges[i]){\r\n                ifroot[x]=false;\r\n            }\r\n        }\r\n    }\r\n\r\n    for (int i=1;i<=n;i++){\r\n        if (ifroot[i]){\r\n            cout<<i<<'\\n';\r\n            break;\r\n        }\r\n    }\r\n\r\n    vector<ll> leafs;\r\n    for (int i=1;i<=n;i++){\r\n        if (ifleaf[i]){\r\n            leafs.push_back(i);\r\n        }\r\n\r\n    }\r\n    sort(leafs.begin(),leafs.end());\r\n    ll size=leafs.size();\r\n    for (ll x=0;x<size;x++){\r\n        cout<<leafs[x];\r\n        if (x!=size-1) cout<<\" \";\r\n    }\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-10-1.png","links":[],"hasIssues":false},{"id":"daily-26-9-30","title":"智乃的“凑数”题(Easy Version)","source":"日常训练","platform":"本地题档","date":"2026-09-30","group":"daily","category":"动态规划","tags":["二维背包","路径还原"],"level":"挑战","summary":"以两组元素的和作为二维状态，保存正负来源标记，查询时枚举乘积分解并还原选择。","caution":"压缩后的不规则二维数组需要特别核对下标；倒序更新防止重复使用同一元素。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.30-智乃的“凑数”题(Easy Version)-hyper.cpp","code":"#include <bits/stdc++.h>\r\n#include <vector>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nconst ll MAX=100;\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    int n, m;\r\n    cin >> n >> m;\r\n\r\n    vector<ll> k(n);\r\n    for (ll &x : k) cin >> x;\r\n\r\n    vector<vector<ll>> dp(MAX+1);\r\n    dp[0].resize(MAX + 1);\r\n    for (int i=1;i<=MAX;i++){\r\n        dp[i].resize(MAX/i+1);\r\n    }\r\n    dp[0][0]=1;\r\n\r\n    vector<ll> q(m);\r\n    for (ll &x : q) cin >> x;\r\n\r\n    for (int i=0;i<n;i++){\r\n        for (int a=MAX;a>=0;a--){\r\n            for (int b = (int)dp[a].size() - 1; b >= 0; b--){\r\n                if (dp[a][b] != 0) continue;\r\n                if (a-k[i]>=0 and dp[a-k[i]][b]!=0){\r\n                    dp[a][b]=k[i];\r\n                }\r\n                if (b-k[i]>=0 and dp[a][b-k[i]]!=0){\r\n                    dp[a][b]=-k[i];\r\n                }\r\n            }\r\n        }\r\n    }\r\n\r\n    for (int i=0;i<m;i++){\r\n        bool ifYes=false;\r\n        for (int tmp=1;tmp<=sqrt(q[i]);tmp++){\r\n            if (ifYes) break;\r\n            if (q[i]%tmp==0 and dp[tmp][q[i]/tmp]!=0){\r\n                ifYes=true;\r\n                vector<ll> row,col;\r\n                ll a=tmp;\r\n                ll b=q[i]/tmp;\r\n                while (a!=0 or b!=0) {\r\n                    if (dp[a][b]>0){\r\n                        row.push_back(dp[a][b]);\r\n                        a-=dp[a][b];\r\n                    } \r\n                    else {\r\n                        col.push_back(dp[a][b]);\r\n                        b+=dp[a][b];\r\n                    }\r\n                }\r\n                cout<<\"Yes\"<<'\\n';\r\n                cout<<row.size()<<\" \"<<col.size()<<'\\n';\r\n                for (int i=0;i<row.size();i++){\r\n                    cout<<row[i];\r\n                    if (i!=row.size()-1) cout<<\" \";\r\n                }\r\n                cout<<'\\n';\r\n                for (int i=0;i<col.size();i++){\r\n                    cout<<-col[i];\r\n                    if (i!=col.size()-1) cout<<\" \";\r\n                }\r\n                cout<<'\\n';\r\n            }\r\n        }\r\n        if(!ifYes) cout<<\"No\"<<'\\n';\r\n    }\r\n}\r\n"},{"name":"AI 参考","language":"C++","status":"reference","path":"daily/AI/26.9.30-智乃的“凑数”题(Easy Version)-AI.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    int n, m;\r\n    cin >> n >> m;\r\n\r\n    // k 是给定的 n 个数字；每个 query 是一次独立询问的目标表格权值。\r\n    // 后面会一次性算出所有可达状态，再分别回答这些询问。\r\n    vector<int> k(n), query(m);\r\n    for (int &v : k) cin >> v;\r\n    for (int &x : query) cin >> x;\r\n\r\n    // 表格权值 = 行元素之和 * 列元素之和，询问中的 x <= 100。\r\n    // dp[a][b] 表示能否让行和为 a、列和为 b。\r\n    // 0 表示不可达；正数 k 表示最后一步把 k 放进了行；\r\n    // 负数 -k 表示最后一步把 k 放进了列。\r\n    // 这个值既表示可达性，也用于最后回溯出一种方案。\r\n    const int LIMIT = 100;\r\n    vector<vector<int>> dp(LIMIT + 1);\r\n\r\n    // 行和为 0 时，列和可以是 0~100。行和 a>0 时，\r\n    // 只保留 b<=100/a 的状态，也就是 a*b<=100。\r\n    // 超过 100 的乘积不可能成为询问的答案；后续加正数只会使乘积更大。\r\n    dp[0].resize(LIMIT + 1);\r\n    for (int a = 1; a <= LIMIT; ++a) {\r\n        dp[a].resize(LIMIT / a + 1);\r\n    }\r\n\r\n    // 还未使用任何数字时，(0,0) 可达。用 1 表示这个起点。\r\n    dp[0][0] = 1;\r\n\r\n    for (int i = 0; i < n; ++i) {\r\n        // 对于当前数字 k[i]，每个已有状态有三种选择：\r\n        // 1. 不选它：原状态保留，无须写代码；\r\n        // 2. 放进行：从 (a-k[i],b) 转移到 (a,b)；\r\n        // 3. 放进列：从 (a,b-k[i]) 转移到 (a,b)。\r\n        //\r\n        // a、b 倒序枚举：转移的起点坐标更小，尚未在这一轮更新。\r\n        // 因此每个数字最多使用一次。\r\n        for (int a = LIMIT; a >= 0; --a) {\r\n            for (int b = (int)dp[a].size() - 1; b >= 0; --b) {\r\n                // 已可达的状态保留原有路径，不必覆盖。\r\n                if (dp[a][b] != 0) continue;\r\n\r\n                // 若 (a-k[i],b) 可达，把 k[i] 放进行即可得到 (a,b)。\r\n                if (a >= k[i] && dp[a - k[i]][b] != 0) {\r\n                    dp[a][b] = k[i];\r\n                    continue;\r\n                }\r\n\r\n                // 否则尝试把 k[i] 放进列。\r\n                if (b >= k[i] && dp[a][b - k[i]] != 0) {\r\n                    dp[a][b] = -k[i];\r\n                }\r\n            }\r\n        }\r\n    }\r\n\r\n    // 预先给每个可能的权值保存一组可行的 (行和,列和)。\r\n    // 只遍历 a,b>0，因为 x>0 时行和、列和都不能为空。\r\n    pair<int, int> answer[LIMIT + 1] = {};\r\n    for (int a = 1; a <= LIMIT; ++a) {\r\n        for (int b = 1; b < (int)dp[a].size(); ++b) {\r\n            if (dp[a][b] != 0) answer[a * b] = {a, b};\r\n        }\r\n    }\r\n\r\n    for (int x : query) {\r\n        if (answer[x].first == 0) {\r\n            cout << \"No\\n\";\r\n            continue;\r\n        }\r\n\r\n        // 从 (行和,列和) 回溯到 (0,0)。\r\n        // dp[a][b]>0：最后放进了行，减去对应数字；\r\n        // dp[a][b]<0：最后放进了列，把负数加回列和。\r\n        vector<int> row, column;\r\n        auto [a, b] = answer[x];\r\n        while (a != 0 || b != 0) {\r\n            int step = dp[a][b];\r\n            if (step > 0) {\r\n                row.push_back(step);\r\n                a -= step;\r\n            } else {\r\n                column.push_back(-step);\r\n                b += step;\r\n            }\r\n        }\r\n\r\n        // 回溯得到的顺序与选数字的顺序相反，但题目允许任意顺序输出。\r\n        // x>0，因而行和、列和都大于 0，row、column 都非空。\r\n        cout << \"Yes\\n\";\r\n        cout << row.size() << ' ' << column.size() << '\\n';\r\n        for (int i = 0; i < (int)row.size(); ++i) {\r\n            if (i) cout << ' ';\r\n            cout << row[i];\r\n        }\r\n        cout << '\\n';\r\n        for (int i = 0; i < (int)column.size(); ++i) {\r\n            if (i) cout << ' ';\r\n            cout << column[i];\r\n        }\r\n        cout << '\\n';\r\n    }\r\n}\r\n"}],"statement":"/media/pages/study/ACM/daily-26-9-30.png","links":[],"hasIssues":false},{"id":"daily-26-9-29","title":"子串匹配","source":"日常训练","platform":"本地题档","date":"2026-09-29","group":"daily","category":"字符串","tags":["KMP","前缀函数","子串匹配"],"level":"进阶","summary":"原稿用 find 枚举匹配起点，再计算模式串前缀函数；复习时可改为完整 KMP 扫描。","caution":"匹配后只前进 1 位才能保留重叠出现；分析 find 的最坏复杂度。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.29-子串匹配.cpp","code":"#include <bits/stdc++.h>\r\n#include <vector>\r\nusing namespace std;\r\n\r\nint main() {\r\n    string s1,s2;\r\n    cin>>s1>>s2;\r\n    int n2=s2.size();\r\n    vector<int> ans;\r\n    size_t i = 0;\r\n\r\n    while ((i = s1.find(s2, i)) != string::npos) {\r\n        ans.push_back(i+1);\r\n        i++;\r\n    }\r\n\r\n    for (int x : ans){\r\n        cout<<x<<'\\n';\r\n    }\r\n\r\n    vector<int> pi(n2,0);\r\n\r\n    for (int i = 1, j = 0; i < n2; i++) {\r\n        while (j > 0 && s2[i] != s2[j]) {\r\n            j = pi[j - 1];\r\n        }\r\n        if (s2[i] == s2[j]) {\r\n            j++;\r\n        }\r\n        pi[i] = j;\r\n    }\r\n\r\n    for (int i = 0; i < n2; i++) {\r\n        cout << pi[i];\r\n        if (i + 1 < n2) cout << \" \";\r\n    }\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-9-29.png","links":[],"hasIssues":false},{"id":"daily-26-9-28","title":"阶乘","source":"日常训练","platform":"本地题档","date":"2026-09-28","group":"daily","category":"数学与数论","tags":["质因数分解","二分","阶乘指数"],"level":"进阶","summary":"分解 p 的质因子，用 Legendre 公式计算 n! 中的指数，再二分最小 n。","caution":"质因数分解的终止条件、p=1、剩余大质因子应独立检查。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.28-阶乘-hyper.cpp","code":"#include <bits/stdc++.h>\r\n#include <cmath>\r\n#include <vector>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nll countPrime(ll n, ll prime){\r\n    ll cnt=0;\r\n    while(n){\r\n        n/=prime;\r\n        cnt+=n;\r\n    }\r\n    return cnt;\r\n}\r\n\r\nll get_min_n(ll p,ll need,ll prime){\r\n    ll l=1,r=p;\r\n    while (l<r) {\r\n        ll mid=(l+r)/2;\r\n        if (countPrime(mid,prime)<need){\r\n            l=mid+1;\r\n        }\r\n        else{\r\n            r=mid;\r\n        }\r\n    }\r\n    return l;\r\n}\r\n\r\nvoid solve(){\r\n    ll p;\r\n    cin>>p;\r\n    ll tmp=p;\r\n    ll prime=1;\r\n    ll ans=1;\r\n    while (tmp-1 and prime<sqrt(p)) {\r\n        prime++;\r\n        if (tmp%prime!=0) continue;\r\n        ll need=0;\r\n        while (tmp%prime==0) {\r\n            need++;\r\n            tmp/=prime;\r\n        }\r\n        ans=max(ans,get_min_n(p,need,prime));\r\n    }\r\n    if (tmp>1) ans=max(ans,get_min_n(p,1,tmp));\r\n    cout<<ans;\r\n}\r\n\r\nint main() {\r\n    int T;\r\n    cin>>T;\r\n    while (T--) {\r\n        solve();\r\n        if (T) cout<<'\\n';\r\n    }\r\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"daily/AI/26.9.28-阶乘-AI.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\n// 计算 n! 中质数 prime 的总个数。\r\n// 例如：n = 10、prime = 2 时，\r\n// 例如：n = 10、prime = 2 时，数量为 10 / 2 + 10 / 4 + 10 / 8 + ... = 8。\r\n// 其中整除结果都是向下取整；后面的项用来统计含有多个 prime 的倍数。\r\nll countPrime(ll n, ll prime){\r\n    ll cnt = 0;\r\n    while (n){\r\n        n /= prime;       // 统计 prime 的倍数，每个至少含有一个 prime\r\n        cnt += n;\r\n    }\r\n    return cnt;\r\n}\r\n\r\n// 求最小的 n，使 n! 中至少含有 need 个 prime 因子。\r\n// n 越大，n! 中 prime 的个数不会减少，因此可以二分答案。\r\n// limit 用 p：因为 p! 一定包含 p 的所有质因数及其次数，答案不会超过 p。\r\nll minN(ll prime, ll need, ll limit){\r\n    ll l = 1, r = limit;\r\n    while (l < r){\r\n        ll mid = l + (r - l) / 2; // 避免直接写 (l + r) / 2 可能产生的溢出\r\n        if (countPrime(mid, prime) >= need) r = mid;\r\n        else l = mid + 1;         // mid 不满足，答案只能在右侧\r\n    }\r\n    // 此时 l == r，就是满足条件的最小 n\r\n    return l;\r\n}\r\n\r\nvoid solve(){\r\n    ll p;\r\n    cin>>p;\r\n\r\n    ll x = p;    // x 用于逐步分解质因数，保留 p 作为二分上界\r\n    ll ans = 1;  // p = 1 时没有质因数，最小正整数答案就是 1\r\n\r\n    // 试除法分解 p：每次找到一个质因数 prime，并统计它的指数 need。\r\n    // prime <= x / prime 等价于 prime * prime <= x，但这样写可避免乘法溢出。\r\n    for (ll prime = 2; prime <= x / prime; prime++){\r\n        if (x % prime != 0) continue;\r\n\r\n        ll need = 0; // prime 在 p 的质因数分解中的指数\r\n        while (x % prime == 0){\r\n            x /= prime; // 除掉一个 prime\r\n            need++;\r\n        }\r\n\r\n        // 这个质因数要求的最小 n，可能决定最终答案\r\n        ans = max(ans, minN(prime, need, p));\r\n    }\r\n\r\n    // 如果最后剩下 x > 1，那么 x 本身是一个质数，且在 p 中只出现一次。\r\n    if (x > 1) ans = max(ans, minN(x, 1, p));\r\n\r\n    // p | n! 要求 p 的每一种质因数都达到对应次数，\r\n    // 所以整体最小 n 是各质因数所需最小 n 的最大值。\r\n    cout << ans << '\\n';\r\n}\r\n\r\nint main() {\r\n    int T;\r\n    cin>>T;\r\n    while (T--) {\r\n        solve();\r\n    }\r\n}\r\n"}],"statement":"/media/pages/study/ACM/daily-26-9-28.png","links":[],"hasIssues":false},{"id":"daily-26-9-27","title":"小红树","source":"日常训练","platform":"本地题档","date":"2026-09-27","group":"daily","category":"图与树","tags":["树形DP","子树统计"],"level":"挑战","summary":"先迭代建立父子关系，逆序合并子树颜色信息，再统计删除边两侧的差异。","caution":"原稿最终枚举 i<n，没有处理编号 n 的点；对照 AI 参考核对边枚举范围。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.27-小红树-hyper.cpp","code":"#include <iostream>\n#include <string>\n#include <utility>\n#include <vector>\nusing namespace std;\nusing ll = long long;\n\nint main() {\n    int n;\n    string s;\n    cin>>n;\n    cin>>s;\n    vector<string> vals(n+1);\n    vector<vector<ll>> tree(n+1);\n\n    for (int i=1;i<=n;i++){\n        vals[i]=s[i-1];\n    } \n    \n    for (int i=1;i<n;i++){\n        ll u,v;\n        cin>>u>>v;\n        tree[u].push_back(v);\n        tree[v].push_back(u);\n    }\n    \n    vector<ll> parents(n+1,0),orders; \n    parents[1] = 0;\n    orders.push_back(1);\n\n    for (int i = 0; i < (int)orders.size(); ++i) {\n        ll u = orders[i];\n        for (ll v : tree[u]) {\n            if (v == parents[u]) continue;\n            parents[v] = u;\n            orders.push_back(v);\n        }\n    }\n\n    vector<ll> sub(n+1,0);\n    for (ll i = n - 1; i >= 0; --i) {\n        ll u = orders[i];\n        sub[u] = 1;\n        for (ll v : tree[u]){\n            if (parents[u]!=v){\n                sub[u]+=sub[v];\n                if (vals[u]==vals[v]) sub[u]--;\n            }\n        }\n    }\n\n    ll ans=0;\n    for (ll i=2;i<n;i++){\n        if (vals[i]==vals[parents[i]]){\n            ans+=llabs(sub[i]-(sub[1]-sub[i]+1));\n        }\n        else{\n            ans+=llabs(sub[i]-(sub[1]-sub[i]));\n        }\n    }\n    cout<<ans;\n}\n    "},{"name":"AI 参考","language":"C++","status":"reference","path":"daily/AI/26.9.27-小红树-AI.cpp","code":"#include <bits/stdc++.h>\nusing namespace std;\n\nusing ll = long long;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int n;\n    string color;\n    cin >> n >> color;\n\n    vector<vector<int>> tree(n + 1);\n    for (int i = 1; i < n; ++i) {\n        int u,v;\n        cin >> u >> v;\n        tree[u].push_back(v);\n        tree[v].push_back(u);\n    }\n\n    // 以 1 为根，用迭代遍历求每个节点的父节点和遍历顺序。\n    // 使用迭代，避免 n=200000 时递归过深导致栈溢出。\n    vector<int> parent(n + 1, 0), order;\n    order.reserve(n);\n    order.push_back(1);\n\n    for (int i = 0; i < (int)order.size(); ++i) {\n        int u = order[i];\n        for (int v : tree[u]) {\n            if (v == parent[u]) continue;\n            parent[v] = u;\n            order.push_back(v);\n        }\n    }\n\n    // sub[u]：以 u 为根的子树中，同色连通块的数量。\n    vector<ll> sub(n + 1, 0);\n    for (int i = n - 1; i >= 0; --i) {\n        int u = order[i];\n        sub[u] = 1;\n\n        for (int v : tree[u]) {\n            if (parent[v] != u) continue; // 只合并 u 的孩子\n\n            sub[u] += sub[v];\n            if (color[u - 1] == color[v - 1])\n                --sub[u]; // u 和孩子同色，连接后两个连通块合并成一个\n        }\n    }\n\n    // 整棵树的同色连通块数量就是根节点的子树答案。\n    ll total = sub[1];\n    ll answer = 0;\n\n    // 删除父子边 parent[u]-u 后，u 子树一侧有 sub[u] 个连通块。\n    // 若边两端同色，删除边会把一个原连通块拆成两个，另一侧数量为 total-sub[u]+1；\n    // 若边两端异色，这条边原本不连接同色块，另一侧数量为 total-sub[u]。\n    for (int u = 2; u <= n; ++u) {\n        ll oneSide = sub[u];\n        ll otherSide = total - sub[u]\n                     + (color[u - 1] == color[parent[u] - 1] ? 1 : 0);\n\n        answer += llabs(oneSide - otherSide);\n    }\n\n    cout << answer << '\\n';\n    return 0;\n}\n"}],"statement":"/media/pages/study/ACM/daily-26-9-27.png","links":[],"hasIssues":true},{"id":"daily-26-9-26","title":"多项式输出","source":"日常训练","platform":"本地题档","date":"2026-09-26","group":"daily","category":"字符串","tags":["格式化","分类讨论"],"level":"基础","summary":"按降幂拼接非零项，分别处理符号、系数 ±1、常数项与一次项。","caution":"原稿以 i==n 判断首项，首部系数为 0 时易多出加号；全零多项式也需处理。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.26-多项式输出-hyper.cpp","code":"#include <bits/stdc++.h>\r\n#include <string>\r\n#include <vector>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nint main() {\r\n    int n;\r\n    cin>>n;\r\n    string ans=\"\";\r\n\r\n    for (int i=n;i>=0;i--){\r\n        string x;\r\n        cin>>x;\r\n        if (x[0]=='0' and x.size()==1) continue;\r\n        if (x[0]=='-'){\r\n            if (x[1]=='1' and x.size()==2){\r\n                if (i==0) ans+=x;\r\n                else if (i==1) ans+=\"-x\";\r\n                else ans+=\"-x^\"+to_string(i);\r\n            }\r\n            else{\r\n                if (i==0) ans+=x;\r\n                else if (i==1) ans+=x+\"x\";\r\n                else ans+=x+\"x^\"+to_string(i);\r\n            }\r\n        }\r\n        else{\r\n            if (x[0]=='1' and x.size()==1){\r\n                if (i==n) ans+=\"x^\"+to_string(i);\r\n                else if (i==1) ans+=\"+x\";\r\n                else if (i==0) ans+=\"+1\";\r\n                else ans+=\"+x^\"+to_string(i);\r\n            }\r\n            else{\r\n                if (i==n) ans+=x+\"x^\"+to_string(i);\r\n                else if (i==0) ans+=\"+\"+x;\r\n                else if (i==1) ans+=\"+\"+x+\"x\";\r\n                else ans+=\"+\"+x+\"x^\"+to_string(i);\r\n            }\r\n        }\r\n    }\r\n\r\n    cout<<ans;\r\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"daily/AI/26.9.26-多项式输出-AI.cpp","code":"#include <bits/stdc++.h>\r\n#include <string>\r\nusing namespace std;\r\n\r\nint main() {\r\n    int n;\r\n    cin >> n;\r\n    string ans = \"\";\r\n\r\n    for (int i = n; i >= 0; i--) {\r\n        string x;\r\n        cin >> x;\r\n        if (x == \"0\") continue;\r\n\r\n        bool neg = (x[0] == '-');\r\n        string absX = neg ? x.substr(1) : x;\r\n        bool isOne = (absX == \"1\");\r\n\r\n        // 构造项的主体（不含符号）\r\n        string term;\r\n        if (i == 0) {\r\n            term = absX;\r\n        } else if (i == 1) {\r\n            term = isOne ? \"x\" : absX + \"x\";\r\n        } else {\r\n            term = isOne ? \"x^\" + to_string(i) : absX + \"x^\" + to_string(i);\r\n        }\r\n\r\n        // 处理符号\r\n        if (ans.empty()) {\r\n            if (neg) ans += \"-\";\r\n        } else {\r\n            ans += neg ? \"-\" : \"+\";\r\n        }\r\n        ans += term;\r\n    }\r\n\r\n    if (ans.empty()) ans = \"0\";\r\n    cout << ans;\r\n    return 0;\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-9-26.png","links":[],"hasIssues":true},{"id":"daily-26-9-25","title":"三角形取数(Hard Version)","source":"日常训练","platform":"本地题档","date":"2026-09-25","group":"daily","category":"动态规划","tags":["网格DP","滚动数组"],"level":"进阶","summary":"从三角形底部允许的终点向上转移，每格取下层三个邻位的最大值。","caution":"不可达状态必须设负无穷；负权数据不能被默认 0 状态覆盖。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.25-三角形取数(Hard Version).cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll NEG = LLONG_MIN / 4;\r\n\r\nint main() {\r\n    int n,k;\r\n    cin>>n>>k;\r\n    vector<vector<ll>> arr(n+1,vector<ll>(2*n,0));\r\n    vector<vector<ll>> dp(2,vector<ll>(2*n,NEG));\r\n    for (int i=1;i<=n;i++){\r\n        for (int j=n-(i-1);j<=n+(i-1);j++){\r\n            cin>>arr[i][j];\r\n        }\r\n        // for (int j=1;j<2*n;j++){\r\n        //     cout<<arr[i][j]<<\" \";\r\n        // }\r\n        // cout<<'\\n';\r\n    }\r\n\r\n    for (int i=n;i>=1;i--){\r\n        if (i==n){\r\n            for (int j=n-k;j<=n+k;j++){\r\n                dp[0][j]=arr[i][j];\r\n            }\r\n        }\r\n        else{\r\n            for (int j=n-(i-1);j<=n+(i-1);j++){\r\n                dp[1][j] = max({dp[0][j], dp[0][j-1], dp[0][j+1]}) + arr[i][j];\r\n            }\r\n        }\r\n        if (i!=n) swap(dp[0],dp[1]);\r\n        // for (int i=1;i<2*n;i++){\r\n        //     cout<<dp[i]<<\" \";\r\n        // }\r\n        // cout<<'\\n';\r\n    }\r\n    cout<<dp[0][n];\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-9-25.png","links":[],"hasIssues":false},{"id":"daily-26-9-24","title":"Calling","source":"日常训练","platform":"本地题档","date":"2026-09-24","group":"daily","category":"贪心与双指针","tags":["装箱","分类讨论"],"level":"挑战","summary":"按大尺寸物品优先装入，再计算剩余空位可容纳的小尺寸物品。","caution":"每种余数情形的空位数量需独立推导，不宜仅凭面积判断。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.24-Calling-hyp.cpp","code":"#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\n\nvoid solve(){\n    ll s;\n    cin>>s;\n    vector<ll> arr(7);\n    for (int i=1;i<=6;i++) cin>>arr[i];\n\n    if (arr[6]+arr[5]+arr[4]>s) cout<<\"No\";\n    else{\n        ll k=s-(arr[6]+arr[5]+arr[4]);\n        if (k*4<arr[3]) cout<<\"No\";\n        else{\n            k-=(arr[3]+3)/4;\n            if (k*9<=arr[2]){\n                arr[2]-=k*9;\n            }\n            else{\n                arr[1]-=(k*9-arr[2])*4;\n                arr[2]=0;\n            }\n\n            if (arr[3]%4==3){\n                if (arr[2]>0){\n                    arr[2]-=1;\n                    arr[1]-=5;\n                }\n                else{\n                    arr[1]-=9;\n                }\n            }\n            else if (arr[3]%4==2){\n                if (arr[2]<=3){\n                    arr[1]-=18-4*arr[2];\n                    arr[2]=0;\n                }\n                else{\n                    arr[2]-=3;\n                    arr[1]-=6;\n                }\n            }\n            else if (arr[3]%4==1){\n                if (arr[2]<=5){\n                    arr[1] -= 27 - 4 * arr[2];\n                    arr[2]=0;\n                }\n                else{\n                    arr[2]-=5;\n                    arr[1]-=7;\n                }\n            }\n\n            if (arr[2] <= arr[4] * 5) {\n                arr[1] -= (arr[4] * 5 - arr[2]) * 4;\n                arr[2] = 0;\n            }\n            arr[1]-=11*arr[5];\n            if (arr[2]<=0 and arr[1]<=0) cout<<\"Yes\";\n            else cout<<\"No\";\n        }\n    }\n}\n\nint main() {\n    ll T;\n    cin>>T;\n\n    while (T--) {\n        solve();\n        if (T) cout<<'\\n';\n    }\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"daily/AI/26.9.24-Calling-AI.cpp","code":"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nusing ll = long long;\n\nvoid solve() {\n    ll s;\n    cin >> s;\n\n    vector<ll> arr(7);\n    for (int i = 1; i <= 6; ++i) cin >> arr[i];\n\n    // 先给 6、5、4 边长的方块各分配一个框。\n    ll boxes = arr[6] + arr[5] + arr[4];\n\n    // 5x5 框里最多还能放 11 个 1x1。\n    ll space1 = arr[5] * 11;\n\n    // 每个 4x4 框最多还能放 5 个 2x2。\n    ll used2 = min(arr[2], arr[4] * 5);\n    arr[2] -= used2;\n    // 4x4 框剩下的面积可用 1x1 填充。\n    space1 += arr[4] * 20 - used2 * 4;\n\n    // 3x3 每 4 个占一个框；最后不足 4 个的单独处理。\n    boxes += arr[3] / 4;\n    ll rem3 = arr[3] % 4;\n    if (rem3 > 0) {\n        ++boxes;\n\n        // 该框还能放的 2x2 数量：1/2/3 个 3x3 时分别是 5/3/1。\n        ll capacity2 = (rem3 == 1 ? 5 : rem3 == 2 ? 3 : 1);\n        used2 = min(arr[2], capacity2);\n        arr[2] -= used2;\n\n        // 该框剩余面积由 1x1 填充。\n        space1 += 36 - rem3 * 9 - used2 * 4;\n    }\n\n    // 剩余 2x2 每 9 个需要一个新框，最后一个框可放 1x1。\n    boxes += (arr[2] + 8) / 9;\n    if (arr[2] % 9 > 0)\n        space1 += 36 - (arr[2] % 9) * 4;\n\n    // 用已有空位放 1x1，剩余的每 36 个需要一个新框。\n    arr[1] = max(0LL, arr[1] - space1);\n    boxes += (arr[1] + 35) / 36;\n\n    cout << (boxes <= s ? \"Yes\" : \"No\");\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    ll T;\n    cin >> T;\n    while (T--) {\n        solve();\n        if (T) cout << '\\n';\n    }\n    return 0;\n}\n"}],"statement":"/media/pages/study/ACM/daily-26-9-24.png","links":[],"hasIssues":false},{"id":"daily-26-9-23","title":"小跳蛙","source":"日常训练","platform":"本地题档","date":"2026-09-23","group":"daily","category":"贪心与双指针","tags":["双指针","倍增","函数复合"],"level":"挑战","summary":"先用双指针建立每个点的一次跳转，再按跳跃次数的二进制位复合映射。","caution":"等距离时的选择规则必须与题面一致；倍增时使用独立 nextJump。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.23-小跳蛙.cpp","code":"#include <iostream>\r\n#include <cstdio>\r\n#include <cstring> \r\n#include <algorithm>\r\n#include <vector>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\n\r\nint main(){\r\n    ll n,m,k;\r\n    cin>>n>>k>>m;\r\n    vector<ll> p(n+1),arr(n+1);\r\n    ll l,r;\r\n\r\n\tfor (int i = 1; i <= n; i ++ ){\r\n        cin>>arr[i];\r\n\t}\r\n\t\r\n    l=1;\r\n    r=k+1;\r\n    p[1]=k+1;\r\n    for (int i=2;i<=n;i++){\r\n        while (r<n and arr[i]-arr[l]>arr[r+1]-arr[i]) {\r\n            l++;\r\n            r++;\r\n        }\r\n        p[i]=(arr[i]-arr[l]>=arr[r]-arr[i]) ? l : r;\r\n    }\r\n\r\n    vector<int> jump(n + 1), nextJump(n + 1), ans(n + 1);\r\n\r\n    // jump[i] 表示从 i 跳 1 次到达的位置\r\n    for (int i = 1; i <= n; ++i) {\r\n        jump[i] = p[i];\r\n        ans[i] = i; \r\n    }\r\n\r\n    while (m > 0) {\r\n        // 当前二进制位是 1，就应用对应的跳跃步数\r\n        if (m & 1) {\r\n            for (int i = 1; i <= n; ++i)\r\n                ans[i] = jump[ans[i]];\r\n        }\r\n\r\n        m >>= 1;\r\n        if (m == 0) break;\r\n\r\n        // 把跳跃步数翻倍：连续跳两次 jump\r\n        for (int i = 1; i <= n; ++i)\r\n            nextJump[i] = jump[jump[i]];\r\n\r\n        jump.swap(nextJump);\r\n    }\r\n\r\n    for (int i = 1; i <= n; ++i){\r\n        cout << ans[i] << (i == n ? '\\n' : ' ');\r\n    }\r\n    // cout<<'\\n'<<\"P:\";\r\n    // for (int i=1;i<=n;i++){\r\n    //     cout<<p[i]<<\" \";\r\n    // }\r\n    // cout<<'\\n';\r\n\r\n\treturn 0;\r\n}\r\n"}],"statement":"/media/pages/study/ACM/daily-26-9-23.png","links":[],"hasIssues":false},{"id":"daily-26-9-22","title":"数树","source":"日常训练","platform":"本地题档","date":"2026-09-22","group":"daily","category":"数学与数论","tags":["二叉树","二进制","等比数列"],"level":"进阶","summary":"分离完整树层数与剩余节点，把剩余数量按二进制拆开累计贡献。","caution":"原文件仅定义 solve，缺少 main；先补入口再提交。移位上界与取模时机也需检查。","versions":[{"name":"未完成稿","language":"C++","status":"incomplete","path":"daily/hyper/26.9.22-二叉树-数树.cpp","code":"/*\r\n先求出n个点能组成的最大的完全二叉树的高度h\r\n高度为h时，比h-1时ans多了一个等比数列，计算过程如下\r\n第h排有2的h-1次方个点，令t=1LL<<(h-1)，每个点单个存在有t个，两个一起有t/2个，四个一起有t/4个，一直递减到1个，一共(1LL<<h)-1个\r\n所以ans增加了(1LL<<h)-1，\r\n把1->h的所有高度增加的值累加起来\r\n再看剩下的k=n-（(1LL<<h)-1）个点，\r\nt=1LL<<i\r\n用二进制比对每个(t&k)为真的位置\r\n这时满树的高度h=i+1\r\nans又能加上(1LL<<h)-1;\r\n得到答案\r\n作者：hyper152\r\n链接：https://www.nowcoder.com/discuss/931973354746105856?sourceSSR=users\r\n来源：牛客网\r\n*/\r\n#include <bits/stdc++.h>\r\n#include <cmath>\r\nusing namespace std;\r\nusing ll = long long;\r\nll INF=1e9+7;\r\n\r\nvoid solve(){\r\n    ll n;\r\n    cin>>n;\r\n    ll h = 0;\r\n    while ((1LL << (h + 1)) - 1 <= n) {\r\n        h++;\r\n    }\r\n\r\n    ll ans=0;\r\n    for (int i=1;i<=h;i++){\r\n        ans+=(1LL<<i)-1;\r\n    }\r\n\r\n    ll k=n-((1LL << h)-1);\r\n    ll i=0;\r\n    while (k!=0) {\r\n        ll t=1LL<<i;\r\n        if (t & k){\r\n            ans+=(1LL<<(i+1))-1;\r\n            k-=t;\r\n        } \r\n        i++;\r\n    }\r\n    \r\n    ans%=INF;\r\n    cout<<ans<<'\\n';\r\n}\r\n\r\n\r\n\r\n"}],"statement":"/media/pages/study/ACM/daily-26-9-22.png","links":[{"label":"源码内的牛客题解链接","url":"https://www.nowcoder.com/discuss/931973354746105856"}],"hasIssues":true},{"id":"daily-26-9-21","title":"Cidoai的植物","source":"日常训练","platform":"本地题档","date":"2026-09-21","group":"daily","category":"模拟与实现","tags":["随机数","二维数组"],"level":"进阶","summary":"按题面伪随机生成器产生操作，在网格中模拟填充和删除并计算异或校验。","caution":"原稿把 op==2 嵌在 op==1 分支内，删除操作无法触发；行列下标范围也需要核对。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.21-Cidoai的植物.cpp","code":"#include <iostream>\r\n#include <bits/stdc++.h>\r\n#include <vector>\r\nusing ll = long long;\r\nusing namespace std;\r\n\r\nunsigned seed;\r\nunsigned rnd(){\r\n\tunsigned ret=seed;\r\n\tseed^=seed<<13;\r\n\tseed^=seed>>17;\r\n\tseed^=seed<<5;\r\n\treturn ret;\r\n}\r\n\r\nint main() {\r\n    ll n,m,k;\r\n    cin>>n>>m>>k>>seed;\r\n    \r\n    vector<ll> op(k+1),i(k+1),x(k+1),a(k+1),b(k+1);\r\n    vector<vector<ll>> garden(n+1,vector<ll>(m+1,0));\r\n\r\n    for (int t=1;t<=k;t++){\r\n        op[t]=(rnd()%2)+1;\r\n        if (op[t]==1){\r\n            i[t]=(rnd()%m) + 1;\r\n            x[t]=(rnd()%(n*m)) + 1;\r\n            for (int j=1;j<=n;j++){\r\n                if (garden[i[t]][j]==0) garden[i[t]][j]=x[t];\r\n            }\r\n        if (op[t]==2){\r\n            a[t]=(rnd()%n) + 1;\r\n            b[t]=(rnd()%m) + 1;\r\n\r\n            if (garden[a[t]][b[t]]!=0) garden[a[t]][b[t]]=0;\r\n            }\r\n        }\r\n    }\r\n\r\n    ll ans=0;\r\n    for (int i=1;i<=n;i++){\r\n        for (int j=1;j<=m;j++){\r\n            ans=ans^(garden[i][j]*((i-1)*m+j));\r\n        }\r\n    }\r\n\r\n    cout<<ans;\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-9-21.png","links":[],"hasIssues":true},{"id":"daily-26-9-20","title":"讨厌鬼进货","source":"日常训练","platform":"本地题档","date":"2026-09-20","group":"daily","category":"贪心与双指针","tags":["逐项上界","求和"],"level":"基础","summary":"逐项取两种限制的较小值求可供货总量，再与总需求取最小值。","caution":"累计量可能超过 int，使用 long long。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.20-讨厌鬼进货.cpp","code":"#include <bits/stdc++.h>\r\n#include <vector>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nint main() {\r\n    int n,x;\r\n    cin>>n>>x;\r\n    vector<ll> a(n),b(n);\r\n    for (int i=0;i<n;i++) cin>>a[i];\r\n    for (int i=0;i<n;i++) cin>>b[i];\r\n    \r\n    ll sum=0;\r\n    for (int i=0;i<n;i++) sum+=min(a[i],b[i]);\r\n\r\n    if (sum<x) cout<<sum;\r\n    else cout<<x;\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-9-20.png","links":[],"hasIssues":false},{"id":"daily-26-9-19","title":"分割序列","source":"日常训练","platform":"本地题档","date":"2026-09-19","group":"daily","category":"数学与数论","tags":["乘法原理","字符串"],"level":"进阶","summary":"按相邻 1 之间连续 0 的长度分解选择数，独立段的方案相乘。","caution":"首尾零段与中间零段的计数规则不同。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.19-分割序列.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nll INF=1e9+7;\r\n\r\nint main() {\r\n    int n;\r\n    cin>>n;\r\n    string s;\r\n    cin>>s;\r\n    ll ans=1;\r\n    ll tmp=0;\r\n    bool iffirst=true;\r\n    for (int i=0;i<n;i++){\r\n        if (s[i]=='0'){\r\n            tmp++;\r\n        }\r\n        else{\r\n            if (iffirst){\r\n                tmp=0;\r\n                iffirst=false;\r\n            }\r\n            else{\r\n                ans*=(tmp+1);\r\n                ans%=INF;\r\n                tmp=0;\r\n            }\r\n        }\r\n    }\r\n    if (s.size()==1) ans=0;\r\n    cout<<ans;\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-9-19.png","links":[],"hasIssues":false},{"id":"daily-26-9-18","title":"完美异或","source":"日常训练","platform":"本地题档","date":"2026-09-18","group":"daily","category":"构造","tags":["异或","不变量"],"level":"基础","summary":"利用 0 的异或恒等性质，把贡献集中到一个元素，构造其余为 0。","caution":"提交前回到题面确认元素范围与是否允许 0。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.18-异或-完美异或.cpp","code":"/*\r\n只需让非末尾的全部为0，最后一个数字为n就行，，，，\r\n*/\r\n#include <bits/stdc++.h>\r\n#include <vector>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nvoid solve(){\r\n    ll n;\r\n    cin>>n;\r\n    for (int i=0;i<n-1;i++) cout<<0<<\" \";\r\n    cout<<n;\r\n    // ll i=0;\r\n    // vector<ll> arr(n+1,0);\r\n\r\n    // while ((1LL<<i)<=n) {\r\n    //     if ((1LL<<i)&n) arr[n]^=(1LL<<i);\r\n    //     i++;\r\n    // }\r\n\r\n    // for (int i=1;i<=n;i++){\r\n    //     cout<<arr[i];\r\n    //     if (i!=n) cout<<\" \";\r\n    // }\r\n}  \r\n\r\nint main() {\r\n    int T;\r\n    cin>>T;\r\n    while (T--) {\r\n        solve();\r\n        if (T) cout<<'\\n';\r\n    }\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-9-18.png","links":[],"hasIssues":false},{"id":"daily-26-9-17","title":"核心信任者","source":"日常训练","platform":"本地题档","date":"2026-09-17","group":"daily","category":"图与树","tags":["Tarjan","强连通分量","缩点"],"level":"挑战","summary":"Tarjan 求强连通分量，缩点后检查出度为 0 的分量并统计候选。","caution":"原稿在栈内已访问邻点分支使用 low[v]，标准写法使用 dfn[v]；对照 AI 参考复核强连通分量边界。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.17-核心信任者-hyper.cpp","code":"#include <bits/stdc++.h>\n#include <stack>\n#include <vector>\nusing namespace std;\nusing ll = long long;\n\nll n,m,timer=0,scc_count=0;\nvector<vector<ll>> adj;\nvector<ll> low,dfn;\nvector<int> scc_id;\nvector<int> scc_size;\nstack<ll> st;\nvector<bool> on_stack;\n\nvoid tarjan(int u){\n    timer++;\n    dfn[u]=low[u]=timer;\n    st.push(u);\n    on_stack[u]=true;\n\n    for (ll v : adj[u]){\n        if (dfn[v]==0){\n            tarjan(v);\n            low[u] = min(low[u], low[v]);\n        }\n        else if (on_stack[v]){\n            low[u]=min(low[u],low[v]);\n        }\n    }\n\n    if (dfn[u]==low[u]){\n        scc_count++;\n        while (true) {\n            ll v=st.top();\n            st.pop();\n            on_stack[v]=false;\n            scc_id[v]=scc_count;\n            scc_size[scc_count]++;\n            if (v==u) break;    \n        }\n    }\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    cin>>n>>m;\n\n    adj.resize(n + 1);\n    dfn.assign(n + 1, 0);\n    low.assign(n + 1, 0);\n    scc_id.assign(n + 1, 0);\n    scc_size.assign(n + 1, 0);\n    on_stack.assign(n + 1, false);\n\n    for (int i=1;i<=m;i++){\n        ll u,v;\n        cin>>u>>v;\n        adj[u].push_back(v);\n    }\n\n    for (int i = 1; i <= n; ++i) {\n        if (dfn[i] == 0){\n            tarjan(i);\n        } \n    }\n\n    vector<int> out_degree(scc_count + 1, 0);\n\n    for (ll u=1;u<=n;u++){\n        for (ll v : adj[u]){\n            if (scc_id[v]!=scc_id[u]){\n                out_degree[scc_id[u]]++;\n            }\n        }\n    }\n\n    ll sink_count=0;\n    ll sink_id;\n    for (ll i=1;i<=scc_count;i++){\n        if (out_degree[i]==0){\n            sink_count++;\n            sink_id=i;\n        }\n    }\n\n    cout << (sink_count == 1 ? scc_size[sink_id] : 0);\n}\n"},{"name":"AI 参考","language":"C++","status":"reference","path":"daily/AI/26.9.17-核心信任者-AI.cpp","code":"#include <bits/stdc++.h>\nusing namespace std;\n\nint n, m;\nint timer = 0;      // DFS 访问序号，每访问一个新节点就加 1\nint scc_count = 0;  // 已找到的强连通分量数量\nvector<vector<int>> adj; // 邻接表：adj[u] 存 u 直接信任的员工，边 u -> v 表示 u 信任 v\nvector<int> dfn;         // dfn[u]：u 第一次被 DFS 访问时的序号；0 表示还没访问\nvector<int> low;         // low[u]：从 u 的 DFS 子树出发，能回到的最早访问序号\nvector<int> scc_id;      // scc_id[u]：员工 u 所属的强连通分量编号\nvector<int> scc_size;    // scc_size[id]：编号为 id 的分量包含多少名员工\nstack<int> st;           // 保存已访问但还没有归入某个分量的员工\nvector<bool> on_stack;   // on_stack[u]：u 当前是否还在 Tarjan 栈中\n\n// Tarjan 算法的 DFS（Depth-First Search，深度优先搜索）。\n// 函数结束时，会在需要时把一个完整的强连通分量从栈中取出。\nvoid tarjan(int u) {\n    // 第一次访问 u：dfn 和 low 都先设为当前访问序号。\n    dfn[u] = low[u] = ++timer;\n    st.push(u);\n    on_stack[u] = true;\n\n    for (int v : adj[u]) {\n        if (dfn[v] == 0) {\n            // v 未访问，沿着边 u -> v 继续 DFS。\n            tarjan(v);\n            // v 搜索完成后，若 v 能回到更早访问的栈内节点，u 也可以经 v 回去。\n            low[u] = min(low[u], low[v]);\n        } else if (on_stack[v]) {\n            // v 已访问且仍在栈中，u 可以通过这条边连回 v。\n            // 此处用 dfn[v] 更新，因为这是指向已访问节点的边。\n            low[u] = min(low[u], dfn[v]);\n        }\n        // 若 v 已访问但不在栈中，它已属于其他分量，不能用来更新 low[u]。\n    }\n\n    // low[u] == dfn[u] 表示 u 无法回到比自己更早访问的栈内节点，\n    // 因此 u 是一个强连通分量的根；栈中 u 上方的节点和 u 属于同一分量。\n    if (dfn[u] == low[u]) {\n        ++scc_count;\n        int v;\n        do {\n            v = st.top();\n            st.pop();\n            on_stack[v] = false;       // 已归入分量，不再留在 Tarjan 栈中\n            scc_id[v] = scc_count;     // 记录员工所属的分量编号\n            ++scc_size[scc_count];     // 统计这个分量中的员工人数\n        } while (v != u);\n    }\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    cin >> n >> m;\n\n    // 员工编号为 1..n，因此数组开 n+1 个位置，0 号位置不用。\n    adj.resize(n + 1);\n    dfn.assign(n + 1, 0);\n    low.assign(n + 1, 0);\n    scc_id.assign(n + 1, 0);\n    scc_size.assign(n + 1, 0);\n    on_stack.assign(n + 1, false);\n\n    // 读入 m 条直接信任关系，并按有向边存储。\n    for (int i = 0; i < m; ++i) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n    }\n\n    // 图可能不连通，不能只从员工 1 开始；每个未访问节点都启动一次 DFS。\n    for (int i = 1; i <= n; ++i) {\n        if (dfn[i] == 0)\n            tarjan(i);\n    }\n\n    // 把每个强连通分量看作缩点图中的一个点。\n    // 统计跨分量的信任边：只要有边指向其他分量，该分量的出度就大于 0。\n    vector<int> out_degree(scc_count + 1, 0);\n    for (int u = 1; u <= n; ++u) {\n        for (int v : adj[u]) {\n            if (scc_id[u] != scc_id[v])\n                ++out_degree[scc_id[u]];\n        }\n    }\n\n    // 出度为 0 的分量叫汇点分量，它没有信任边指向其他分量。\n    // 缩点图是有向无环图：若汇点唯一，所有分量最终都能到达它；\n    // 汇点内部员工互相可达，所以其中每位员工都被所有人信任。\n    // 若汇点不唯一，不同汇点之间无法互相到达，因此没有核心信任者。\n    int sink_count = 0;\n    int sink_id = -1;\n    for (int id = 1; id <= scc_count; ++id) {\n        if (out_degree[id] == 0) {\n            ++sink_count;\n            sink_id = id;\n        }\n    }\n\n    cout << (sink_count == 1 ? scc_size[sink_id] : 0) << '\\n';  \n    return 0;\n}\n"}],"statement":"/media/pages/study/ACM/daily-26-9-17.png","links":[],"hasIssues":true},{"id":"daily-26-9-16","title":"走一个大整数迷宫","source":"日常训练","platform":"本地题档","date":"2026-09-16","group":"daily","category":"图与树","tags":["BFS","余数状态"],"level":"挑战","summary":"把格点与当前余数组合成状态 (x,y,rem)，用 BFS 求最少步数。","caution":"不能只按坐标去重；同一格点的不同余数是不同状态。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.16-BFS-走一个大整数迷宫.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\nstruct State {\r\n    int x, y, rem;\r\n};\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    int n, m, p;\r\n    cin >> n >> m >> p;\r\n\r\n    vector<vector<long long>> a(n, vector<long long>(m));\r\n    vector<vector<long long>> b(n, vector<long long>(m));\r\n\r\n    for (int i = 0; i < n; i++)\r\n        for (int j = 0; j < m; j++)\r\n            cin >> a[i][j];\r\n\r\n    // b 矩阵读入但不需要使用（因为 p^(2^b) ≡ 1 mod (p-1)）\r\n    for (int i = 0; i < n; i++)\r\n        for (int j = 0; j < m; j++)\r\n            cin >> b[i][j];\r\n\r\n    int mod = p - 1;\r\n\r\n    // 预处理每个格子的 c[i][j] % mod\r\n    // 由数论推导：c[i][j] ≡ a[i][j] (mod p-1)\r\n    vector<vector<int>> c_mod(n, vector<int>(m));\r\n    for (int i = 0; i < n; i++) {\r\n        for (int j = 0; j < m; j++) {\r\n            c_mod[i][j] = a[i][j] % mod;\r\n        }\r\n    }\r\n\r\n    // dist[x][y][rem] = 到达 (x,y) 且余数为 rem 的最短时间，-1 表示未访问\r\n    vector<vector<vector<int>>> dist(n, vector<vector<int>>(m, vector<int>(mod, -1)));\r\n\r\n    queue<State> q;\r\n    int start_rem = c_mod[0][0];\r\n    dist[0][0][start_rem] = 0;\r\n    q.push({0, 0, start_rem});\r\n\r\n    int dx[] = {-1, 1, 0, 0};\r\n    int dy[] = {0, 0, -1, 1};\r\n\r\n    while (!q.empty()) {\r\n        State cur = q.front();\r\n        q.pop();\r\n\r\n        int x = cur.x, y = cur.y, rem = cur.rem;\r\n        int time = dist[x][y][rem];\r\n\r\n        // 到达出口且余数为 0\r\n        if (x == n - 1 && y == m - 1 && rem == 0) {\r\n            cout << time << \"\\n\";\r\n            return 0;\r\n        }\r\n\r\n        for (int d = 0; d < 4; d++) {\r\n            int nx = x + dx[d];\r\n            int ny = y + dy[d];\r\n\r\n            if (nx >= 0 && nx < n && ny >= 0 && ny < m) {\r\n                // 注意 mod 可能为 1（当 p=2 时），此时 nrem 恒为 0\r\n                int nrem = (rem + c_mod[nx][ny]) % mod;\r\n                if (dist[nx][ny][nrem] == -1) {\r\n                    dist[nx][ny][nrem] = time + 1;\r\n                    q.push({nx, ny, nrem});\r\n                }\r\n            }\r\n        }\r\n    }\r\n\r\n    cout << -1 << \"\\n\";\r\n    return 0;\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-9-16.png","links":[],"hasIssues":false},{"id":"daily-26-9-15","title":"小红的区间构造","source":"日常训练","platform":"本地题档","date":"2026-09-15","group":"daily","category":"构造","tags":["数学","区间端点"],"level":"进阶","summary":"先推导可行区间范围，再把多出的长度分配到左右端点。","caution":"检查可行性上下界与端点是否仍满足题目的正数限制。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.15-构造-数学-小红的区间构造.cpp","code":"#include <iostream>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nint main() {\r\n    ll n,k,x;\r\n    cin>>n>>k>>x;\r\n\r\n    if (k<(n-1)*x+1 || k>(n+1)*x-1){cout<<\"-1\";}\r\n    else{\r\n        ll l,r;\r\n        ll lk=(k-((n-1)*x+1))/2;\r\n        ll rk=(k-((n-1)*x+1))-lk;\r\n        l=x-lk;\r\n        r=n*x+rk;\r\n        cout << l << \" \" << r << '\\n';\r\n    }\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-9-15.png","links":[],"hasIssues":false},{"id":"daily-26-9-14","title":"无关(relationship)","source":"日常训练","platform":"本地题档","date":"2026-09-14","group":"daily","category":"数学与数论","tags":["容斥","子集枚举"],"level":"挑战","summary":"枚举条件子集，用最小公倍数统计倍数数量，按子集奇偶进行容斥。","caution":"乘积或 lcm 可能溢出，先做除法界限判断再相乘。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.14-容斥原理-无关(relationship).cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nll k;\r\nvector<ll> arr;\r\n\r\n// 计算 [1, n] 中与 A 无关的正整数个数\r\nll solve(ll n) {\r\n    if (n <= 0) return 0;\r\n    ll ans = 0;\r\n    for (ll mask = 0; mask < (1LL << k); mask++) {\r\n        ll prod = 1;\r\n        int bits = 0;\r\n        bool overflow = false;\r\n        for (int i = 0; i < k; i++) {\r\n            if (mask & (1LL << i)) {\r\n                bits++;\r\n                if (prod > n / arr[i]) {  // 防溢出\r\n                    overflow = true;\r\n                    break;\r\n                }\r\n                prod *= arr[i];\r\n            }\r\n        }\r\n        if (overflow) continue;\r\n        ll cnt = n / prod;\r\n        if (bits % 2 == 0) ans += cnt;  // 偶数个：加\r\n        else               ans -= cnt;  // 奇数个：减\r\n    }\r\n    return ans;\r\n}\r\n\r\nint main() {\r\n    ll L, R;\r\n    cin >> L >> R >> k;\r\n    arr.resize(k);\r\n    for (auto& x : arr) cin >> x;\r\n\r\n    cout << solve(R) - solve(L - 1) << endl;\r\n    return 0;\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-9-14.png","links":[],"hasIssues":false},{"id":"daily-26-9-13","title":"炮兵阵地","source":"日常训练","platform":"本地题档","date":"2026-09-13","group":"daily","category":"动态规划","tags":["状压DP","行状态"],"level":"挑战","summary":"枚举单行合法摆放掩码，结合地形与前两行状态进行转移。","caution":"检查横向间隔、相邻两行冲突以及不可达状态初始化。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.13-状压DP-炮兵阵地.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll=long long;\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    int n, m;\r\n    cin >> n >> m;\r\n\r\n    vector<int> terrain(n + 1, 0); // 存储每一行的地形，H记为1，P记为0\r\n    vector<int> valid_states; // 存储所有合法的单行状态\r\n    vector<int> state_count(1 << m, 0); // 存储每个状态中1的个数\r\n\r\n    // 读取地图并压缩地形\r\n    for (int i = 1; i <= n; i++) {\r\n        string s;\r\n        cin >> s;\r\n        for (int j = 0; j < m; j++) {\r\n            if (s[j] == 'H') {\r\n                terrain[i] |= (1 << j); // 山地置1\r\n            }\r\n        }\r\n    }\r\n\r\n    // 1. 预处理所有合法的单行状态\r\n    for (int state = 0; state < (1 << m); state++) {\r\n        // 检查是否有相邻或隔一个的炮兵\r\n        if ((state & (state << 1)) || (state & (state << 2))) continue;\r\n        valid_states.push_back(state);\r\n        // 计算该状态中1的个数\r\n        int temp = state, c = 0;\r\n        while (temp) {\r\n            c += (temp & 1);\r\n            temp >>= 1;\r\n        }\r\n        state_count[state] = c;\r\n    }\r\n\r\n    // 用 vector 定义三维 dp 数组（滚动数组）\r\n    // dp[当前行][当前行状态][上一行状态]\r\n    vector<vector<vector<int>>> dp(2, vector<vector<int>>(1 << m, vector<int>(1 << m, 0)));\r\n\r\n    int ans = 0;\r\n\r\n    // 2. 动态规划\r\n    for (int i = 1; i <= n; i++) {\r\n        int cur = i & 1;         // 当前行在滚动数组中的下标\r\n        int prev1 = (i - 1) & 1; // 上一行\r\n\r\n        // 清空当前行的 dp 状态\r\n        for (int j = 0; j < (1 << m); j++) {\r\n            for (int k = 0; k < (1 << m); k++) {\r\n                dp[cur][j][k] = 0;\r\n            }\r\n        }\r\n\r\n        // 枚举当前行状态 j\r\n        for (int j : valid_states) {\r\n            if (j & terrain[i]) continue; // 地形冲突\r\n\r\n            // 枚举上一行状态 k\r\n            for (int k : valid_states) {\r\n                if (i >= 2 && (k & terrain[i - 1])) continue; // 地形冲突\r\n                if (j & k) continue; // 当前行和上一行冲突\r\n\r\n                // 枚举上上行状态 l\r\n                for (int l : valid_states) {\r\n                    if (i >= 3 && (l & terrain[i - 2])) continue; // 地形冲突\r\n                    if (j & l) continue; // 上上行和当前行冲突\r\n                    if (k & l) continue; // 上上行和上一行冲突\r\n\r\n                    // 状态转移\r\n                    if (i == 1) {\r\n                        dp[cur][j][k] = max(dp[cur][j][k], state_count[j]);\r\n                    } else {\r\n                        dp[cur][j][k] = max(dp[cur][j][k], dp[prev1][k][l] + state_count[j]);\r\n                    }\r\n\r\n                    // 如果已经算到最后一行，更新全局答案\r\n                    if (i == n) {\r\n                        ans = max(ans, dp[cur][j][k]);\r\n                    }\r\n                }\r\n            }\r\n        }\r\n    }\r\n\r\n    // 如果只有一行，特殊处理\r\n    if (n == 1) {\r\n        for (int j : valid_states) {\r\n            if (!(j & terrain[1])) {\r\n                ans = max(ans, state_count[j]);\r\n            }\r\n        }\r\n    }\r\n\r\n    cout << ans << '\\n';\r\n    return 0;\r\n}"}],"statement":"","links":[],"hasIssues":false},{"id":"daily-26-9-12","title":"好好好数","source":"日常训练","platform":"本地题档","date":"2026-09-12","group":"daily","category":"数学与数论","tags":["进制转换","数位"],"level":"基础","summary":"不断除以 k，取余获得各个数位，维护最大的数位。","caution":"k=1 必须单独处理，防止循环不终止。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.12-进制-好好好数.cpp","code":"#include <bits/stdc++.h>\r\n#include <iostream>\r\nusing namespace std;\r\nusing ll = long long;\r\nint main() {\r\n    int T;\r\n    cin>>T;\r\n    while (T--) {\r\n        ios::sync_with_stdio(false);\r\n        cin.tie(nullptr);\r\n        ll n,k;\r\n        ll ans=0;\r\n        cin>>n>>k;\r\n\r\n        if (k == 1){cout <<\"1\";}\r\n        else{\r\n            while (n>0) {\r\n                ans=max(ans,n%k);\r\n                n=n/k;\r\n            }\r\n            cout<<ans;\r\n        }\r\n\r\n        if (T) cout<<'\\n';\r\n    }\r\n}\r\n"}],"statement":"/media/pages/study/ACM/daily-26-9-12.png","links":[],"hasIssues":false},{"id":"daily-26-9-11","title":"走廊的灯","source":"日常训练","platform":"本地题档","date":"2026-09-11","group":"daily","category":"贪心与双指针","tags":["字符串分段","贪心"],"level":"进阶","summary":"扫描连续字符段，比较相邻段的贡献，维护可取方案与最大值。","caution":"检查首尾连续 2 的特殊分支，并为贪心选择给出理由。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.11-贪心-走廊的灯.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\nint main() {\r\n    int T;\r\n    cin >> T;\r\n    while (T--) {\r\n        int n;\r\n        string s;\r\n        cin >> n >> s;\r\n\r\n        int ans = 0, mx = 0, i = 0;\r\n\r\n        while (i < n and s[i] == '2') { i++; ans++; }\r\n        mx = ans;\r\n        char tmp = (i < n) ? s[i] : 0;\r\n\r\n        while (i < n) {\r\n            if (s[i] == '2' or s[i] == tmp) {\r\n                ans++;\r\n                if (ans > mx) mx = ans;\r\n            } else {\r\n                tmp = s[i];\r\n                ans = 1;\r\n                int j = i - 1;\r\n                while (j >= 0 and s[j] == '2'){ans++;j--;}\r\n                if (ans > mx) mx = ans;\r\n            }\r\n            i++;\r\n        }\r\n        cout << mx;\r\n        if (T) cout << \"\\n\";\r\n    }\r\n    return 0;\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-9-11.jpg","links":[],"hasIssues":false},{"id":"daily-26-9-10","title":"「土」秘法地震","source":"日常训练","platform":"本地题档","date":"2026-09-10","group":"daily","category":"枚举与位运算","tags":["二维枚举","矩形覆盖"],"level":"基础","summary":"对每个被标记位置枚举能覆盖它的 k×k 窗口，并记录可行起点。","caution":"先证明复杂度适合题目规模；起点范围应限制在网格内。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.10-二维枚举-「土」秘法地震.cpp","code":"#include <bits/stdc++.h>\r\n#include <vector>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nvoid ij(int x,int y,int k,vector<vector<int>>& b,int n,int m){\r\n    for (int i=x-k+1;i<=x;i++){\r\n        for (int j=y-k+1;j<=y;j++){\r\n            if (i>=0 and j>=0 and i<=n-k and j<=m-k) b[i][j]=1;\r\n        }\r\n    }\r\n}\r\n\r\nint main() {\r\n    int n,m,k;\r\n    cin>>n>>m>>k;\r\n    vector<vector<int>> b(n-k+1,vector<int>(m-k+1,0));\r\n\r\n    for (int i=0;i<n;i++){\r\n        string x;\r\n        cin>>x;\r\n        for (int j=0;j<x.size();j++) {\r\n            char c = x[j];\r\n            if (c=='1') ij(i,j,k,b,n,m);\r\n        }\r\n    }\r\n\r\n    ll ans=0;\r\n\r\n    for (int i=0;i<n-k+1;i++){\r\n        for (int j=0;j<m-k+1;j++){\r\n            // cout<<b[i][j]<<\" \";\r\n            if (b[i][j]==1) ans++;\r\n        }\r\n        // cout<<endl;\r\n    }\r\n\r\n    cout<<ans;\r\n\r\n}\r\n"}],"statement":"/media/pages/study/ACM/daily-26-9-10.png","links":[],"hasIssues":false},{"id":"daily-26-9-9","title":"小红的双排列删除得分","source":"日常训练","platform":"本地题档","date":"2026-09-09","group":"daily","category":"动态规划","tags":["前缀和","区间DP"],"level":"进阶","summary":"记录每个值第一次出现的位置，以前缀和计算成对端点区间得分并转移。","caution":"转移从 dp[p−1] 出发，避免把已删除区间重复计算。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.9-DP-小红的双排列删除得分.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    int n;\r\n    cin >> n;\r\n\r\n    int m = 2 * n;\r\n    vector<int> pos(n + 1, 0);\r\n    vector<ll> sum(m + 1, 0);\r\n    vector<ll> dp(m + 1, 0);\r\n\r\n    for (int i = 1; i <= m; i++) {\r\n        int x;\r\n        cin >> x;\r\n\r\n        sum[i] = sum[i - 1] + x;\r\n        dp[i] = dp[i - 1];\r\n\r\n        if (pos[x] == 0) {\r\n            pos[x] = i;\r\n        } else {\r\n            int p = pos[x];\r\n            dp[i] = max(dp[i],dp[p-1]+sum[i]-sum[p-1]);\r\n        }\r\n    }\r\n\r\n    cout << dp[m] << '\\n';\r\n    return 0;\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-9-9.jpg","links":[],"hasIssues":false},{"id":"daily-26-9-8","title":"小红的陡峭值（五）hard","source":"日常训练","platform":"本地题档","date":"2026-09-08","group":"daily","category":"数学与数论","tags":["排序","贡献法","模逆元"],"level":"进阶","summary":"排序后按每个元素在两两差中的贡献系数求和，用快速幂求模逆元。","caution":"负数取模需归一化；逆元成立依赖模数与分母条件。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.8-排序-数学-小红的陡峭值（五）hard.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nconst ll MOD = 1e9 + 7;\r\n\r\nll qpow(ll a, ll b, ll mod = MOD) {\r\n    a %= mod;\r\n    ll x = 1;\r\n    while (b) {\r\n        if (b & 1) x = x * a % mod;\r\n        a = a * a % mod;\r\n        b >>= 1;\r\n    }\r\n    return x;\r\n}\r\n\r\nll inv(ll x, ll mod = MOD) {\r\n    return qpow(x, mod - 2, mod);\r\n}\r\n\r\nint main() {\r\n    ll n;\r\n    cin >> n;\r\n    vector<ll> arr(n + 1);  // 改成 n+1，1-indexed\r\n    for (ll i = 1; i <= n; i++) cin >> arr[i];\r\n    sort(arr.begin() + 1, arr.end());  // 从第1个位置开始排序\r\n    \r\n    ll ans = 2 * inv(n) % MOD;  // 先算 2/n\r\n    ll x = 0, y = -n + 1;  // y = 1-n+2*i，i从1开始\r\n    for (ll i = 1; i <= n; i++) {\r\n        x = ((x + y * arr[i]) % MOD + MOD) % MOD;  // 每一步取模，处理负数\r\n        y += 2;  // 下一个系数 +2\r\n    }\r\n    ans = ans * x % MOD;\r\n    cout << ans;\r\n    return 0;\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-9-8.jpg","links":[],"hasIssues":false},{"id":"daily-26-9-7","title":"小红的陡峭值","source":"日常训练","platform":"本地题档","date":"2026-09-07","group":"daily","category":"构造","tags":["贪心","数组填充"],"level":"进阶","summary":"先让未知位置延续邻近值，求当前陡峭值，再尝试调整端点完成目标。","caution":"全零、单元素、端点不可修改等情况需要分别验证。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.7-贪心-构造-小红的陡峭值.cpp","code":"#include <iostream>\r\n#include <vector>\r\n#include <cmath>\r\nusing namespace std;\r\n\r\nint main() {\r\n    int n;\r\n    cin >> n;\r\n    \r\n    vector<int> a(n + 1);\r\n    for (int i = 1; i <= n; i++) {\r\n        cin >> a[i];\r\n    }\r\n    \r\n    // 找到第一个非零元素的位置\r\n    int firstNonZero = 1;\r\n    while (firstNonZero <= n && a[firstNonZero] == 0) {\r\n        firstNonZero++;\r\n    }\r\n    \r\n    // 如果全是0，构造一个陡峭值为1的数组\r\n    if (firstNonZero > n) {\r\n        a[1] = 2;\r\n        firstNonZero = 1;\r\n    }\r\n    \r\n    vector<int> b = a;\r\n    \r\n    // 填充第一个非零元素前面的0\r\n    for (int j = 1; j < firstNonZero; j++) {\r\n        b[j] = a[firstNonZero];\r\n    }\r\n    \r\n    // 从左到右填充后面的0\r\n    for (int j = 1; j <= n; j++) {\r\n        if (b[j] == 0) {\r\n            b[j] = b[j - 1];\r\n        }\r\n    }\r\n    \r\n    // 计算陡峭值\r\n    int steep = 0;\r\n    for (int i = 2; i <= n; i++) {\r\n        steep += abs(b[i] - b[i - 1]);\r\n    }\r\n    \r\n    // 根据陡峭值输出结果\r\n    if (steep > 1) {\r\n        cout << \"-1\";\r\n    } \r\n    else if (steep == 1) {\r\n        for (int i = 1; i <= n; i++) {\r\n            cout << b[i] << \" \";\r\n        }\r\n    } \r\n    else { // steep == 0\r\n        // 尝试修改首尾元素使陡峭值变为1\r\n        if (a[1] != 0 && a[n] != 0) {\r\n            cout << \"-1\";\r\n        } else {\r\n            if (a[1] == 0) {\r\n                b[1] = b[2] - 1;\r\n                if (b[1] == 0) {\r\n                    b[1] = 2;\r\n                }\r\n            } else if (a[n] == 0) {\r\n                b[n] = b[n - 1] - 1;\r\n                if (b[n] == 0) {\r\n                    b[n] = 2;\r\n                }\r\n            }\r\n            \r\n            for (int i = 1; i <= n; i++) {\r\n                cout << b[i] << \" \";\r\n            }\r\n        }\r\n    }\r\n    \r\n    return 0;\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-9-7.jpg","links":[],"hasIssues":false},{"id":"daily-26-9-6","title":"小红的区间修改（二）","source":"日常训练","platform":"本地题档","date":"2026-09-06","group":"daily","category":"数据结构","tags":["ODT","区间赋值","map"],"level":"挑战","summary":"用有序映射维护常值区间边界，split 后删除旧段，并同步各值覆盖长度。","caution":"原稿 Split 直接读取 lower_bound 的结果，末尾边界可能为 end；复习时补哨兵并验证边界。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.9.6-ODT-小红的区间修改（二）.cpp","code":"#include <iostream>\r\n#include <map>\r\nusing namespace std;\r\n\r\nconst int MAXI = 1e5;\r\n\r\nint q;\r\n\r\nmap<int, int> mp = {{1, 0}};\r\nmap<int, int> cnt = {{0, MAXI + 1}};\r\n\r\nvoid Add(int x, int v) {\r\n    cnt[x] += v;\r\n}\r\n\r\nvoid Remove(int x, int v) {\r\n    auto it = cnt.find(x);\r\n    if (!(it->second -= v)) {\r\n        cnt.erase(it);\r\n    }\r\n}\r\n\r\nauto Split(int x) {\r\n    auto it = mp.lower_bound(x);\r\n    if (it->first == x) {\r\n        return it;\r\n    }\r\n    return mp.emplace_hint(it, x, prev(it)->second);\r\n}\r\n\r\nvoid Modify(int l, int r, int x) {\r\n    r++;\r\n    auto itr = Split(r);\r\n    auto itl = Split(l);\r\n    for (auto it = itl; it != itr; it = mp.erase(it)) {\r\n        int len = next(it)->first - it->first;\r\n        Remove(it->second, len);\r\n    }\r\n    mp.emplace_hint(itr, l, x);\r\n    Add(x, r - l);\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    cin >> q;\r\n    while (q--) {\r\n        int l, r, x;\r\n        cin >> l >> r >> x;\r\n        Modify(l, r, x);\r\n        cout << cnt.size() << '\\n';\r\n    }\r\n}\r\n"}],"statement":"/media/pages/study/ACM/daily-26-9-6.jpg","links":[],"hasIssues":true},{"id":"daily-26-8-11","title":"简单题的逆袭","source":"日常训练","platform":"本地题档","date":"2026-08-11","group":"daily","category":"数学与数论","tags":["整数除法","分类讨论"],"level":"基础","summary":"对 x=0、x=1 等情况分类，使用连续整除统计层数，避免浮点对数。","caution":"明确无解条件；y=0 与 x>y 的交界需要单独检查。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.8.11-数学-简单题的逆袭.cpp","code":"#include <bits/stdc++.h>\r\n#include <algorithm>\r\nusing namespace std;\r\n#define ll long long\r\nint main() {\r\n    int t; scanf(\"%d\",&t);\r\n    for(int i=1;i<=t;i++) {\r\n        ll x,y;\r\n        cin>>x>>y;\r\n        if(x>y) {\r\n            if(y==0) cout<<\"-1\\n\";\r\n            else printf(\"0\\n\");\r\n        }\r\n        else if(x==0 || x==1) {\r\n            printf(\"-1\\n\");\r\n        }else {\r\n            ll ans = 0;\r\n            while(y>=x) {\r\n                y/=x;\r\n                ans++;\r\n            }\r\n            cout<<ans<<endl;\r\n        }\r\n    }\r\n    return 0;\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-8-11.jpg","links":[],"hasIssues":false},{"id":"daily-26-8-10","title":"小红的数组操作","source":"日常训练","platform":"本地题档","date":"2026-08-10","group":"daily","category":"贪心与双指针","tags":["滑动窗口","前后缀最值"],"level":"进阶","summary":"用集合维护不重复窗口，同时预处理左右两侧操作成本的最小值。","caution":"集合中的值与窗口必须同步；留意空前缀和空后缀。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.8.10-双指针-小红的数组操作.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll=long long;\r\n\r\nint n;\r\nvector<ll> a;\r\n\r\nvector<ll> lf;\r\nvector<ll> rt;\r\n\r\nint main() {\r\n\r\n    cin >> n;\r\n    a.resize(n+1);\r\n    for (int i=1;i<=n;i++){\r\n        int t;\r\n        cin >>t;\r\n        a[i]=t;\r\n    }\r\n\r\n    lf.resize(n+1);\r\n    rt.resize(n+1);\r\n\r\n    for (int i=1;i<=n;i++){\r\n        lf[i]=a[i]*i;\r\n        rt[i-1]=a[i]*(n-i+1);\r\n    }\r\n\r\n    for (int i=1;i<=n-1;i++){\r\n        rt[i]=min(rt[i-1],rt[i]);\r\n    }\r\n\r\n    for (int i=n-1;i>=1;i--){\r\n        lf[i]=min(lf[i+1],lf[i]);\r\n    }\r\n\r\n    set<int> st;\r\n    ll ans = LLONG_MAX;\r\n    int l = 1;\r\n    \r\n    for (int i = 1; i <=n; i++) {\r\n        while (st.count(a[i])) {\r\n            st.erase(a[l]);\r\n            l++;\r\n        }\r\n        st.insert(a[i]);\r\n        ans=min(ans,lf[l-1]+rt[i]);\r\n    }\r\n\r\n    cout << ans << endl;\r\n    return 0;\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-8-10.jpg","links":[],"hasIssues":false},{"id":"daily-26-8-9","title":"可划分数组","source":"日常训练","platform":"本地题档","date":"2026-08-09","group":"daily","category":"动态规划","tags":["区间划分","gcd"],"level":"进阶","summary":"预处理每个位置左右最近的非互质伙伴，再用前缀 DP 枚举合法分段。","caution":"原稿存在多层枚举，分析最坏时间再尝试优化。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.8.9-DP-数论-可划分数组.cpp","code":"#include <iostream>\r\n#include <numeric>\r\n#include <vector>\r\nusing namespace std;\r\n\r\nint n;\r\nvector<int> a;\r\nvector<int> dp;\r\n\r\nvector<int> lf;\r\nvector<int> rt;\r\n\r\nvoid Solve() {\r\n    cin >> n;\r\n    a.resize(n);\r\n    for (auto& x : a) {\r\n        cin >> x;\r\n    }\r\n    lf.assign(n, -1);\r\n    rt.assign(n, n);\r\n    dp.assign(n + 1, -1);\r\n    dp[0] = 0;\r\n    for (int i = 0; i < n; i++) {\r\n        for (int j = i - 1; j > -1; j--) {\r\n            if (gcd(a[i], a[j]) > 1) {\r\n                lf[i] = j;\r\n                break;\r\n            }\r\n        }\r\n        for (int j = i + 1; j < n; j++) {\r\n            if (gcd(a[i], a[j]) > 1) {\r\n                rt[i] = j;\r\n                break;\r\n            }\r\n        }\r\n    }\r\n    for (int i = 1; i <= n; i++) {\r\n        int mini = i;\r\n        for (int j = i - 1; j > -1; j--) {\r\n            if (rt[j] >= i) {\r\n                mini = min(mini, lf[j]);\r\n            }\r\n            if (mini >= j && dp[j] != -1) {\r\n                dp[i] = max(dp[i], dp[j] + 1);\r\n            }\r\n        }\r\n    }\r\n    cout << dp[n];\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    Solve();\r\n}\r\n"}],"statement":"/media/pages/study/ACM/daily-26-8-9.jpg","links":[],"hasIssues":false},{"id":"daily-26-8-8","title":"变异蛮牛","source":"日常训练","platform":"本地题档","date":"2026-08-08","group":"daily","category":"图与树","tags":["DFS","二分染色","组合计数"],"level":"进阶","summary":"沿树边交替染色，统计与根同色的点，再使用组合计数。","caution":"递归版本在长链上可能耗尽栈；复习时考虑迭代遍历。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.8.8-树-DFS-变异蛮牛.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll=long long;\r\n\r\nstruct node{\r\n    int color;\r\n    int father;\r\n    vector<int> sons;\r\n};\r\n\r\nvoid run(int id,vector<node>& nodes,ll& sum){\r\n    int next_color=1-nodes[id].color;\r\n    if (nodes[id].color==0) sum++;\r\n    for (auto& p : nodes[id].sons){\r\n        if (p==nodes[id].father) continue;\r\n        nodes[p].color=next_color;\r\n        nodes[p].father=id;\r\n        run(p,nodes,sum);\r\n    }\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    int T;\r\n    cin>>T;\r\n    while (T--) {\r\n        int n;\r\n        cin>>n;\r\n        vector<node> nodes(n+1);\r\n        nodes[1]={0,-1};\r\n        for (int i=1;i<n;i++){\r\n            int v1,v2;\r\n            cin>>v1>>v2;\r\n            nodes[v1].sons.push_back(v2);\r\n            nodes[v2].sons.push_back(v1);\r\n        }\r\n\r\n        ll sum=0;\r\n        run(1,nodes,sum);\r\n\r\n        // for (int i=1;i<=n;i++){\r\n        //     if (nodes[i].color==0) sum++;\r\n        // }\r\n\r\n        cout<<sum*(sum-1)/2+sum<<'\\n';\r\n    }\r\n}\r\n"}],"statement":"/media/pages/study/ACM/daily-26-8-8.jpg","links":[],"hasIssues":false},{"id":"daily-26-8-7","title":"纸牌游戏","source":"日常训练","platform":"本地题档","date":"2026-08-07","group":"daily","category":"模拟与实现","tags":["枚举","比较"],"level":"基础","summary":"枚举双方两张牌的四种出牌顺序，逐局比较后累计获胜方案。","caution":"平局不会贡献正负分，方案按出牌下标区分。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.8.7-模拟-纸牌游戏.cpp","code":"#include <iostream>\r\nusing namespace std;\r\n \r\nint main(){\r\n    int t;\r\n    cin >> t;\r\n    while(t--){\r\n        int a1, a2, b1, b2;\r\n        cin >> a1 >> a2 >> b1 >> b2;\r\n        int count = 0;\r\n        count += ((a1 > b1) + (a2 > b2)) > ((a1 < b1) + (a2 < b2));\r\n        count += ((a1 > b2) + (a2 > b1)) > ((a1 < b2) + (a2 < b1));\r\n        count += ((a2 > b1) + (a1 > b2)) > ((a2 < b1) + (a1 < b2));\r\n        count += ((a2 > b2) + (a1 > b1)) > ((a2 < b2) + (a1 < b1));\r\n        cout << count << endl;\r\n    }\r\n    return 0;\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-8-7.jpg","links":[],"hasIssues":false},{"id":"daily-26-7-26","title":"2^20","source":"日常训练","platform":"本地题档","date":"2026-07-26","group":"daily","category":"枚举与位运算","tags":["二进制","有限枚举"],"level":"基础","summary":"枚举至多 20 次加一，统计二进制末尾零，用乘二补足到 2 的 20 次方的倍数。","caution":"n 已整除时返回 0；移位和常量使用足够宽的整数。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.7.26-枚举-位运算-2^20.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nbool isPowerOfTwo(ll n) {\r\n    return n > 0 and (n & (n - 1)) == 0;\r\n}\r\n\r\nvoid solve(ll n) {\r\n    // 如果已经是 2^20 的倍数\r\n    if (n % 1048576 == 0) {\r\n        cout << 0 << endl;\r\n        return;\r\n    }\r\n    \r\n    // 只关心余数部分\r\n    n %= 1048576;\r\n    \r\n    ll ans = 20;  // 答案最多 20\r\n    \r\n    // 枚举加的次数 i (0 到 20)\r\n    for (int i = 0; i <= 20; i++) {\r\n        ll x = n + i;  // 加 i 次后的数\r\n        \r\n        // 统计 x 的二进制末尾有多少个 0\r\n        int cnt = 0;\r\n        while (x % 2 == 0 && cnt < 20) {\r\n            x /= 2;\r\n            cnt++;\r\n        }\r\n        \r\n        // 还需要乘 (20 - cnt) 次\r\n        // 总操作数 = 加的次数 + 乘的次数\r\n        ans = min(ans, (ll)i + (20 - cnt));\r\n    }\r\n    \r\n    cout << ans << endl;\r\n}\r\nint main() {\r\n    int T;\r\n    cin>>T;\r\n\r\n    while (T--){\r\n        ll n;\r\n        cin>>n;\r\n        solve(n);\r\n    }\r\n}\r\n"}],"statement":"/media/pages/study/ACM/daily-26-7-26.jpg","links":[],"hasIssues":false},{"id":"daily-26-7-25","title":"小辰的智慧树","source":"日常训练","platform":"本地题档","date":"2026-07-25","group":"daily","category":"贪心与双指针","tags":["差分","贪心"],"level":"进阶","summary":"差分统计每个高度的可削次数，从高到低优先取得 2H−1 的边际收益。","caution":"剩余操作不足以处理整层时，只消耗剩余次数。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.7.25-差分-贪心-小辰的智慧树.cpp","code":"#include <iostream>\r\n#include <vector>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nconst int MAX_H = 1'000'000;\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    \r\n    int n;\r\n    ll m;\r\n    cin >> n >> m;\r\n    \r\n    vector<int> diff(MAX_H + 5, 0);\r\n    int max_h = 0;\r\n    for (int i = 0; i < n; ++i) {\r\n        int h, c;\r\n        cin >> h >> c;\r\n        if (h > c) {\r\n            diff[c + 1]++;\r\n            diff[h + 1]--;\r\n            if (h > max_h) max_h = h;\r\n        }\r\n    }\r\n    \r\n    vector<int> active(MAX_H + 5, 0);\r\n    for (int i = 1; i <= max_h; ++i) {\r\n        active[i] = active[i - 1] + diff[i];\r\n    }\r\n    \r\n    ll ans = 0;\r\n    for (int H = max_h; H >= 1 && m > 0; --H) {\r\n        int cur = active[H];\r\n        if (cur == 0) continue;\r\n        \r\n        if (m >= cur) {\r\n            ans += cur * (2LL * H - 1);\r\n            m -= cur;\r\n        } else {\r\n            ans += m * (2LL * H - 1);\r\n            m = 0;\r\n        }\r\n    }\r\n    \r\n    cout << ans;\r\n    return 0;\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-7-25.jpg","links":[],"hasIssues":false},{"id":"daily-26-7-24","title":"我不是大富翁","source":"日常训练","platform":"本地题档","date":"2026-07-24","group":"daily","category":"动态规划","tags":["余数DP","滚动数组"],"level":"进阶","summary":"把走完整圈转为对 n 的余数为 0；每步在余数状态上选择加或减。","caution":"新一轮必须清空 ndp；注意负数取模。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.7.24-DP-我不是大富翁.cpp","code":"#include <iostream>\r\n#include <numeric>\r\n#include <vector>\r\n#include <algorithm>\r\nusing namespace std;\r\n\r\nint main() {\r\n    int m, n;\r\n    cin >> n >> m;\r\n    \r\n    vector<int> arr(m);\r\n    \r\n    for (int i = 0; i < m; i++) {\r\n        cin >> arr[i];\r\n    }\r\n    \r\n    int sum = accumulate(arr.begin(), arr.end(), 0);\r\n    \r\n    if (sum % n == 0) {\r\n        cout << \"yes\" << endl;\r\n    } \r\n    else {\r\n        vector<bool> dp(n, false), ndp(n, false);\r\n        dp[0] = true;\r\n        \r\n        for (int i = 0; i < m; i++) {\r\n            fill(ndp.begin(), ndp.end(), false);\r\n            int step = arr[i] % n;\r\n            \r\n            for (int j = 0; j < n; j++) {\r\n                if (dp[j]) {\r\n                    ndp[(j + step) % n] = true;\r\n                    ndp[(j - step + n) % n] = true;\r\n                }\r\n            }\r\n            dp.swap(ndp);\r\n        }\r\n        \r\n        if (dp[0]) {\r\n            cout << \"yes\" << endl;\r\n        } else {\r\n            cout << \"no\" << endl;\r\n        }\r\n    }\r\n    \r\n    return 0;\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-7-24.jpg","links":[],"hasIssues":false},{"id":"daily-26-7-23","title":"加法入门","source":"日常训练","platform":"本地题档","date":"2026-07-23","group":"daily","category":"数学与数论","tags":["三角数","边界修正"],"level":"基础","summary":"通过三角数定位层数，再比较区间端点；先用平方根估计，随后用整数不等式修正。","caution":"平方根是估计值，检查整数溢出与临界三角数。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"daily/hyper/26.7.23-数学-加法入门.cpp","code":"#include <cmath>\r\n#include <iostream>\r\nusing namespace std;\r\n \r\nusing ll = long long;\r\n \r\nint n;\r\nll l;\r\nll r;\r\n \r\nll Ceng(ll a) {\r\n    ll res = sqrt(a * 2) + 0.5;\r\n    while (res * (res + 1) / 2 < a) {\r\n        res++;\r\n    }\r\n    while (res * (res - 1) / 2 >= a) {\r\n        res--;\r\n    }\r\n    return res;\r\n}\r\n \r\nll Lf(ll a) {\r\n    return a + Ceng(a);\r\n}\r\n \r\nvoid Solve() {\r\n    cin >> n >> l >> r;\r\n    if (Lf(l) > r) {\r\n        cout << \"Yes\\n\";\r\n        return;\r\n    }\r\n    cout << \"No\\n\";\r\n}\r\n \r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    int T;\r\n    cin >> T;\r\n    while (T--) {\r\n        Solve();\r\n    }\r\n}"}],"statement":"/media/pages/study/ACM/daily-26-7-23.jpg","links":[],"hasIssues":false},{"id":"luogu-P1027","title":"P1027 · Car 的旅行路线","source":"NOIP 2001 提高组","platform":"洛谷","date":"","group":"luogu","category":"图与树","tags":["Floyd","矩形补点","计算几何"],"level":"挑战","summary":"用点积确定矩形直角顶点并补齐第四点，建立城市内外交通费用，再用 Floyd 求最短路。","caution":"几何坐标乘积需足够宽的整数；距离和费用用浮点数，核对出发到达城市的所有机场。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"洛谷/P1027 [NOIP 2001 提高组] Car 的旅行路线.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\nstruct Point {\r\n    int x, y;\r\n};\r\n\r\n// 判断 p 是否为直角顶点\r\nbool isRight(Point p, Point q, Point r) {\r\n    return 1LL * (q.x - p.x) * (r.x - p.x)\r\n         + 1LL * (q.y - p.y) * (r.y - p.y) == 0;\r\n}\r\n\r\n// 求矩形第四个顶点\r\nPoint getFourth(Point a, Point b, Point c) {\r\n    if (isRight(a, b, c)) return {b.x + c.x - a.x, b.y + c.y - a.y};\r\n    else if (isRight(b, a, c)) return {a.x + c.x - b.x, a.y + c.y - b.y};\r\n    else return {a.x + b.x - c.x, a.y + b.y - c.y};\r\n}\r\n\r\ndouble distance(Point a, Point b) {\r\n    return hypot(double(a.x - b.x), double(a.y - b.y));\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    int cases;\r\n    cin >> cases;\r\n\r\n    cout << fixed << setprecision(1);\r\n\r\n    while (cases--) {\r\n        int S, t, A, B;\r\n        cin >> S >> t >> A >> B;\r\n\r\n        // 城市编号转换为从 0 开始\r\n        --A;\r\n        --B;\r\n\r\n        int m = 4 * S;\r\n        vector<Point> airport(m);\r\n        vector<int> T(S);\r\n\r\n        // 城市 i 的机场编号为 4*i 到 4*i+3\r\n        for (int i = 0; i < S; i++) {\r\n            int k = 4 * i;\r\n\r\n            cin >> airport[k].x >> airport[k].y\r\n                >> airport[k + 1].x >> airport[k + 1].y\r\n                >> airport[k + 2].x >> airport[k + 2].y\r\n                >> T[i];\r\n\r\n            airport[k + 3] = getFourth(\r\n                airport[k], airport[k + 1], airport[k + 2]\r\n            );\r\n        }\r\n\r\n        // 建图：w[i][j] 表示两个机场之间的直接交通费用\r\n        vector<vector<double>> w(m, vector<double>(m, 0));\r\n\r\n        for (int i = 0; i < m; i++) {\r\n            for (int j = i + 1; j < m; j++) {\r\n                int cityI = i / 4;\r\n                int cityJ = j / 4;\r\n\r\n                int price = (cityI == cityJ ? T[cityI] : t);\r\n\r\n                w[i][j] = w[j][i] =\r\n                    distance(airport[i], airport[j]) * price;\r\n            }\r\n        }\r\n\r\n        const double INF = numeric_limits<double>::infinity();\r\n        vector<double> dist(m, INF);\r\n        vector<bool> used(m, false);\r\n\r\n        // 可以从 A 城市的任意机场出发\r\n        for (int i = 0; i < 4; i++) {\r\n            dist[4 * A + i] = 0;\r\n        }\r\n\r\n        // 朴素 Dijkstra\r\n        for (int step = 0; step < m; step++) {\r\n            int u = -1;\r\n\r\n            for (int i = 0; i < m; i++) {\r\n                if (!used[i] && (u == -1 || dist[i] < dist[u])) {\r\n                    u = i;\r\n                }\r\n            }\r\n\r\n            if (u == -1 || dist[u] == INF) break;\r\n\r\n            used[u] = true;\r\n\r\n            for (int v = 0; v < m; v++) {\r\n                if (!used[v]) {\r\n                    dist[v] = min(dist[v], dist[u] + w[u][v]);\r\n                }\r\n            }\r\n        }\r\n\r\n        double ans = INF;\r\n        for (int i = 0; i < 4; i++) {\r\n            ans = min(ans, dist[4 * B + i]);\r\n        }\r\n\r\n        cout << ans << '\\n';\r\n    }\r\n\r\n    return 0;\r\n}"}],"statement":"","links":[{"label":"洛谷 P1027 题面","url":"https://www.luogu.com.cn/problem/P1027"}],"hasIssues":false},{"id":"cqu2026-N","title":"ACM 不是一场骗局","source":"2026 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2026","category":"模拟与实现","tags":["字典映射","查表"],"level":"基础","summary":"固定七种姓名缩写与学校缩写的映射，读入后查表输出。","caution":"键要完整匹配；题目保证之外的输入不能默认插入空值。","versions":[{"name":"AC 目录存档","language":"Python","status":"ac-directory","path":"2026重庆大学程序设计新生赛暨邀请赛/src/AC/N ACM 不是一场骗局-AC.py","code":"name=input()\r\nif (name==\"hr\"):\r\n    print(\"nju\")\r\nif (name==\"gxm\"):\r\n    print(\"ucas\")\r\nif (name==\"cyj\"):\r\n    print(\"ucas\")\r\nif (name==\"lyz\"):\r\n    print(\"zju\")\r\nif (name==\"csys\"):\r\n    print(\"zju\")\r\nif (name==\"yzt\"):\r\n    print(\"ustc\")\r\nif (name==\"hyz\"):\r\n    print(\"fdu\")"},{"name":"AI 参考","language":"C++","status":"reference","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/AI/N ACM 不是一场骗局-AI.cpp","code":"/*\n【思路】这是固定映射题，不需要搜索、排序或推导姓名和学校的规律。\n用 map<string,string> 保存“姓名缩写 -> 学校缩写”，读到名字后直接查表输出。\n不同名字可以对应同一学校，例如 gxm、cyj 都输出 ucas，不影响键的唯一性。\n输入只有一组，并保证是规定的七种缩写之一，所以不会查询到表外名字。\n\n【C++ 用法】\nconst 表示映射初始化后不再修改。\nschool.at(name) 读取现有键对应的值，不会像非 const map 的 [] 那样自动创建缺失键。\n如果输入不满足题目保证，at 会抛出异常；这里利用的是题目给定的合法输入条件。\n表只有 7 项，是固定规模，时间与空间均可视为 O(1)。\n*/\n#include <bits/stdc++.h>\nusing namespace std;\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    // 直接按题目规定映射，不根据姓名缩写推测学校。\n    // 每一对大括号是 {键,值}，键和值都是 string，注意按题目要求保留小写。\n    const map<string,string> school={\n        {\"hr\",\"nju\"},\n        {\"gxm\",\"ucas\"},\n        {\"cyj\",\"ucas\"},\n        {\"lyz\",\"zju\"},\n        {\"csys\",\"zju\"},\n        {\"yzt\",\"ustc\"},\n        {\"hyz\",\"fdu\"}\n    };\n    string name;\n    // 姓名缩写不含空格，使用 >> 读取一个单词即可，不需要 getline。\n    cin>>name;\n    cout<<school.at(name)<<'\\n'; // 题目输入为规定的七种缩写之一。\n}\n"}],"statement":"","links":[],"editorial":"【思路】这是固定映射题，不需要搜索、排序或推导姓名和学校的规律。\n用 map<string,string> 保存“姓名缩写 -> 学校缩写”，读到名字后直接查表输出。\n不同名字可以对应同一学校，例如 gxm、cyj 都输出 ucas，不影响键的唯一性。\n输入只有一组，并保证是规定的七种缩写之一，所以不会查询到表外名字。\n\n【C++ 用法】\nconst 表示映射初始化后不再修改。\nschool.at(name) 读取现有键对应的值，不会像非 const map 的 [] 那样自动创建缺失键。\n如果输入不满足题目保证，at 会抛出异常；这里利用的是题目给定的合法输入条件。\n表只有 7 项，是固定规模，时间与空间均可视为 O(1)。","editorialSource":"原文件中的 AI 参考注释 · 请结合题面与原稿复核","number":"N","hasIssues":false},{"id":"cqu2026-M","title":"同色吞并","source":"2026 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2026","category":"图与树","tags":["换根DP","颜色","有向边消息"],"level":"挑战","summary":"每个方向记录这一侧能否缩并与最终颜色，用两遍遍历推导所有根的可行性。","caution":"hyper 文件为空；AI 参考的颜色公式仅在该方向可行时有效。","versions":[{"name":"AI 参考","language":"C++","status":"reference","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/AI/M 同色吞并-AI.cpp","code":"/*\n【先固定最终保留点，理解一次子树合并】\n若最终保留 u，则每个孩子必须先把整棵孩子子树缩成它的根，再由 u 吞并。\nu 初始颜色为 c，每吞并一个同色孩子就翻转，因此依次需要的孩子最终颜色是\nc、c^1、c、c^1、...。其中 ^ 是按位异或，对 0/1 而言异或 1 就是翻色。\n如果有 m 个孩子，必须满足：全部孩子子树都可缩好；最终颜色为 c 的孩子\n恰有 ceil(m/2) 个，另一种恰有 floor(m/2) 个。按两种颜色交替吞并即可。\n这既是必要条件，也是充分条件，不需要枚举孩子处理顺序。\n最后 u 翻色 m 次，最终颜色固定为 c^(m%2)，与吞并的具体次序无关。\n\n【有向边消息与换根 DP（Dynamic Programming，动态规划）】\n删掉无向边 (u,v)，考虑 u 所在的那一侧：它能否缩成 u，以及缩完是什么颜色。\nu 需要吞并的直接孩子数固定为 degree(u)-1，因此这个方向的最终颜色为\noutColor[u]=color[u]^((degree(u)-1)%2)，与排除的是哪个邻点 v 无关。\n这个颜色只有在该侧可缩好时才代表实际结果；不可行方向另用布尔状态阻止接受。\n\n临时以 1 为根：parent[u] 是父亲，order 保证父亲先于孩子。\ndown[u]：u 的整棵临时子树，能否缩成 u，即 u->parent[u] 方向是否可行。\nup[u]：父亲所在的另一侧能否缩成父亲，即 parent[u]->u 方向是否可行。\n注意 up[u] 不是“外部能否缩成 u”，也不是“u 能否被父亲吞掉”。\n\n【两遍遍历】\n1. 逆 order，孩子先完成，根据各孩子的 down 和 outColor 求 down[u]。\n2. 正 order，父亲已经给出 up[u]，现在所有邻点传向 u 的消息都已齐全。\n   汇总 bad（不可行方向数量）以及 cnt[0]、cnt[1]（方向最终颜色的数量）。\n   不排除邻点即可判断 u 能否成为最终根；排除孩子 v 的一份贡献，\n   就得到 u->v 的可行性，存入 up[v]，让下一层继续使用。\n所有根共享消息，不必对每个根重新做一次整树 DP。\n\n【为什么只减一份贡献】\n为每个孩子重新扫描其他邻点，会在星形树上退化为 O(n^2)。\n先汇总一次，再减去当前孩子造成的 bad 和颜色计数，每个方向只需 O(1)。\n即便不可行方向也暂计入 cnt，但 bad>0 不会被判为可行；排除时两种贡献一起减。\n\n【例子与边界】\nu 初始为 0，两个孩子缩完分别为 0、1：先吞 0，u 变 1，再吞 1，合法。\n若两个孩子都为 0，则吞第一个后 u 变 1，剩余 0 吞不了，不合法。\nn=1 没有孩子，bad=0、同色计数=0，条件自然成立，输出 1。\n采用迭代遍历，长链不爆栈；每条边扫描常数次，时间与空间均 O(n)。\n*/\n#include <bits/stdc++.h>\nusing namespace std;\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int n;\n    string s;\n    cin>>n>>s;\n    vector<vector<int>> tree(n+1);\n    for (int i=1;i<n;i++){\n        int u,v;\n        cin>>u>>v;\n        tree[u].push_back(v);\n        tree[v].push_back(u);\n    }\n    // color[u] 由输入字符串得到，是不会随 DP 改动的初始颜色。\n    // outColor[u] 是 u 朝任意邻点发送可行消息时，u 最终应具有的颜色。\n    vector<int> color(n+1),outColor(n+1);\n    for (int u=1;u<=n;u++){\n        color[u]=s[u-1]-'0';\n        int degree=tree[u].size();\n        // 对任意邻点 v，把 u 所在一侧缩成 u，需吞并 degree-1 个直接孩子。\n        // 每吞并一次翻色，故有向边 u->v 的最终颜色与 v 无关。\n        // &1 取奇偶性；degree=0 仅出现在单点树，没有有向边，取 0 次翻色即可。\n        outColor[u]=color[u]^((max(0,degree-1))&1);\n    }\n\n    vector<int> parent(n+1,0),order;\n    // reserve 只预留容量；从根 1 起逐个 push_back，建立父先子后的顺序。\n    order.reserve(n);\n    order.push_back(1);\n    for (int i=0;i<(int)order.size();i++){\n        int u=order[i];\n        for (int v : tree[u]){\n            if (v==parent[u]) continue;\n            parent[v]=u;\n            order.push_back(v);\n        }\n    }\n\n    // down[u]：删掉 u 与父亲的边后，u 的子树能否缩成 u。\n    // up[u]：删掉 u 与父亲的边后，父亲所在一侧能否缩成父亲。\n    vector<int> down(n+1,0),up(n+1,0);\n    for (int i=n-1;i>=0;i--){\n        int u=order[i];\n        // bad：不可行孩子数；same：最终颜色等于 u 初始颜色的孩子数；m：孩子总数。\n        int bad=0,same=0,m=0;\n        for (int v : tree[u]){\n            // 当前只求孩子向父亲的消息，不能把父亲所在侧也混进 u 的子树。\n            if (v==parent[u]) continue;\n            m++;\n            if (!down[v]) bad++;\n            if (outColor[v]==color[u]) same++;\n        }\n        // 先把每个孩子子树缩好。u 吞并孩子时，所需颜色依次为\n        // color[u], color[u]^1, color[u], ...。\n        // 因而所有孩子都必须可行，同色孩子恰有 ceil(m/2) 个。\n        // 对非负整数 m，(m+1)/2 就是向上取整的 m/2；m=0 的叶子自动可行。\n        down[u]=(bad==0 && same==(m+1)/2);\n    }\n\n    // 默认各点不可行，检查通过的位置改成 '1'；最终输出无空格的二进制串。\n    string ans(n,'0');\n    for (int u : order){\n        // 到达 u 时，父亲传来的 up[u] 已经由上一层求出。\n        int bad=0,cnt[2]={0,0};\n        for (int v : tree[u]){\n            // 父亲传来的可行性存在 up[u]，孩子传来的可行性存在 down[v]。\n            int ok=(v==parent[u] ? up[u] : down[v]);\n            if (!ok) bad++;\n            // 颜色由发送消息的邻点 v 决定，不是 outColor[u]。\n            cnt[outColor[v]]++;\n        }\n        int degree=tree[u].size();\n        // u 作为最终根时，所有邻点都作为孩子，不排除任何一侧。\n        if (bad==0 && cnt[color[u]]==(degree+1)/2) ans[u-1]='1';\n\n        for (int v : tree[u]){\n            if (v==parent[u]) continue;\n            // 计算 u->v：从所有邻点的统计里排除 v->u 的贡献。\n            // 不重新扫描其他邻点，避免星形树退化成 O(n^2)。\n            // !down[v] 为 0 或 1，恰好是这个孩子对 bad 的贡献。\n            int restBad=bad-(!down[v]);\n            int restSame=cnt[color[u]]-(outColor[v]==color[u]);\n            int m=degree-1;\n            // 排除 v 后，u 有 degree-1 个“孩子”，仍使用相同的交替颜色判定。\n            // 这条 u->v 消息恰好就是下一层需要的 up[v]。\n            up[v]=(restBad==0 && restSame==(m+1)/2);\n        }\n    }\n    cout<<ans<<'\\n';\n    // 两遍迭代遍历，时间、空间均 O(n)；n=1 自然输出 1，长链不会递归爆栈。\n}\n"},{"name":"空文件 · 待补全","language":"C++","status":"empty","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/hyper/M 同色吞并.cpp","code":""}],"statement":"","links":[],"editorial":"【先固定最终保留点，理解一次子树合并】\n若最终保留 u，则每个孩子必须先把整棵孩子子树缩成它的根，再由 u 吞并。\nu 初始颜色为 c，每吞并一个同色孩子就翻转，因此依次需要的孩子最终颜色是\nc、c^1、c、c^1、...。其中 ^ 是按位异或，对 0/1 而言异或 1 就是翻色。\n如果有 m 个孩子，必须满足：全部孩子子树都可缩好；最终颜色为 c 的孩子\n恰有 ceil(m/2) 个，另一种恰有 floor(m/2) 个。按两种颜色交替吞并即可。\n这既是必要条件，也是充分条件，不需要枚举孩子处理顺序。\n最后 u 翻色 m 次，最终颜色固定为 c^(m%2)，与吞并的具体次序无关。\n\n【有向边消息与换根 DP（Dynamic Programming，动态规划）】\n删掉无向边 (u,v)，考虑 u 所在的那一侧：它能否缩成 u，以及缩完是什么颜色。\nu 需要吞并的直接孩子数固定为 degree(u)-1，因此这个方向的最终颜色为\noutColor[u]=color[u]^((degree(u)-1)%2)，与排除的是哪个邻点 v 无关。\n这个颜色只有在该侧可缩好时才代表实际结果；不可行方向另用布尔状态阻止接受。\n\n临时以 1 为根：parent[u] 是父亲，order 保证父亲先于孩子。\ndown[u]：u 的整棵临时子树，能否缩成 u，即 u->parent[u] 方向是否可行。\nup[u]：父亲所在的另一侧能否缩成父亲，即 parent[u]->u 方向是否可行。\n注意 up[u] 不是“外部能否缩成 u”，也不是“u 能否被父亲吞掉”。\n\n【两遍遍历】\n1. 逆 order，孩子先完成，根据各孩子的 down 和 outColor 求 down[u]。\n2. 正 order，父亲已经给出 up[u]，现在所有邻点传向 u 的消息都已齐全。\n   汇总 bad（不可行方向数量）以及 cnt[0]、cnt[1]（方向最终颜色的数量）。\n   不排除邻点即可判断 u 能否成为最终根；排除孩子 v 的一份贡献，\n   就得到 u->v 的可行性，存入 up[v]，让下一层继续使用。\n所有根共享消息，不必对每个根重新做一次整树 DP。\n\n【为什么只减一份贡献】\n为每个孩子重新扫描其他邻点，会在星形树上退化为 O(n^2)。\n先汇总一次，再减去当前孩子造成的 bad 和颜色计数，每个方向只需 O(1)。\n即便不可行方向也暂计入 cnt，但 bad>0 不会被判为可行；排除时两种贡献一起减。\n\n【例子与边界】\nu 初始为 0，两个孩子缩完分别为 0、1：先吞 0，u 变 1，再吞 1，合法。\n若两个孩子都为 0，则吞第一个后 u 变 1，剩余 0 吞不了，不合法。\nn=1 没有孩子，bad=0、同色计数=0，条件自然成立，输出 1。\n采用迭代遍历，长链不爆栈；每条边扫描常数次，时间与空间均 O(n)。","editorialSource":"原文件中的 AI 参考注释 · 请结合题面与原稿复核","number":"M","hasIssues":true},{"id":"cqu2026-L","title":"上下翻飞","source":"2026 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2026","category":"构造","tags":["网格路径","蛇形遍历","分类讨论"],"level":"进阶","summary":"先在前 k−1 列交替上下移动，再走完剩余列并折返，覆盖两行所有格子且恰好竖直移动 k 次。","caution":"可行范围为 1≤k≤n；k=1 时须补上另一行第一格，n=1 单独处理。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/hyper/L 上下翻飞-hyper.cpp","code":"/*\n【这份保留原构造，只补详细注释】\n目标：从 (1,1) 出发，覆盖 2*n 个格子各一次，并恰好上下移动 k 次。\n\n【有解范围】\n每一列只有一条竖边，格子不能重复访问，所以一列最多上下移动一次，总计 k<=n。\n必须访问两行，至少上下移动一次，故 k>=1。下面构造能覆盖整个 1<=k<=n 范围。\nn=1 且 k=1 时只需 (1,1)、(2,1)，单独输出即可。\n\n【构造分两段】\n第一段：反复走“下、右、上、右”，每经过一列就完成一次上下翻转。\n只在竖向移动时增加 step，直到已经完成 k-1 次翻转。\n若 k>=2，此时前 k-1 列两格都访问过，当前列 y=k-1。\n第二段：沿当前行走完 y+1..n，在最右列翻到另一行，再倒着走回 y+1。\n这一段恰好多一次上下移动，总数就是 (k-1)+1=k。\n两段访问的列互不重叠，所以不会重复访问格子。\n\n【k=1 为什么还要额外补一个点】\n第一段完全不执行，起点仅访问过 (1,1)，此时 y=1，而 (2,1) 还没访问。\n第二段访问了两行的第 2..n 列，因此回程末尾必须补上 (2,1)。\nk>=2 时第 y 列已经访问两格，就不能再补，否则会重复。\n\n【例子】n=4、k=3，一条输出路径为：\n(1,1),(2,1),(2,2),(1,2),(1,3),(1,4),(2,4),(2,3)。\n竖向移动分别在第 1、2、4 列，总共 3 次。\n\n【变量】x 是当前行，y 是当前列；i 是方向序号；step 只统计已走的上下移动。\nxi、yi 分别是行、列增量数组，方向下标 i%4 表示四步循环。\n坐标连续输出即可，不需要先存整条路径。每组时间 O(n)，额外空间 O(1)。\n无解也要输出换行，避免 -1 与下一组的第一个行号粘成 -11。\n*/\n#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\n\nvoid solve(){\n    ll n,k;\n    cin>>n>>k;\n    // 题目 k 非负，因此 k==0 或 k>n 恰好对应所有无解情况。\n    if (k>n or k==0) cout<<-1<<'\\n';\n    else if (n==1) cout<<1<<\" \"<<1<<'\\n'<<2<<\" \"<<1<<'\\n';\n    else{\n        ll x=1,y=1;\n        // 按 (xi,yi) 配对：(+1,0)下、(0,+1)右、(-1,0)上、(0,+1)右。\n        vector<ll> yi={0,1,0,1};\n        vector<ll> xi={1,0,-1,0};\n        // 起点先输出一次，之后每移动一步输出新格子，不重复输出当前起点。\n        cout<<x<<\" \"<<y<<'\\n';\n        ll i=0;\n        ll step=0;\n        // 这里控制的是竖向次数，不是总步数；向右移动不增加 step。\n        while (step<k-1){\n            x+=xi[i%4];\n            y+=yi[i%4];\n            // 四个方向中，下标 0、2 分别是下、上，另外两个方向都是向右。\n            if (i%4==0 or i%4==2) step++;\n            i++;\n            cout<<x<<\" \"<<y<<'\\n';\n        }\n        // 第一趟沿当前行向右，不再输出第 y 列，因为当前位置已经输出过。\n        for (ll tmp=y+1;tmp<=n;tmp++){\n            cout<<x<<\" \"<<tmp<<'\\n';\n        }\n        // 行号只有 1、2，3-x 恰好换到另一行；下一次输出位于同一最右列 n。\n        // 前一趟至少经过一列，因为 k<=n，所以第 n 列的翻转一定存在。\n        x=3-x;\n        for (ll tmp=n;tmp>=y+1;tmp--){\n            cout<<x<<\" \"<<tmp<<'\\n';\n            // k=1 时，回到第 2 列后继续补第 1 列；不能在每次回程输出时都补。\n            if (k==1 and tmp==y+1) cout<<x<<\" \"<<y<<'\\n';\n        }\n    }\n}\n\nint main(){\n    int T=1;\n    cin>>T;\n    while (T--) solve();\n}\n"},{"name":"ERROR 目录原稿","language":"C++","status":"error","path":"2026重庆大学程序设计新生赛暨邀请赛/src/ERROR/L 上下翻飞.cpp","code":"/*\r\nWA\r\n部分正确\r\n\r\n你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的\r\n\r\n错误记录（只补注释，未修改代码）：\r\n已确认的问题：无解分支输出 -1 后没有换行，多组数据时会与下一组坐标或 -1 粘连。\r\n反例：T=2，第一组 n=2、k=0，第二组 n=2、k=1。\r\n当前输出首行是 -11 1，正确应为第一行 -1，第二行 1 1。\r\n建议无解时输出 cout<<-1<<'\\n'，并返回；本文件仍保留原代码，不代改。\r\n构造本身未发现错误：n<=35 的所有 1<=k<=n 都通过覆盖、唯一性、共边和上下次数验证。\r\n\r\n完整的多组输出反例：\r\n输入：\r\n2\r\n2 0\r\n2 1\r\n期望输出：\r\n-1\r\n1 1\r\n1 2\r\n2 2\r\n2 1\r\n当前第一行会变成 -11 1：第一组的 -1 和第二组第一个坐标的 1 粘成了 -11。\r\n另一个格式例子：两组分别是 2 0、2 3，当前会输出 -1-1，而不是规定的两行 -1。\r\n部分整数读取器可能容忍 -1-1，但不能依赖这种行为；上面 -11 1 的反例则会把 -11\r\n读成一个整数，不会自动拆成第一组的 -1 和第二组的 1，Special Judge 也无法补救。\r\n\r\n无需误改的部分：1<=k<=n 的判定是对的，每列最多一条竖边，访问两行至少需要一条。\r\n前 k-1 次翻转加上最右端的一次翻转，恰好 k 次；k=1 的末尾补点也有必要。\r\n最终修复只需让无解分支也输出换行；加 return 可以，但保留现有 else-if 结构也可以。\r\n*/\r\n#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nvoid solve(){\r\n    ll n,k;\r\n    cin>>n>>k;\r\n    // 输出格式错误：缺少 '\\n'，下一组输出会接在 -1 后面。\r\n    if (k>n or k==0) cout<<-1;\r\n    else if (n==1) cout<<1<<\" \"<<1<<'\\n'<<2<<\" \"<<1<<'\\n';\r\n    else{\r\n        ll x=1,y=1;\r\n        vector<ll> yi={0,1,0,1};\r\n        vector<ll> xi={1,0,-1,0};\r\n        cout<<x<<\" \"<<y<<'\\n';\r\n        ll i=0;\r\n        ll step=0;\r\n        while (step<k-1){\r\n            x+=xi[i%4];\r\n            y+=yi[i%4];\r\n            if (i%4==0 or i%4==2) step++;\r\n            i++;\r\n            cout<<x<<\" \"<<y<<'\\n';\r\n        }\r\n        for (ll tmp=y+1;tmp<=n;tmp++){\r\n            cout<<x<<\" \"<<tmp<<'\\n';\r\n        }\r\n        x=3-x;\r\n        for (ll tmp=n;tmp>=y+1;tmp--){\r\n            cout<<x<<\" \"<<tmp<<'\\n';\r\n            // 这是 k=1 时补上另一行第 1 列，不是重复访问，不能当成错误删除。\r\n            if (k==1 and tmp==y+1) cout<<x<<\" \"<<y<<'\\n';\r\n        }\r\n    }\r\n}\r\n\r\nint main(){\r\n    int T=1;\r\n    cin>>T;\r\n    while (T--) solve();\r\n}\r\n"}],"statement":"","links":[],"number":"L","hasIssues":true},{"id":"cqu2026-K","title":"可能的0","source":"2026 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2026","category":"数学与数论","tags":["生成函数","Horner","整数根"],"level":"挑战","summary":"用多项式 ∏(p_i+x) 表示零的计数，枚举 1..20，用 Horner 求 F(−t) 找回整数根。","caution":"系数可能很大，Python 可用任意精度；C++ 参考需要核对整数范围。","versions":[{"name":"hyper 原稿","language":"Python","status":"original","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/hyper/K 可能的0.py","code":"n=int(input())\r\nq=list(map(int,input().split()))\r\nans=[]\r\nfor i in range(1,21):\r\n    tmp=q[-1]\r\n    for j in range(len(q)-2,-1,-1):\r\n        tmp=-i*tmp+q[j]\r\n    if tmp==0:\r\n        ans.append(i)\r\nprint(*ans)"},{"name":"AI 参考","language":"C++","status":"reference","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/AI/K 可能的0-AI.cpp","code":"/*\n【计数为什么能写成多项式】\n第 i 个位置最终保留非零时有 p_i 种不同字符，记为常数项 p_i；\n最终变成零时只有字符 0 这一种结果，记为一次项 x。\n零不能按原字符的 p_i 种选择重复计数，因为它们变成零后是同一个结果。\n把 n 个位置独立选择相乘：F(x)=(p_1+x)...(p_n+x)。\n展开时每选择一个 x 就代表一个零，所以 x^j 的系数恰好就是 q_j。\n输入因此给出了完整多项式 F(x)=q_0+q_1*x+...+q_n*x^n。\n\n【怎样反推 p_i】\n若 t 是某个 p_i，把 x=-t 代入，对应因子 p_i-t=0，所以 F(-t)=0。\n反过来，一个整数乘积为 0，至少有一个因子为 0，因此 F(-t)=0 也说明 t=p_i。\np_i 互异且范围为 [1,20]，只需从 1 到 20 依次试根，不必枚举所有递增序列。\n\n【秦九韶算法 / Horner 法】\n计算 q_0+q_1*x+...+q_n*x^n 时，不分别算 x 的幂，而写成\n(((q_n*x+q_{n-1})*x+q_{n-2})*x+...)+q_0。\n从最高次项往下，每步只做一次乘法和一次加法，总共 O(n)。\n这里 q[i] 就是系数，不是模数，也不是必须恢复的 p[i]。\n\n【例子】输入 n=2，q=[6,5,1]，即 F(x)=6+5x+x^2。\nt=2 时，从最高项开始计算：value=1，接着 1*(-2)+5=3，再 3*(-2)+6=0。\nt=3 也为零，答案就是 2 3，对应 (x+2)(x+3)。\n\n【精确性】\n不能只对某个模数求值：不为 0 的整数也可能恰好是模数的倍数。\n也不使用浮点近似判零。下面用 __int128 精确计算，并为乘加保留宽裕的安全范围。\n按 n<=10、|x|<=20、q_i<=1e12 的粗略上界估算，约 1e25 的量级仍在其范围内。\n只输出恢复出的 int 根，所以不需要编写 __int128 的输出函数。\n题目保证输入合法，恰好有 n 个不同的候选根；时间 O(20n)，空间 O(n)。\n*/\n#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int n;\n    cin>>n;\n    // 一共有 n+1 个系数，从 q[0] 常数项读到 q[n] 最高次项，不能漏读 q[n]。\n    vector<ll> q(n+1);\n    for (ll& x : q) cin>>x;\n\n    // 一个位置：非零有 p_i 种选法，填 0 有一种选法并贡献一个 x。\n    // F(x)=(p_1+x)*...*(p_n+x)=q_0+q_1*x+...+q_n*x^n。\n    // 所以 F(-t)=0 当且仅当 t 是一个 p_i。\n    // p_i 互异且都在 [1,20]，直接检查 20 个可能值即可。\n    vector<int> ans;\n    for (int t=1;t<=20;t++){\n        // 秦九韶算法（Horner）：从最高次项往下，反复乘 x 加当前系数。\n        // 使用 __int128 扩大乘加的安全余量，不依赖正负项抵消来压缩范围。\n        // 判零必须针对原整数值，不能用浮点或只在某个模数下判零。\n        __int128 value=0;\n        for (int i=n;i>=0;i--) value=value*(-t)+q[i];\n        // t 从小到大枚举，发现根时直接记录，不需要额外排序或去重。\n        if (value==0) ans.push_back(t);\n    }\n    // 题目保证存在合法答案，因此恰好找到 n 个根；顺序天然递增。\n    for (int i=0;i<(int)ans.size();i++){\n        if (i) cout<<\" \";\n        cout<<ans[i];\n    }\n    cout<<'\\n';\n    // 时间 O(20n)，空间 O(n)，GNU C++17 支持 __int128。\n}\n"},{"name":"AI 参考","language":"Python","status":"reference","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/AI/K 可能的0-AI.py","code":"# 【整体思路：把计数问题转成多项式，再枚举整数根】\n# 第 i 个位置最后有两种情况：\n# 1. 不变成 0：可以选择 p[i] 种非零字符，计数记为 p[i]。\n# 2. 变成 0：最终只有字符 0 这一种结果，计数记为 x。\n#    这里的 x 是辅助变量，用来记录“这个位置贡献了一个 0”，不是输入的字符。\n#    原先不同的非零字符变成 0 后，结果都一样，不能再重复乘上 p[i]。\n#\n# 所有位置独立选择，因此可以写成：\n# F(x) = (p[1]+x)(p[2]+x)...(p[n]+x)。\n# 展开时，选中几个因子中的 x，就代表最终有几个位置变成 0。\n# 因而 x^j 的系数就是“恰好有 j 个 0 的字符串数量”，也就是题目给出的 q[j]。\n# 所以输入实际上给出了这个完整多项式：\n# F(x) = q[0] + q[1]*x + q[2]*x^2 + ... + q[n]*x^n。\n#\n# 例：若原来的 p 为 2、3：\n# F(x) = (2+x)(3+x) = 6+5x+x^2，对应输入 q=[6,5,1]。\n# 没有 0 时有 2*3=6 种；一个 0 时有 3+2=5 种；两个 0 时只有 1 种。\n#\n# 【为什么代入 -t 就能判断 t 是不是答案】\n# F(-t) = (p[1]-t)(p[2]-t)...(p[n]-t)。\n# 如果 t 等于其中某个 p[i]，对应因子就是 0，整个乘积也就是 0。\n# 反过来，乘积为 0，就一定有一个因子为 0，也就是 t 等于某个 p[i]。\n# 因此 F(-t)==0，当且仅当 t 是需要恢复的某个数。\n# 题目保证 1<=p[i]<=20，且这些数互不相同，所以只需依次检查 1 到 20。\n# 不需要枚举所有 p 的组合，也不需要使用浮点数近似求根。\n\n# n 是字符串长度；输入一共会给出 n+1 个多项式系数。\nn = int(input())\n\n# input() 读取一行，split() 按空白分开，map(int, ...) 把每一项转成整数，\n# list(...) 再把它们保存为列表。\n# q 的顺序是从低次到高次：q[0] 是常数项，q[n] 是最高次项系数。\nq = list(map(int, input().split()))\n\n# 保存恢复出的 p[i]。Python 的 [] 表示空列表，相当于 C++ 的空 vector。\nans = []\n\n# range(1,21) 包含 1，但不包含 21，因此依次枚举 t=1,2,...,20。\nfor t in range(1, 21):\n    # 每次换一个候选 t，都要从头计算 F(-t)，不能沿用上一次的 value。\n    value = 0\n\n    # 【秦九韶算法，也叫 Horner 法】\n    # 不分别计算 x、x^2、x^3，而是把多项式改写成嵌套形式：\n    # 例如 q[0]+q[1]*x+q[2]*x^2 = (q[2]*x+q[1])*x+q[0]。\n    # 所以要从最高次项开始，每次“旧结果乘 x，再加当前系数”。\n    #\n    # reversed(q) 按 q[n]、q[n-1]、...、q[0] 的顺序逐个取出系数，\n    # 不会修改原列表 q；coef 是 coefficient（系数）的缩写。\n    # 这里代入的是 x=-t，因此每一步乘的是 (-t)。\n    for coef in reversed(q):\n        value = value * (-t) + coef\n\n    # 例：q=[6,5,1]、t=2，倒序取出的系数依次为 1、5、6：\n    # 第一步 value = 0*(-2)+1 = 1。\n    # 第二步 value = 1*(-2)+5 = 3。\n    # 第三步 value = 3*(-2)+6 = 0。\n    # 此时 value 就是 F(-2)，等于 0，说明 2 是一个需要输出的 p[i]。\n    # Python 的 int 自动支持大整数，这些乘加不需要手动改用 __int128。\n    # 这里必须计算精确整数值，不能对某个模数取模后就判断是否为 0。\n    if value == 0:\n        # append(t) 把 t 加到列表末尾，相当于 C++ 的 push_back(t)。\n        # t 本来就是从小到大枚举，所以 ans 自然递增，不用再排序。\n        ans.append(t)\n\n# *ans 表示把列表中的元素依次展开，作为 print 的多个参数。\n# 例如 ans=[2,3]，print(*ans) 输出：2 3，并自动换行。\n# 如果直接 print(ans)，会输出带中括号和逗号的 [2, 3]，不符合题目格式。\nprint(*ans)\n\n# 每个候选需要计算 n+1 个系数，一共检查 20 个候选。\n# 时间复杂度 O(20n)，额外空间 O(n)；题目保证存在合法答案，最终会找到 n 个数。\n"}],"statement":"","links":[],"editorial":"【计数为什么能写成多项式】\n第 i 个位置最终保留非零时有 p_i 种不同字符，记为常数项 p_i；\n最终变成零时只有字符 0 这一种结果，记为一次项 x。\n零不能按原字符的 p_i 种选择重复计数，因为它们变成零后是同一个结果。\n把 n 个位置独立选择相乘：F(x)=(p_1+x)...(p_n+x)。\n展开时每选择一个 x 就代表一个零，所以 x^j 的系数恰好就是 q_j。\n输入因此给出了完整多项式 F(x)=q_0+q_1*x+...+q_n*x^n。\n\n【怎样反推 p_i】\n若 t 是某个 p_i，把 x=-t 代入，对应因子 p_i-t=0，所以 F(-t)=0。\n反过来，一个整数乘积为 0，至少有一个因子为 0，因此 F(-t)=0 也说明 t=p_i。\np_i 互异且范围为 [1,20]，只需从 1 到 20 依次试根，不必枚举所有递增序列。\n\n【秦九韶算法 / Horner 法】\n计算 q_0+q_1*x+...+q_n*x^n 时，不分别算 x 的幂，而写成\n(((q_n*x+q_{n-1})*x+q_{n-2})*x+...)+q_0。\n从最高次项往下，每步只做一次乘法和一次加法，总共 O(n)。\n这里 q[i] 就是系数，不是模数，也不是必须恢复的 p[i]。\n\n【例子】输入 n=2，q=[6,5,1]，即 F(x)=6+5x+x^2。\nt=2 时，从最高项开始计算：value=1，接着 1*(-2)+5=3，再 3*(-2)+6=0。\nt=3 也为零，答案就是 2 3，对应 (x+2)(x+3)。\n\n【精确性】\n不能只对某个模数求值：不为 0 的整数也可能恰好是模数的倍数。\n也不使用浮点近似判零。下面用 __int128 精确计算，并为乘加保留宽裕的安全范围。\n按 n<=10、|x|<=20、q_i<=1e12 的粗略上界估算，约 1e25 的量级仍在其范围内。\n只输出恢复出的 int 根，所以不需要编写 __int128 的输出函数。\n题目保证输入合法，恰好有 n 个不同的候选根；时间 O(20n)，空间 O(n)。","editorialSource":"原文件中的 AI 参考注释 · 请结合题面与原稿复核","number":"K","hasIssues":false},{"id":"cqu2026-J","title":"小 B 与瓶子","source":"2026 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2026","category":"动态规划","tags":["排序","相邻配对","最小子段"],"level":"挑战","summary":"原点排序后相邻配对，插入两点会翻转一段黑白间隙，把增量转成最小连续区间和。","caution":"按位置区分段的正负权；最优新端点可落在原点上。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/hyper/J 小 B 与瓶子.cpp","code":"#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\nconst ll INF=LLONG_MAX;\n\nvoid solve() {\n    ll n;\n    cin>>n;\n    vector<ll> a(2*n+1);\n    for (ll i=1;i<=2*n;i++) cin>>a[i];\n    sort(a.begin()+1,a.end());\n    ll base=0;\n    for (int i=1;i<=2*n-1;i+=2) base+=a[i+1]-a[i];\n\n    ll pre=0,maxpre=0,best=INF;\n    for (int i=1;i<=2*n-1;i++){\n        ll gap=a[i+1]-a[i];\n        if (i&1) pre-=gap;\n        else pre+=gap;\n        best=min(best,pre-maxpre);\n        maxpre=max(pre,maxpre);\n    }\n    cout<<base+best<<'\\n';\n}\n\nint main() {\n    int T=1;\n    // cin >> T;\n    while (T--) solve();\n    return 0;\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/AI/J 小 B 与瓶子-AI.cpp","code":"/*\n【先看没有新瓶子的情况】\n数轴上把偶数个点两两配对，最小距离和可由“排序后相邻配对”得到。\n例如 a<=b<=c<=d，不相邻的配法 (a,c)、(b,d) 或 (a,d)、(b,c)，\n费用都不小于 (a,b)、(c,d)。不断交换配对，能把最优解整理成相邻配对。\n因此原答案 base=sum(a[1]-a[0], a[3]-a[2], ...)。\n\n【加入两个点，为什么变成区间问题】\n把原配对线段涂黑，其他相邻原点间隙涂白。黑色长度之和就是 base。\n在 x<=y 处各插入一个新瓶子后，重新排序相邻配对：\n[x,y] 外的点序号奇偶性不变，配对覆盖不变；区间内序号整体错位一次，黑白互换。\n所以增量 = [x,y] 内原白色长度 - 原黑色长度。\n给黑段权值 -长度，白段权值 +长度，就转化成寻找权值和最小的连续区间。\n每一段内部权值密度固定，移动端点时费用线性变化，最优端点可选在原点上。\n两端以外原本没有黑段，向外延长只会多付长度，也不必考虑。\n原点都是整数，因此这样的新瓶子美观度满足整数要求。\n\n【带符号前缀和】\npre：从 a[0] 走到当前 a[i] 的累计带符号长度，初始位置的 pre 为 0。\nmaxPre：当前右端点之前，所有可能左端点处最大的 pre。\nbest：找到的最小增量。固定右端点后，要最小化 pre[right]-pre[left]，\n就让 pre[left] 尽量大，因此用 pre-maxPre 更新 best。\nbest 初值 0，表示新瓶子取同一美观度，可以不改善但绝不必让费用变大。\n\n【例子】原美观度 [0,100,101,201]，base=100+100=200。\n三个间隙带符号长度为 -100、+1、-100，前缀为 0、-100、-99、-199。\n最小增量为 -199，答案 1；新瓶子可取 0 和 201，与两端旧瓶配对，\n中间的 100、101 配成一对，恰好只付 1。\n\n【复杂度和边界】排序 O(n log n)，扫描 O(n)，保存输入 O(n)。\n重复美观度只产生长度为 0 的间隙，无需去重，瓶子数量必须保留。\nn=1 时能用两个新瓶子分别匹配两个旧瓶子，答案自然为 0。\n*/\n#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int n;\n    cin>>n;\n    // 输入 n 是原配对数，原瓶子实际有 2*n 个，不是 n 个。\n    vector<ll> a(2*n);\n    for (ll& x : a) cin>>x;\n    sort(a.begin(),a.end());\n\n    // 原瓶子排序后相邻配对最优，base 是不加新瓶子时的费用。\n    ll base=0;\n    for (int i=0;i<2*n;i+=2) base+=a[i+1]-a[i];\n\n    // 在数轴 x<=y 处加入两个新瓶子，只有 [x,y] 内的配对覆盖会翻转。\n    // 原来被相邻瓶子配对覆盖的段：翻转后省去长度，权为 -长度。\n    // 原来未覆盖的段：翻转后增加长度，权为 +长度。\n    // 相邻原瓶子之间函数线性，最优端点可以选在原瓶子的美观度处。\n    // pre 是带正负号的长度累计，不是原瓶子数值的普通前缀和。\n    ll pre=0,maxPre=0,best=0;\n    for (int i=1;i<2*n;i++){\n        ll gap=a[i]-a[i-1];\n        // 下标从 0 开始：i 为奇数时，该段是 (a[0],a[1]) 等原有黑段。\n        // i&1 判断最低二进制位是否为 1，与 i%2==1 等价。\n        if (i&1) pre-=gap;\n        else pre+=gap;\n        // 当前点作为右端点，左端点选择此前 pre 最大的位置。\n        best=min(best,pre-maxPre);\n        // 让当前点也成为以后右端点可选择的左端点；无需保存整个前缀数组。\n        maxPre=max(maxPre,pre);\n    }\n    // best 初始为 0，包含两个新瓶子美观度相同、不改变费用的情况。\n    // best 是相对原答案的增量，可能为负；不能把 best 单独当作最终费用。\n    cout<<base+best<<'\\n';\n    // 排序 O(n log n)，扫描 O(n)，空间 O(n)。所有距离、费用用 long long。\n}\n"}],"statement":"","links":[],"editorial":"【先看没有新瓶子的情况】\n数轴上把偶数个点两两配对，最小距离和可由“排序后相邻配对”得到。\n例如 a<=b<=c<=d，不相邻的配法 (a,c)、(b,d) 或 (a,d)、(b,c)，\n费用都不小于 (a,b)、(c,d)。不断交换配对，能把最优解整理成相邻配对。\n因此原答案 base=sum(a[1]-a[0], a[3]-a[2], ...)。\n\n【加入两个点，为什么变成区间问题】\n把原配对线段涂黑，其他相邻原点间隙涂白。黑色长度之和就是 base。\n在 x<=y 处各插入一个新瓶子后，重新排序相邻配对：\n[x,y] 外的点序号奇偶性不变，配对覆盖不变；区间内序号整体错位一次，黑白互换。\n所以增量 = [x,y] 内原白色长度 - 原黑色长度。\n给黑段权值 -长度，白段权值 +长度，就转化成寻找权值和最小的连续区间。\n每一段内部权值密度固定，移动端点时费用线性变化，最优端点可选在原点上。\n两端以外原本没有黑段，向外延长只会多付长度，也不必考虑。\n原点都是整数，因此这样的新瓶子美观度满足整数要求。\n\n【带符号前缀和】\npre：从 a[0] 走到当前 a[i] 的累计带符号长度，初始位置的 pre 为 0。\nmaxPre：当前右端点之前，所有可能左端点处最大的 pre。\nbest：找到的最小增量。固定右端点后，要最小化 pre[right]-pre[left]，\n就让 pre[left] 尽量大，因此用 pre-maxPre 更新 best。\nbest 初值 0，表示新瓶子取同一美观度，可以不改善但绝不必让费用变大。\n\n【例子】原美观度 [0,100,101,201]，base=100+100=200。\n三个间隙带符号长度为 -100、+1、-100，前缀为 0、-100、-99、-199。\n最小增量为 -199，答案 1；新瓶子可取 0 和 201，与两端旧瓶配对，\n中间的 100、101 配成一对，恰好只付 1。\n\n【复杂度和边界】排序 O(n log n)，扫描 O(n)，保存输入 O(n)。\n重复美观度只产生长度为 0 的间隙，无需去重，瓶子数量必须保留。\nn=1 时能用两个新瓶子分别匹配两个旧瓶子，答案自然为 0。","editorialSource":"原文件中的 AI 参考注释 · 请结合题面与原稿复核","number":"J","hasIssues":false},{"id":"cqu2026-I","title":"A Brief Proof","source":"2026 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2026","category":"图与树","tags":["树上配对","后序遍历"],"level":"挑战","summary":"每棵子树最多上传一个未配对特殊点，在父节点处将来自不同分支的点配对。","caution":"pending 记录节点编号，不是个数；路径允许共点但不能共边。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/hyper/I A Brief Proof.cpp","code":"#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\nconst ll INF=LLONG_MAX;\n\nvoid solve() {\n    ll n,k;\n    cin>>n>>k;\n    vector<vector<ll>> tree(n+1);\n    for (ll i=1;i<n;i++){\n        ll u,v;\n        cin>>u>>v;\n        tree[u].push_back(v);\n        tree[v].push_back(u);\n    }\n    vector<int> special(n+1,0);\n    for (int i=0;i<k;i++){\n        int u;\n        cin>>u;\n        special[u]=1;\n    }\n    vector<ll> parent(n+1,0),order;\n    order.push_back(1);\n    for (int i=0;i<(int)order.size();i++){\n        ll u=order[i];\n        for (auto v : tree[u]){\n            if (v==parent[u]) continue;\n            parent[v]=u;\n            order.push_back(v);\n        }\n    }\n\n    vector<ll> pending(n+1,0);\n    vector<pair<ll,ll>> ans;\n    for (ll i=n-1;i>=0;i--){\n        ll u=order[i];\n        ll cur=special[u]==1 ? u : 0;\n        for (auto v : tree[u]){\n            if (parent[u]==v or pending[v]==0) continue;\n            if (cur==0) cur=pending[v];\n            else{\n                ans.push_back({cur,pending[v]});\n                cur=0;\n            }\n        }\n        if (cur!=0) pending[u]=cur;\n    }\n\n    for (auto &[u,v] : ans){\n        cout<<u<<\" \"<<v<<'\\n';\n    }\n}\n\nint main() {\n    int T=1;\n    // cin >> T;\n    while (T--) solve();\n    return 0;\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/AI/I A Brief Proof-AI.cpp","code":"/*\n【目标】把偶数个特殊点两两配对，不同配对的唯一路径不能共用边，可以共用顶点。\n\n【树上从下向上配对】\n暂时以 1 为根。对每棵子树，尽可能在子树内部把特殊点配好，\n最后只留下 0 或 1 个尚未配对的点，交给父亲继续处理。\n因为子树与外界只有一条父边，如果上传多个点分别与外界配对，就可能复用这条边。\npending[u] 存留下的那个特殊点编号，不是剩余点数量；为 0 表示没有剩余。\n\n【在 u 处怎么合并孩子的结果】\n候选点来自每个孩子上传的一个 pending，以及 u 自己（若 u 是特殊点）。\n维护 cur：尚未配对的一个候选。新候选到来时，若 cur 为空就先保留它；\n否则把 cur 与新候选配成一对，然后清空 cur。\n两点要么来自不同孩子子树，要么一个就是 u，因此路径在 u 汇合。\n这些孩子的内部路径已经配好，上传点通往 u 的剩余路径尚未被使用；\n每个孩子仅上传一个候选，因此这一轮新路径彼此也不共用孩子的父边。\n\n【为什么最终都能配完】\n每配成一对消耗两个点，所以 pending[u] 是否为空，只取决于子树特殊点数量的奇偶。\n整棵树有偶数 k 个特殊点，根处一定剩 0 个，最终正好产生 k/2 对。\n\n【为什么不用递归】\n先用 order 建立父先子后的遍历顺序，再逆序处理，实现子先父后的依赖顺序。\n这里 order 按队列式扩展，并非递归 DFS 序，但仍保证所有孩子在父亲之前完成处理。\n长链最多 2e5 级时，不会因为函数递归过深而爆栈。\n每条边扫描常数次，时间 O(n+k)，空间 O(n+k)，无需真正输出或保存每条路径。\n*/\n#include <bits/stdc++.h>\nusing namespace std;\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int n,k;\n    cin>>n>>k;\n    vector<vector<int>> tree(n+1);\n    for (int i=1;i<n;i++){\n        int u,v;\n        cin>>u>>v;\n        tree[u].push_back(v);\n        tree[v].push_back(u);\n    }\n    // special[u] 为 1 表示特殊点；这里是标记，后续不会随配对删除节点。\n    vector<int> special(n+1,0);\n    for (int i=0;i<k;i++){\n        int u;\n        cin>>u;\n        special[u]=1;\n    }\n\n    // 先建立父子关系，再逆序处理；不用深递归，长链也安全。\n    vector<int> parent(n+1,0),order;\n    // reserve 只预留容量，不创建 n 个元素；随后用 push_back 逐个加入。\n    order.reserve(n);\n    order.push_back(1);\n    // 循环中 size 会随 push_back 增大，所以新加入的孩子也会继续被处理。\n    for (int i=0;i<(int)order.size();i++){\n        int u=order[i];\n        for (int v : tree[u]){\n            // 输入是树，跳过父亲即可，不会再从其他路径重复进入同一个点。\n            if (v==parent[u]) continue;\n            parent[v]=u;\n            order.push_back(v);\n        }\n    }\n\n    // pending 的英文意思是“待处理、尚未完成”。\n    // pending[u]：处理完 u 的整棵子树后，唯一留下、还没有配对的特殊点编号。\n    // 例如 pending[u]=8，表示“8 号特殊点还没配对”，不是还有 8 个点。\n    // pending[u]=0 表示 u 子树内的特殊点已经全部配完；节点编号从 1 开始，\n    // 所以可以用不存在的编号 0 表示“没有剩余点”。\n    //\n    // 每棵子树处理结束时，要同时保证两件事：\n    // 1. 已经配好的路径互不共用边，而且全部留在这棵子树内部。\n    // 2. 如果剩下特殊点 x=pending[u]，那么 x 到 u 的路径还没有被使用。\n    //    这样以后把 x 与子树外的点配对时，就能安全地沿这条路走到 u，再走向父亲。\n    // 每棵子树至多留下一个特殊点，保证通往父亲的那条边最多被一条配对路径使用。\n    vector<int> pending(n+1,0);\n    // ans 中每个 pair 保存一对特殊点的编号；树上两点的路径唯一，不用存路径本身。\n    vector<pair<int,int>> ans;\n    // 答案最多 k/2 对；预留容量并不改变 ans.size()。\n    ans.reserve(k/2);\n\n    /*\n    【先看一个完整的例子，再看下面的循环】\n    树有三条分支：1-2-5、1-3-6、1-4-7，根是 1。\n    特殊点为 1、5、6、7，一共 4 个。\n\n    从下向上处理后，三个孩子的结果为：\n        pending[2]=5：2 的子树留下特殊点 5。\n        pending[3]=6：3 的子树留下特殊点 6。\n        pending[4]=7：4 的子树留下特殊点 7。\n    此时还没有给这三个点配对，5 到 2、6 到 3、7 到 4 的边也都没有被使用。\n\n    处理 u=1，假设按孩子 2、3、4 的顺序访问：\n    (1) 1 自己是特殊点，所以先令 cur=1，表示把特殊点 1 暂存起来。\n    (2) 孩子 2 留下特殊点 5；手里已有 cur=1，于是配对 (1,5)。\n        这一对的路径是 1-2-5。配完令 cur=0，表示手里不再有待配对的点。\n    (3) 孩子 3 留下特殊点 6；此时 cur=0，先令 cur=6，暂时不配对。\n    (4) 孩子 4 留下特殊点 7；此时 cur=6，于是配对 (6,7)。\n        这一对的路径是 6-3-1-4-7。配完再次令 cur=0。\n    (5) 所有孩子处理完，记录 pending[1]=0，表示整棵树已经没有剩余点。\n\n    两条路径都经过顶点 1，但是没有共用任何一条边，符合题意。\n    注意：“经过同一个顶点”允许，“经过同一条边”才不允许。\n\n    如果某个普通节点 u 的三个孩子分别留下点 5、6、7，处理过程则是：\n        cur=0 -> 暂存 5 -> 把 5 和 6 配对、清空 cur -> 暂存 7。\n    最后 pending[u]=7，把这个点留给父亲继续配；不是要求每层必须全部配完。\n    */\n\n    // order 建立时，父亲一定排在孩子前面；现在倒着遍历，孩子就先于父亲处理。\n    // 所以轮到 u 时，每个孩子 v 的 pending[v] 都已经算好，可以直接拿来使用。\n    for (int i=n-1;i>=0;i--){\n        int u=order[i];\n        // cur 是 current 的缩写，这里表示“当前手里暂存的一个未配对特殊点编号”。\n        // cur=0：手里没有点，等待下一个孩子提供候选。\n        // cur=x：手里暂存特殊点 x，等待下一个候选来和 x 配成一对。\n        //\n        // special[u] ? u : 0 是条件表达式：\n        // u 是特殊点，就先把 u 自己作为候选；否则暂时没有候选。\n        // 这不是把 u 与自己配对，只是把 u 放进“等待配对”的位置。\n        // 若候选就是 u，它走到当前汇合点 u 不需要经过任何边。\n        int cur=(special[u] ? u : 0);\n        for (int v : tree[u]){\n            // tree[u] 存的是无向邻点，里面也有父亲，父亲不能作为孩子处理。\n            // 孩子若 pending[v]=0，表示它的子树已经全部配完，没有候选交上来。\n            // 满足其中任意一个条件就跳过，继续看下一个邻点。\n            if (v==parent[u] || pending[v]==0) continue;\n\n            // 执行到这里，v 一定是孩子，而且它留下了一个特殊点 pending[v]。\n            // 这一个点不一定是 v 本人，也可能是 v 子树中更深处的某个特殊点。\n            // 如果手里还没有候选，就把这个点暂存到 cur，先不输出配对。\n            if (cur==0) cur=pending[v];\n            else{\n                // 手里已经有候选 cur，现在又拿到 pending[v]，正好凑成两个点。\n                // cur 要么是 u 本人，要么来自之前处理过的另一个孩子子树；\n                // pending[v] 来自当前这个孩子子树，因此两者一定是不同的特殊点。\n                // 树上它们的唯一路径是：cur -> ... -> u -> ... -> pending[v]。\n                //\n                // 为什么这条路径不会与已经配好的路径共用边？\n                // 1. 每个孩子都保证：留下的点走到孩子根的那条路还没有被使用。\n                // 2. 不同孩子的子树互不相交，所以它们走到 u 用的是不同分支。\n                // 3. 一对配完后，两个候选都不再留给上层，这两条分支不会再被取用。\n                // 所以不需要真的删除边或逐条检查路径，候选的来源已经保证了合法性。\n                // 多组配对可以都经过 u，但会使用不同分支的边，题目允许共用顶点。\n                ans.push_back({cur,pending[v]});\n\n                // 两个点都已配好，当前手里不能再留下 cur，否则会把它重复配对。\n                // 清空后，下一个孩子若还有候选，就会重新进入上面的 cur==0 分支。\n                // 这里不用把 pending[v] 也改成 0：每个孩子的记录只被父亲读取一次。\n                // u 的父亲以后只读取 pending[u]，不会越过 u 再直接读取 pending[v]。\n                cur=0;\n            }\n        }\n\n        // 所有孩子处理完后：\n        // cur=0：u 本人和孩子们交来的候选已经全部两两配完。\n        // cur=x：还剩特殊点 x，暂时不强行配对，留给 u 的父亲继续处理。\n        // x 到 u 的那条路径尚未用于任何配对，父亲之后可以安全地接着往上走。\n        // 注意保存的是 x 的编号，不是父亲编号，也不是剩余点的数量。\n        pending[u]=cur;\n    }\n    // 每配成一对就减少两个未配对点；每棵子树又最多留下一个点。\n    // 因此子树特殊点为偶数时 pending 为 0，为奇数时 pending 为某个点的编号。\n    // 根 1 的子树就是整棵树，总共有偶数 k 个特殊点，所以 pending[1] 必为 0，\n    // 最终恰好输出 k/2 对，每个特殊点出现一次，没有点需要再交给根的父亲。\n    for (auto [u,v] : ans) cout<<u<<\" \"<<v<<'\\n';\n    // 时间 O(n+k)，空间 O(n+k)。\n}\n"}],"statement":"","links":[],"editorial":"【目标】把偶数个特殊点两两配对，不同配对的唯一路径不能共用边，可以共用顶点。\n\n【树上从下向上配对】\n暂时以 1 为根。对每棵子树，尽可能在子树内部把特殊点配好，\n最后只留下 0 或 1 个尚未配对的点，交给父亲继续处理。\n因为子树与外界只有一条父边，如果上传多个点分别与外界配对，就可能复用这条边。\npending[u] 存留下的那个特殊点编号，不是剩余点数量；为 0 表示没有剩余。\n\n【在 u 处怎么合并孩子的结果】\n候选点来自每个孩子上传的一个 pending，以及 u 自己（若 u 是特殊点）。\n维护 cur：尚未配对的一个候选。新候选到来时，若 cur 为空就先保留它；\n否则把 cur 与新候选配成一对，然后清空 cur。\n两点要么来自不同孩子子树，要么一个就是 u，因此路径在 u 汇合。\n这些孩子的内部路径已经配好，上传点通往 u 的剩余路径尚未被使用；\n每个孩子仅上传一个候选，因此这一轮新路径彼此也不共用孩子的父边。\n\n【为什么最终都能配完】\n每配成一对消耗两个点，所以 pending[u] 是否为空，只取决于子树特殊点数量的奇偶。\n整棵树有偶数 k 个特殊点，根处一定剩 0 个，最终正好产生 k/2 对。\n\n【为什么不用递归】\n先用 order 建立父先子后的遍历顺序，再逆序处理，实现子先父后的依赖顺序。\n这里 order 按队列式扩展，并非递归 DFS 序，但仍保证所有孩子在父亲之前完成处理。\n长链最多 2e5 级时，不会因为函数递归过深而爆栈。\n每条边扫描常数次，时间 O(n+k)，空间 O(n+k)，无需真正输出或保存每条路径。","editorialSource":"原文件中的 AI 参考注释 · 请结合题面与原稿复核","number":"I","hasIssues":false},{"id":"cqu2026-H","title":"赞助到账","source":"2026 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2026","category":"数学与数论","tags":["前缀和","前后缀最小值"],"level":"进阶","summary":"枚举余额翻倍的时机，用前后缀最小值推导启动资金的两个下界。","caution":"前缀最小值必须包含初始 0；整除上取整方向要正确。","versions":[{"name":"AC 目录存档","language":"C++","status":"ac-directory","path":"2026重庆大学程序设计新生赛暨邀请赛/src/AC/H 赞助到账-AC.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF =LLONG_MAX;\r\n\r\nbool ifyes(const vector<ll>& a,const vector<ll>& pre,ll tmp,ll n){\r\n    bool p=true;\r\n    ll i=1;\r\n    ll max_pre=0;\r\n    ll max_pre_i=-1;\r\n    if (pre[i]+tmp<0){\r\n        p=false;\r\n        tmp*=2;\r\n    }\r\n    while (true){\r\n        if (pre[i]+tmp>=0 and p){\r\n            if (pre[i]>=max_pre){\r\n                max_pre=pre[i];\r\n                max_pre_i=i;\r\n            }\r\n        }\r\n        else{\r\n            if (p){\r\n                i=max_pre_i+1;\r\n                p=false;\r\n                tmp=(max_pre+tmp)*2;\r\n            }\r\n            tmp+=a[i];\r\n            if (tmp<0) return false;\r\n        }\r\n        if (i==n) break;\r\n        i++;\r\n    }\r\n    return true;\r\n}\r\n\r\nvoid solve(){\r\n    ll n;\r\n    cin>>n;\r\n    vector<ll> a(n+1);\r\n    vector<ll> pre(n+1,0);\r\n    ll sum=0;\r\n    for (int i=1;i<=n;i++){ \r\n        cin>>a[i];\r\n        if (a[i]<0) sum+=a[i];\r\n        pre[i]=pre[i-1]+a[i];\r\n        // cout<<pre[i]<<\" \";\r\n    }\r\n    ll l=0,r=-sum;\r\n    // cout<<l<<\" \"<<r<<'\\n';\r\n    while (l<r){\r\n        ll mid=(l+r)/2;\r\n        if (ifyes(a,pre,mid,n)) r=mid;\r\n        else l=mid+1;\r\n    }\r\n    cout<<l;\r\n    cout<<'\\n';\r\n}\r\n\r\nint main(){\r\n    int T=1;\r\n    // cin>>T;\r\n    while (T--) solve();\r\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/AI/H 赞助到账-AI.cpp","code":"/*\n【题意模型】收支 a_i 按顺序发生，余额任何时刻都不能为负。\n可在某个时机申请一次赞助，把当时余额翻倍，求最少启动资金 x。\n\n【前缀和】pre[i]=前 i 笔收支之和，pre[0]=0。\n没有赞助时，第 i 笔之后余额为 x+pre[i]，所以最少需要\nD=-min(pre[0],pre[1],...,pre[n]) 的启动资金。\nminPre 初值为 0，把没有发生任何收支的初始时刻也纳入，确保 D>=0。\n\n【枚举在前 k 笔之后申请】\n申请前，所有 i<=k 都要满足 x+pre[i]>=0。\n令 leftMin=min(pre[0..k])，则第一个条件为 x>=-leftMin。\n申请时余额为 x+pre[k]，翻倍后再经历到第 i 笔，余额是：\n2*(x+pre[k])+(pre[i]-pre[k])=2*x+pre[k]+pre[i]，i>=k。\n因此第二个条件是 2*x>=-pre[k]-min(pre[k..n])。\n\n【为什么代码不用后缀最小值，而能用全局 D】\n在第一个条件成立时，对所有 i<=k，有\n2*x+pre[k]+pre[i]=(x+pre[k])+(x+pre[i])>=0。\n所以把第二个条件也检查到申请前的 i，不会加上真正的新限制。\n直接使用全局最小 pre[i]=-D，得到 2*x>=D-pre[k]。\n如果右边为负，资金至少为 0 已经满足它，先用 max(0,...) 截成非负。\n\n【每个时机的答案】x=max(-leftMin,ceil(max(0,D-pre[k])/2))。\n两个条件要同时满足，所以取 max；不同 k 任选一种，所以再对 x 取 min。\n初始 ans=D 是一定可行的上界：这份资金不靠赞助也不会出现负余额。\n例：只有一笔 -5，k=0 时 need=5，x=ceil(5/2)=3，先翻倍为 6 再支出 5 即可。\n\n【边界与复杂度】k=0 是第一笔之前，k=n 是最后一笔之后，两端都要枚举。\n所有金额用 long long；need 非负时 need/2+need%2 为准确向上取整。\n读入求前缀和，再线性枚举时机，时间 O(n)，空间 O(n)。\n*/\n#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int n;\n    cin>>n;\n    vector<ll> pre(n+1,0);\n    // minPre：整个收支过程的最小前缀和，不是最小的单笔收支。\n    ll minPre=0;\n    for (int i=1;i<=n;i++){\n        ll x;\n        cin>>x;\n        pre[i]=pre[i-1]+x;\n        minPre=min(minPre,pre[i]);\n    }\n\n    // 不申请赞助时，至少需要 D 的启动资金才能使所有余额非负。\n    ll D=-minPre;\n    // leftMin 是当前申请前的最小前缀和；ans 是所有已考察申请时机中的最小资金。\n    ll leftMin=0,ans=D;\n    // 枚举完成前 k 笔收支之后申请；包含第一笔前 k=0、最后一笔后 k=n。\n    for (int k=0;k<=n;k++){\n        // 先纳入 pre[k]，因为申请前此刻的余额也必须合法，不能先负债再用赞助补救。\n        leftMin=min(leftMin,pre[k]);\n        // 申请前：余额为 x+pre[i]，要求 x>=-leftMin。\n        // 申请时余额翻倍，之后余额为 2*x+pre[k]+pre[i]。\n        // 因此还需 2*x>=D-pre[k]。取全局最小前缀不会增加无效限制：\n        // 对申请前的 i，2*x+pre[k]+pre[i]=(x+pre[k])+(x+pre[i])>=0。\n        ll need=max(0LL,D-pre[k]);\n        ll x=max(-leftMin,need/2+need%2); // need 非负，向上取整。\n        // k 只是一个可选择的申请时机，保留目前最省启动资金的方案。\n        ans=min(ans,x);\n    }\n    cout<<ans<<'\\n';\n    // 时间 O(n)，空间 O(n)。一笔 -5 的答案为 3，而不是 5。\n}\n"}],"statement":"","links":[],"editorial":"【题意模型】收支 a_i 按顺序发生，余额任何时刻都不能为负。\n可在某个时机申请一次赞助，把当时余额翻倍，求最少启动资金 x。\n\n【前缀和】pre[i]=前 i 笔收支之和，pre[0]=0。\n没有赞助时，第 i 笔之后余额为 x+pre[i]，所以最少需要\nD=-min(pre[0],pre[1],...,pre[n]) 的启动资金。\nminPre 初值为 0，把没有发生任何收支的初始时刻也纳入，确保 D>=0。\n\n【枚举在前 k 笔之后申请】\n申请前，所有 i<=k 都要满足 x+pre[i]>=0。\n令 leftMin=min(pre[0..k])，则第一个条件为 x>=-leftMin。\n申请时余额为 x+pre[k]，翻倍后再经历到第 i 笔，余额是：\n2*(x+pre[k])+(pre[i]-pre[k])=2*x+pre[k]+pre[i]，i>=k。\n因此第二个条件是 2*x>=-pre[k]-min(pre[k..n])。\n\n【为什么代码不用后缀最小值，而能用全局 D】\n在第一个条件成立时，对所有 i<=k，有\n2*x+pre[k]+pre[i]=(x+pre[k])+(x+pre[i])>=0。\n所以把第二个条件也检查到申请前的 i，不会加上真正的新限制。\n直接使用全局最小 pre[i]=-D，得到 2*x>=D-pre[k]。\n如果右边为负，资金至少为 0 已经满足它，先用 max(0,...) 截成非负。\n\n【每个时机的答案】x=max(-leftMin,ceil(max(0,D-pre[k])/2))。\n两个条件要同时满足，所以取 max；不同 k 任选一种，所以再对 x 取 min。\n初始 ans=D 是一定可行的上界：这份资金不靠赞助也不会出现负余额。\n例：只有一笔 -5，k=0 时 need=5，x=ceil(5/2)=3，先翻倍为 6 再支出 5 即可。\n\n【边界与复杂度】k=0 是第一笔之前，k=n 是最后一笔之后，两端都要枚举。\n所有金额用 long long；need 非负时 need/2+need%2 为准确向上取整。\n读入求前缀和，再线性枚举时机，时间 O(n)，空间 O(n)。","editorialSource":"原文件中的 AI 参考注释 · 请结合题面与原稿复核","number":"H","hasIssues":false},{"id":"cqu2026-G","title":"撕不干净的社团公告栏","source":"2026 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2026","category":"数据结构","tags":["栈","区间模拟","操作编号"],"level":"进阶","summary":"每个位置用栈保存覆盖层及操作编号，撕除时向两侧连续弹出同编号的顶层。","caution":"逐位置粘贴与撕除最坏为 O(nq)，存储所有覆盖层也需评估；对照 ERROR 原稿检查空栈。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/hyper/G 撕不干净的社团公告栏-hyper.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\n\r\nvoid solve(){\r\n    int n,q;\r\n    cin>>n>>q;\r\n    vector<vector<int>> ids(n+1);\r\n    vector<vector<string>> colors(n+1);\r\n    while (q--){\r\n        string c;\r\n        cin>>c;\r\n        if (c==\"P\"){\r\n            int l,r;\r\n            string color;\r\n            cin>>l>>r>>color;\r\n            for (int i=l;i<=r;i++){\r\n                ids[i].push_back(q);\r\n                colors[i].push_back(color);\r\n            }\r\n            \r\n            // cout<<\"P\"<<'\\n';\r\n            // for (int i=1;i<=n;i++){\r\n            //      if (colors[i].empty()) cout<<\".\";\r\n            //      else cout<<colors[i].back();\r\n            // }\r\n            // cout<<'\\n';\r\n            \r\n        }\r\n        else{\r\n            int x;\r\n            cin>>x;\r\n            if ((int)ids[x].size()<1) continue;\r\n            int id=ids[x].back();\r\n            ids[x].pop_back();\r\n            colors[x].pop_back();\r\n            for (int i=x-1;i>=1;i--){\r\n                if (!ids[i].empty() and ids[i].back()==id){\r\n                    ids[i].pop_back();\r\n                    colors[i].pop_back();\r\n                }\r\n                else break;\r\n            }\r\n            for (int i=x+1;i<=n;i++){\r\n                if (!ids[i].empty() and ids[i].back()==id){\r\n                    ids[i].pop_back();\r\n                    colors[i].pop_back();\r\n                }\r\n                else break;\r\n            }\r\n            \r\n            // cout<<\"T\"<<'\\n';\r\n            // for (int i=1;i<=n;i++){\r\n            //      if (colors[i].empty()) cout<<\".\";\r\n            //      else cout<<colors[i].back();\r\n            // }\r\n            // cout<<'\\n';\r\n            \r\n        }\r\n    }\r\n    for (int i=1;i<=n;i++){\r\n         if (colors[i].empty()) cout<<\".\";\r\n         else cout<<colors[i].back();\r\n    }\r\n    cout<<'\\n';\r\n}\r\n\r\nint main(){\r\n    int T=1;\r\n    // cin>>T;\r\n    while (T--) solve();\r\n}"},{"name":"ERROR 目录原稿","language":"C++","status":"error","path":"2026重庆大学程序设计新生赛暨邀请赛/src/ERROR/G 撕不干净的社团公告栏.cpp","code":"/*\r\nRE\r\n部分正确\r\n\r\n你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的\r\n\r\n错误记录（只补注释，未修改代码）：\r\n撕纸时只检查了 ids[x] 非空，左右邻居 ids[i] 可能为空，直接 back() 会触发 RE。\r\n反例：n=2、q=2，依次 P 1 1 A、T 1；正确输出 ..，向右扫描空的第 2 格时出错。\r\n左右两处都应先判断 !ids[i].empty()，再判断 ids[i].back()==id。\r\n空格必须停止延伸，不能跳过空格继续撕另一段。\r\n逐格维护叠层的思路符合本题规模，O(nq) 可行。\r\n使用独立纸条编号区分同色不同张纸是正确的，循环中的 q 值仍能提供唯一编号。\r\n\r\n右侧空容器反例：\r\n2 2\r\nP 1 1 A\r\nT 1\r\n期望输出：..\r\n中心格 1 撕完后，检查格 2 时 ids[2] 原本就是空的，不能读取 back()。\r\n\r\n左侧空容器反例：\r\n2 2\r\nP 2 2 A\r\nT 2\r\n期望输出：..\r\n检查左邻格 1 时，同样会在空 vector 上调用 back()。\r\n\r\n正确的判断顺序：先 !ids[i].empty()，再用 && 短路检查 ids[i].back()==id。\r\n不能反过来写成 back()==id && !empty()，因为左边已经先访问了空容器。\r\nids 与 colors 必须同步压入、同步弹出；当前代码在这一点上是同步的。\r\n每个格子仅弹一次、然后向尚未处理的邻格继续扫描，本身不会把新露出的下层再撕掉；\r\n这里确定的 RE 原因是缺少邻格非空判断，不是“用了 vector 模拟栈”。\r\n*/\r\n#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\n\r\nvoid solve(){\r\n    int n,q;\r\n    cin>>n>>q;\r\n    vector<vector<int>> ids(n+1);\r\n    vector<vector<string>> colors(n+1);\r\n    while (q--){\r\n        string c;\r\n        cin>>c;\r\n        if (c==\"P\"){\r\n            int l,r;\r\n            string color;\r\n            cin>>l>>r>>color;\r\n            for (int i=l;i<=r;i++){\r\n                ids[i].push_back(q);\r\n                colors[i].push_back(color);\r\n            }\r\n            \r\n            // cout<<\"P\"<<'\\n';\r\n            // for (int i=1;i<=n;i++){\r\n            //      if (colors[i].empty()) cout<<\".\";\r\n            //      else cout<<colors[i].back();\r\n            // }\r\n            // cout<<'\\n';\r\n            \r\n        }\r\n        else{\r\n            int x;\r\n            cin>>x;\r\n            if ((int)ids[x].size()<1) continue;\r\n            // 这里只能保证中心格 x 非空，不能推出后面左右邻格 i 也非空。\r\n            int id=ids[x].back();\r\n            ids[x].pop_back();\r\n            colors[x].pop_back();\r\n            for (int i=x-1;i>=1;i--){\r\n                // RE：左侧可能为空，必须先判断 !ids[i].empty()，再读取 back()。\r\n                if (ids[i].back()==id){\r\n                    ids[i].pop_back();\r\n                    colors[i].pop_back();\r\n                }\r\n                else break;\r\n            }\r\n            for (int i=x+1;i<=n;i++){\r\n                // RE：右侧同样可能为空；应使用短路 && 先判非空，空格直接停止。\r\n                if (ids[i].back()==id){\r\n                    ids[i].pop_back();\r\n                    colors[i].pop_back();\r\n                }\r\n                else break;\r\n            }\r\n            \r\n            // cout<<\"T\"<<'\\n';\r\n            // for (int i=1;i<=n;i++){\r\n            //      if (colors[i].empty()) cout<<\".\";\r\n            //      else cout<<colors[i].back();\r\n            // }\r\n            // cout<<'\\n';\r\n            \r\n        }\r\n    }\r\n    for (int i=1;i<=n;i++){\r\n         if (colors[i].empty()) cout<<\".\";\r\n         else cout<<colors[i].back();\r\n    }\r\n    cout<<'\\n';\r\n}\r\n\r\nint main(){\r\n    int T=1;\r\n    // cin>>T;\r\n    while (T--) solve();\r\n}\r\n"}],"statement":"","links":[],"number":"G","hasIssues":true},{"id":"cqu2026-F","title":"乘六除二","source":"2026 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2026","category":"数学与数论","tags":["质因子指数","线性方程"],"level":"基础","summary":"只维护 2 与 3 的指数，设乘 6 与除 2 次数，解非负整数条件。","caution":"先做乘法再做除法可保证操作合法，不必生成大整数。","versions":[{"name":"AC 目录存档","language":"Python","status":"ac-directory","path":"2026重庆大学程序设计新生赛暨邀请赛/src/AC/F 乘六除二-AC.py","code":"a,b,c,d=map(int,input().split())\r\nif (d-b)>=(c-a) and d-b>=0:\r\n    print(\"YES\")\r\nelse:\r\n    print(\"NO\")"},{"name":"AI 参考","language":"C++","status":"reference","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/AI/F 乘六除二-AI.cpp","code":"/*\n【把大数问题变成指数问题】\n不必计算实际的 2^a*3^b，因为它可能极大；只维护 2、3 的指数。\n初始指数为 (a,b)，目标指数为 (c,d)。\n乘 6=乘 2 再乘 3，因此两个指数各加 1；除 2 使 2 的指数减 1。\n\n【列方程】\n设乘 6 共 y 次，除 2 共 x 次，那么目标必须满足：\nc=a+y-x，d=b+y。\n解出 y=d-b，x=a+d-b-c，二者必须都是非负整数。\ny>=0 等价于 d>=b；x>=0 等价于 d-b>=c-a，这就是下面的两个条件。\n\n【仅次数非负，能否保证每次操作都合法】\n可以先完成所有乘 6，再完成所有除 2。\n开始除法时 2 的指数为 a+y，随后逐渐降到目标 c；因为 c>=0，\n每次需要除 2 时指数都至少为 1，不会除出非整数，数值始终为正。\n所以两个不等式既必要又充分，不需要模拟操作顺序。\n\n【例子】初始 a=1,b=0，目标 c=0,d=0：y=0、x=1，把 2 除 2 得到 1。\n若 a=b=0，目标 c=2,d=0，则需要 y=0、x=-2，不可能只增大 2 的指数。\n本题只有一组输入，答案必须使用大写 YES/NO。时间、空间均 O(1)。\n*/\n#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    ll a,b,c,d;\n    cin>>a>>b>>c>>d;\n    // 初始数 2^a*3^b，目标数 2^c*3^d，不必真正计算这两个大数。\n    // 除以 2：2 的指数 -1；乘以 6：2、3 的指数各 +1。\n    // 设乘 6 共 y 次、除 2 共 x 次：y=d-b，x=a+y-c。\n    // x、y 均非负时，先乘完再除，能保持每次除法合法且结果为正整数。\n    // x>=0 等价于 d-b>=c-a，避免把多个指数相加。\n    // 第一个条件说明 3 的指数不能减少；第二个说明可用的 2 足够除到目标。\n    // 用差值比较，无需把指数相加后再相减，也避免计算真正的幂。\n    if (d>=b && d-b>=c-a) cout<<\"YES\\n\";\n    else cout<<\"NO\\n\";\n}\n"}],"statement":"","links":[],"editorial":"【把大数问题变成指数问题】\n不必计算实际的 2^a*3^b，因为它可能极大；只维护 2、3 的指数。\n初始指数为 (a,b)，目标指数为 (c,d)。\n乘 6=乘 2 再乘 3，因此两个指数各加 1；除 2 使 2 的指数减 1。\n\n【列方程】\n设乘 6 共 y 次，除 2 共 x 次，那么目标必须满足：\nc=a+y-x，d=b+y。\n解出 y=d-b，x=a+d-b-c，二者必须都是非负整数。\ny>=0 等价于 d>=b；x>=0 等价于 d-b>=c-a，这就是下面的两个条件。\n\n【仅次数非负，能否保证每次操作都合法】\n可以先完成所有乘 6，再完成所有除 2。\n开始除法时 2 的指数为 a+y，随后逐渐降到目标 c；因为 c>=0，\n每次需要除 2 时指数都至少为 1，不会除出非整数，数值始终为正。\n所以两个不等式既必要又充分，不需要模拟操作顺序。\n\n【例子】初始 a=1,b=0，目标 c=0,d=0：y=0、x=1，把 2 除 2 得到 1。\n若 a=b=0，目标 c=2,d=0，则需要 y=0、x=-2，不可能只增大 2 的指数。\n本题只有一组输入，答案必须使用大写 YES/NO。时间、空间均 O(1)。","editorialSource":"原文件中的 AI 参考注释 · 请结合题面与原稿复核","number":"F","hasIssues":false},{"id":"cqu2026-E","title":"奶茶拼团！第二杯半价！","source":"2026 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2026","category":"动态规划","tags":["线性DP","相邻配对"],"level":"进阶","summary":"只看最后一单，枚举第 i 人独买或最后两人拼单，得到前缀最小费用。","caution":"不能将原本不相邻的人拼单；注意半价的数值精度。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/hyper/E 奶茶拼团！第二杯半价！-hyper.cpp","code":"#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\nconst ll INF=LLONG_MAX;\n\nvoid solve(){\n    int n;\n    cin>>n;\n    vector<ll> a(n+1,0);\n    vector<ll> dp(n+1,INF);\n    dp[0]=0;\n    cin>>a[1];\n    dp[1]=a[1];\n    for (int i=2;i<=n;i++){\n        cin>>a[i];\n        dp[i]=min(dp[i-1]+a[i],dp[i-2]+max(a[i],a[i-1])+min(a[i],a[i-1])/2);\n    }\n    cout<<dp[n]<<'\\n';\n}\n\nint main(){\n    int T=1;\n    // cin>>T;\n    while (T--) solve();\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/AI/E 奶茶拼团！第二杯半价！-AI.cpp","code":"/*\n【核心】把原队伍划分成长度为 1 或 2 的连续段，每段独立结账。\n不能把原来不相邻的人凑在一起，前面的人离开也不会创造新拼单关系。\n\n【DP（Dynamic Programming，动态规划）状态】\ndp[i]：已经让原队伍前 i 人全部结账时，能够达到的最小总费用。\ndp[0]=0 表示没有人需要买奶茶，费用为 0。\n\n【只考虑最后一笔账单】\n1. 第 i 人单独付钱：前 i-1 人最优处理，费用 dp[i-1]+a[i]。\n2. 第 i-1 与第 i 人拼单：前 i-2 人最优处理，这一对的费用为\n   max(a[i-1],a[i])+min(a[i-1],a[i])/2。\n这两种情况穷尽最后一笔账单，取较小值即可，不用枚举所有区间。\n\n【为什么不能固定从头两两拼】\n例如价格 2、100、100、2：固定拼 (1,2)、(3,4) 需要 202；\n让中间两人拼单，两端各自付钱，只需 2+150+2=154。\n因此需要 DP 自动决定边界，而不是固定分组或只选某一对优惠最大的。\n\n【实现与复杂度】\n先读完整个价格数组，再从小到大算 dp，确保用到的更短前缀已经算好。\ni=1 时只能单付；i>=2 才允许访问 a[i-1]、dp[i-2]。\n所有原价为偶数，整数除以 2 就是准确半价；费用统一用 long long。\n时间 O(n)，空间 O(n)。\n*/\n#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int n;\n    cin>>n;\n    // 下标从 1 开始，a[0] 不作为任何同学的价格；dp[0] 用作空前缀边界。\n    vector<ll> a(n+1),dp(n+1,0);\n    for (int i=1;i<=n;i++) cin>>a[i];\n\n    // dp[i]：前 i 人都完成结账的最小费用，dp[0]=0。\n    for (int i=1;i<=n;i++){\n        dp[i]=dp[i-1]+a[i]; // 最后一人单独结账。\n        // 两个人结账必须同时消耗这两个名额，不能与 dp[i-1] 组合，否则第 i-1 人会重计。\n        if (i>=2){\n            // 最后两人一起结账，原队伍中相邻，且不再参与其他结账。\n            ll cost=max(a[i-1],a[i])+min(a[i-1],a[i])/2;\n            // dp[i] 当前保存单付方案，再与最后两人拼单方案比较。\n            dp[i]=min(dp[i],dp[i-2]+cost);\n        }\n    }\n    cout<<dp[n]<<'\\n';\n    // 时间 O(n)，空间 O(n)。\n}\n"},{"name":"ERROR 目录原稿","language":"C++","status":"error","path":"2026重庆大学程序设计新生赛暨邀请赛/src/ERROR/E 奶茶拼团！第二杯半价！.cpp","code":"/*\r\nMLE\r\n部分正确\r\n\r\n你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的你🐎的\r\n\r\n错误记录（只补注释，未修改代码）：\r\n主要问题是规模，不是这套区间转移在小数据上的计算结果。\r\n1. 二维 dp 空间 O(n^2)，n=200000 时元素约需 320 GB，直接内存超限。\r\n2. len、l、k 三层循环时间 O(n^3)，即使内存足够也会运行超时。\r\n本次 120 组随机小数据与线性 DP 的答案一致，不必把 MLE 当成转移式写错。\r\n优化方向：dp[i] 表示前 i 人最小费用，dp[0]=0；最后一人单独或最后两人拼单：\r\ndp[i]=dp[i-1]+a[i]；若 i>=2，再与\r\ndp[i-2]+max(a[i-1],a[i])+min(a[i-1],a[i])/2 取 min。\r\n线性 DP 时间 O(n)、空间 O(n)，也可以滚动到 O(1) 额外空间。\r\n\r\n容量估算：dp 有 (n+2)*(n+1) 项，每项 long long 通常占 8 字节。\r\nn=6000 时，仅元素约 288 MB 就已超过 256 MiB；n=200000 时约 320 GB。\r\n这不是少开几行、改成 int、取消初始化就能解决的问题，必须减少状态维度。\r\n\r\n为什么没有把当前区间转移另判为逻辑错误：\r\n每对相邻学生拼单都会比各自单付便宜，因此长度至少为 2 的最优方案一定含一对。\r\n枚举这一对，再把左右剩余部分分别最优结账，能够覆盖最优方案；问题是太慢、太占内存。\r\n本题只需要考虑最后一笔账单是一人还是两人，完全不必记录所有左右端点。\r\n\r\n线性 DP 的边界提醒：dp[0]=0，dp[1]=a[1]；i>=2 才访问 a[i-1] 和 dp[i-2]。\r\n例如 n=1、价格 2，答案为 2；n=2、价格 2 4，答案为 5。\r\n不要强制从队首固定两两配对，也不要只按单次优惠最大贪心挑一对。\r\n*/\r\n#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\n\r\nvoid solve(){\r\n    int n;\r\n    cin>>n;\r\n    vector<ll> a(n+1,0);\r\n    // MLE 根源：这里分配约 n*n 个 long long，题目 n 最大为 2e5。\r\n    vector<vector<ll>> dp(n+2,vector<ll>(n+1,INF));\r\n    for (int i=1;i<=n;i++){\r\n        cin>>a[i];\r\n        dp[i][i]=a[i];\r\n    }\r\n    for (int l=1;l<=n;l++){\r\n        if (l!=n) dp[l][l+1]=min(a[l],a[l+1])/2+max(a[l],a[l+1]);\r\n        dp[l][l]=a[l];\r\n    }\r\n    // TLE 根源：区间长度、左端点、拼单位置三层枚举，整体 O(n^3)。\r\n    // 只需处理前缀，并考虑最后一人单独结账或最后两人拼单。\r\n    for (int len=3;len<=n;len++){\r\n        for (int l=1;l+len<=n+1;l++){\r\n            int r=l+len-1;\r\n            for (int k=l;k<=r-1;k++){\r\n                // 这对的费用本身计算正确：较贵的原价 + 较便宜的一半。\r\n                // 已选一对后再枚举左右子区间属于不必要的三次方规模，不是这里价格公式错。\r\n                int x=min(a[k],a[k+1])/2+max(a[k],a[k+1]);\r\n                if (k==l) dp[l][r]=min(dp[l][r],x+dp[k+2][r]);\r\n                else if (k+1==r) dp[l][r]=min(dp[l][r],dp[l][k-1]+x);\r\n                else dp[l][r]=min(dp[l][r],dp[l][k-1]+x+dp[k+2][r]);\r\n            }\r\n        }\r\n    }\r\n    cout<<dp[1][n]<<'\\n';\r\n}\r\n\r\nint main(){\r\n    int T=1;\r\n    // cin>>T;\r\n    while (T--) solve();\r\n}\r\n"}],"statement":"","links":[],"editorial":"【核心】把原队伍划分成长度为 1 或 2 的连续段，每段独立结账。\n不能把原来不相邻的人凑在一起，前面的人离开也不会创造新拼单关系。\n\n【DP（Dynamic Programming，动态规划）状态】\ndp[i]：已经让原队伍前 i 人全部结账时，能够达到的最小总费用。\ndp[0]=0 表示没有人需要买奶茶，费用为 0。\n\n【只考虑最后一笔账单】\n1. 第 i 人单独付钱：前 i-1 人最优处理，费用 dp[i-1]+a[i]。\n2. 第 i-1 与第 i 人拼单：前 i-2 人最优处理，这一对的费用为\n   max(a[i-1],a[i])+min(a[i-1],a[i])/2。\n这两种情况穷尽最后一笔账单，取较小值即可，不用枚举所有区间。\n\n【为什么不能固定从头两两拼】\n例如价格 2、100、100、2：固定拼 (1,2)、(3,4) 需要 202；\n让中间两人拼单，两端各自付钱，只需 2+150+2=154。\n因此需要 DP 自动决定边界，而不是固定分组或只选某一对优惠最大的。\n\n【实现与复杂度】\n先读完整个价格数组，再从小到大算 dp，确保用到的更短前缀已经算好。\ni=1 时只能单付；i>=2 才允许访问 a[i-1]、dp[i-2]。\n所有原价为偶数，整数除以 2 就是准确半价；费用统一用 long long。\n时间 O(n)，空间 O(n)。","editorialSource":"原文件中的 AI 参考注释 · 请结合题面与原稿复核","number":"E","hasIssues":true},{"id":"cqu2026-D","title":"贰零壹贰","source":"2026 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2026","category":"动态规划","tags":["相邻交换","逆序对","有限排列"],"level":"挑战","summary":"枚举 0122 的 12 种排列，四阶段 DP 选位置，把聚拢费用与内部逆序对费用相加。","caution":"阶段倒序更新，不能重复选同一位置；状态值可以为负。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/hyper/D 贰零壹贰-hyper.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\n\r\nvector<pair<string,int>> patterns;\r\n\r\nvoid solve(){\r\n    ll n;\r\n    cin>>n;\r\n    string s;\r\n    cin>>s;\r\n    vector<int> cnt(3,0);\r\n    for (char c : s) cnt[c-'0']++;\r\n    if (cnt[0]<1 or cnt[1]<1 or cnt[2]<2){\r\n        cout<<-1<<'\\n';\r\n        return;\r\n    }\r\n    ll ans=INF;\r\n\r\n    for (const auto& [pat,inv] : patterns){\r\n        vector<ll> dp(5,INF);\r\n        dp[0]=0;\r\n        for (ll i=0;i<n;i++){\r\n            for (ll j=4;j>=1;j--){\r\n                if (s[i]!=pat[j-1] or dp[j-1]==INF) continue;\r\n                ll cost= j>=3 ? i : -i;\r\n                dp[j]=min(dp[j],dp[j-1]+cost);\r\n            }\r\n        }\r\n        if (dp[4]!=INF) ans=min(ans,dp[4]-4+inv);\r\n    }\r\n    ans= ans==INF ? -1 :ans;\r\n    cout<<ans<<'\\n';\r\n}\r\n\r\nint main(){\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    \r\n    string pat=\"0122\";\r\n    do{\r\n        int rank[4],count2=0,inv=0;\r\n        for (ll i=0;i<4;i++){\r\n            if (pat[i]=='0') rank[i]=1;\r\n            else if (pat[i]=='1') rank[i]=2;\r\n            else if (pat[i]=='2') rank[i]=count2++==0 ? 0 : 3; \r\n        }\r\n        for (int i=0;i<4;i++){\r\n            for (int j=i+1;j<4;j++){\r\n                if (rank[i]>rank[j]) inv++;\r\n            }\r\n        }\r\n        patterns.push_back({pat,inv});\r\n    } while (next_permutation(pat.begin(),pat.end()));\r\n    \r\n    int T;\r\n    cin>>T;\r\n    while (T--) solve();\r\n}\r\n\r\n"},{"name":"AI 参考","language":"C++","status":"reference","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/AI/D 贰零壹贰-AI.cpp","code":"/*\n【先看这份程序在干什么】\n目标始终是：交换相邻字符，使原串出现连续的 2012。\n最终这四个字符一定来自原串中的某四个位置，我们要找“选哪四个位置”最省交换。\n可以按以下顺序理解，不必一开始就接受 DP 公式：\n    1. 选中的四个字符，原来是什么顺序？\n    2. 把它们挤成连续四格，需要几次？\n    3. 连续四格内部再调整成 2012，需要几次？\n    4. 怎样不枚举四个位置，也能找到最便宜的选法？\n\n一、pat 是“原来的顺序”，不是“最终目标”\n------------------------------------------------------------\n最终目标永远是 2012，但选中的四个字符原来不一定按 2012 排列。\n例如原串 0122：0122 -> 0212 -> 2012，只需 2 次。\n因此只寻找原串里现成的 2012 子序列，会漏掉答案。\n\n四个选中字符必须恰好为一个 0、一个 1、两个 2。\n它们原来的顺序可能是 0122、0212、2012、2210 等，共 12 种不同排列。\n变量 pat 表示其中一种；程序把 12 种全部尝试，再取最小答案。\n同一个 pat 还可能对应很多组不同位置，这些位置选法由后面的 DP 处理。\n\n二、先只考虑把四个选中字符挤成连续四格\n------------------------------------------------------------\n按原串从左到右，把选中的位置记为 p0<p1<p2<p3，下标从 0 开始。\n为了画图，临时把四个选中字符标成 A、B、C、D，没有选中的字符画成点：\n\n    A ... B ..... C .. D\n      g0     g1    g2\n\n点仍是输入中的 0、1、2，只是本次没有选中，不是额外的字符种类。\n三个间隙里“没选中字符”的数量分别为：\n    g0=p1-p0-1，g1=p2-p1-1，g2=p3-p2-1。\n\n为什么聚拢的最少费用是 g0+2*g1+g2？\n  - A、B 之间的一个点，要移到四个选中字符之外：\n    往左只需跨过 A（1 次），往右需跨过 B、C、D（3 次），选便宜的左边。\n  - B、C 之间的一个点：\n    往左需跨过 A、B，往右需跨过 C、D，都要 2 次。\n  - C、D 之间的一个点：\n    往右只需跨过 D（1 次），选便宜的右边。\n所以三个间隙里的每个点，分别需要 1、2、1 次交换。\n\n这个下界能做到：先让 A 向右靠到 B，让 D 向左靠到 C；\n再把相邻的 AB 整体向右移动，跨过中间的点，与 CD 接起来。\n四个选中字符便连续了，彼此顺序仍为原来的 pat。\n原本就在 A 左边或 D 右边的字符不挡路，不需要额外处理。\n\n把间隙公式展开：\n    (p1-p0-1)+2*(p2-p1-1)+(p3-p2-1)\n  = -p0-p1+p2+p3-4。\n\n例如选中位置为 1、3、6、8，间隙为 1、2、1：\n    聚拢费用 = 1+2*2+1 = 6；\n    展开式   = -1-3+6+8-4 = 6。\n代码中的 -4 就来自间隙公式，不是额外做了 4 次操作。\n\n三、再把连续四格内部的顺序从 pat 调整成 2012\n------------------------------------------------------------\n目标 2012 的四个位置编号如下：\n    目标字符：2 0 1 2\n    目标位置：0 1 2 3\n\n所以字符 0 要去位置 1，字符 1 要去位置 2。\n两个 2 按原有先后分别去位置 0、3，交换两个相同的 2 没有收益。\nrank 保存“每个字符最终要去哪个位置”，不是按字符大小排名。\n\n例如 pat=0122，映射后得到 rank=[1,2,0,3]。\n这里 1 在 0 前、2 在 0 前，都与最终 [0,1,2,3] 的顺序相反。\n这种“左边编号比右边大”的一对叫逆序对，本例有 2 对。\n一次相邻交换最多消掉一个逆序对；按冒泡排序逐个消掉，也确实能做到。\n因此逆序对数量 inv 就是内部重排的最少交换次数：\n    0122 -> 0212 -> 2012，正好 2 次。\n\n聚拢时交换“选中字符与没选中字符”，内部重排时交换“两个选中字符”。\n两类必要交换不互相抵扣；先聚拢再重排能达到两部分费用之和。\n所以固定选中位置和原始顺序后：\n    完整费用 = -p0-p1+p2+p3-4+inv。\n\n四、DP 怎样避免枚举所有四元组\n------------------------------------------------------------\nDP 是 Dynamic Programming（动态规划）。\n直接四层循环枚举 p0、p1、p2、p3 太慢。\n但固定 pat 后，inv 已经固定，-4 也固定，只需最小化：\n    -p0-p1+p2+p3。\n\n把“选择四个字符”拆成四个阶段。扫描过原串的某一段后：\n    dp[0]：没选字符，值为 0。\n    dp[1]：选好 pat 第 1 位，保存 -p0 的最小值。\n    dp[2]：选好 pat 前 2 位，保存 -p0-p1 的最小值。\n    dp[3]：选好 pat 前 3 位，保存 -p0-p1+p2 的最小值。\n    dp[4]：四位全选好，保存 -p0-p1+p2+p3 的最小值。\nINF 表示还没有合法选法；这些状态不是方案数量，也不是完整交换次数。\n例如 dp[2] 为负完全正常，不能因为“费用不能为负”就把它改成 0。\n\n扫描到原下标 i，如果当前字符等于 pat 的第 j 位，可以把它接到前 j-1 位后面：\n    选第 1、2 位：本次位置在公式中贡献 -i。\n    选第 3、4 位：本次位置在公式中贡献 +i。\n    新候选 = dp[j-1]+本次贡献。\n    dp[j] 取“原来的值”与“新候选”的较小者。\n保留原值表示不选当前字符，采用新候选表示选择当前字符。\n\n为什么不记录之前具体选了哪些位置？\n扫描从左到右，旧状态所选位置全在当前 i 左侧，先后顺序已由扫描保证。\n同一阶段的两个旧方案，接下来的候选都来自尚未扫描的后缀；\n谁当前的数值更小，接上同样的后续位置后谁仍更小，所以只留最小值就够了。\n\n五、把原串 0122、pat=0122 的 DP 完整算一遍\n------------------------------------------------------------\n此 pat 的 inv=2，INF 表示该阶段还做不到：\n\n    处理到哪里          dp[0] dp[1] dp[2] dp[3] dp[4]\n    还没扫描              0   INF   INF   INF   INF\n    下标 0 的 '0'         0     0   INF   INF   INF\n    下标 1 的 '1'         0     0    -1   INF   INF\n    下标 2 的第一个 '2'   0     0    -1     1   INF\n    下标 3 的第二个 '2'   0     0    -1     1     4\n\n各次有效转移：\n    dp[1]=dp[0]-0=0；\n    dp[2]=dp[1]-1=-1；\n    dp[3]=dp[2]+2=1；\n    dp[4]=dp[3]+3=4。\n最终答案为 dp[4]-4+inv=4-4+2=2。\n4 是下标表达式的结果；减去 4 后聚拢费为 0，再加 2 次内部交换。\n\n六、为什么 j 必须倒序更新\n------------------------------------------------------------\npat=0122 的最后两位都是 2，扫描到原串的第一个 2 时：\n如果先更新 dp[3]，再用刚更新的 dp[3] 更新 dp[4]，\n就把同一个原下标同时当作两个 2，错误地选了一次又选一次。\n本例甚至会算出 dp[4]=3，最后得到错误答案 1。\n\n倒序时先尝试 dp[4]，它只能读取上一轮的 dp[3]；\n之后才更新 dp[3]，因此同一个位置在同一条选择方案里最多用一次。\n\n【程序运行顺序】\nmain 先生成 12 种 pat，计算各自的 inv，存进 patterns，所有测试组复用。\n每组 solve：检查字符数量 -> 枚举 pat -> 扫描原串做四阶段 DP -> 取最小答案。\n缺少 0、1 或不足两个 2 时才无解，因为交换不能创造字符；\n数量满足时，总能通过重新排列得到 2012。\n\n每种 pat 扫描 n 位，每位只试 4 个阶段；12 是常数，总时间 O(n)。\n除输入字符串外，只需要固定大小的 DP 和排列记录，额外空间 O(1)。\n*/\n#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\n// INF 是 infinity 的缩写，表示状态暂时不可达。\n// 选一个很大的数作标记，但使用时仍先判断是不是 INF，不能直接当真实费用计算。\nconst ll INF=LLONG_MAX/4;\n\n// patterns 保存 12 项 {原始顺序 pat,内部最少交换次数 inv}，不保存原串下标。\n// pair 的 first 是字符串，second 是整数。\nvector<pair<string,int>> patterns;\n\nvoid solve(){\n    // 这是一组测试数据；n 是原串长度，s 是实际字符串。\n    int n;\n    string s;\n    cin>>n>>s;\n    // cnt 是 count（计数），分别统计字符 0、1、2 的个数。\n    int cnt[3]={0,0,0};\n    // c-'0' 把字符 '0'/'1'/'2' 转成数字 0/1/2，才能用作数组下标。\n    for (char c : s) cnt[c-'0']++;\n    // 相邻交换只能移动字符，不能改变数量。缺字符时直接输出 -1。\n    if (cnt[0]<1 || cnt[1]<1 || cnt[2]<2){\n        cout<<-1<<'\\n';\n        return;\n    }\n\n    // ans 记录所有 pat、所有位置选法中的最少完整交换次数。\n    // 不能初始化成 0，否则后面取 min 会一直留在 0。\n    ll ans=INF;\n    // 把 pair 拆成 pat 和 inv 两个名字。const auto& 只读原记录，不复制字符串。\n    // 本轮只考虑选中字符原来按 pat 排列，最终目标仍然是 2012。\n    for (const auto& [pat,inv] : patterns){ \n        // 五个阶段下标为 0..4：dp[4] 最终保存 -p0-p1+p2+p3。\n        // 只有四个位置全选齐，再减 4、加 inv 后，才是完整交换次数。\n        array<ll,5> dp;\n        // 每种 pat 都重新初始化，不继承上一个排列的选择结果。\n        dp.fill(INF);\n        // 没选任何字符是合法起点，当前表达式为 0；其余阶段暂时不可达。\n        dp[0]=0;\n        // i 是原串下标，不是字符值，也不是已经选了几个字符。\n        for (int i=0;i<n;i++){\n            // j 表示想把 s[i] 作为 pat 的第几位，范围 1..4。\n            // 必须先更新大阶段再更新小阶段，避免当前一个位置在同轮被选两次。\n            for (int j=4;j>=1;j--){\n                // pat 下标从 0 开始，所以第 j 位访问 pat[j-1]。\n                // 当前字符不匹配，或者前 j-1 位还没选到，就不能向这个阶段转移。\n                // continue 只跳过这次 j，不会结束整串扫描。\n                if (s[i]!=pat[j-1] || dp[j-1]==INF) continue;\n                // 条件运算符：前两阶段贡献 -i，后两阶段贡献 +i。\n                // cost 是当前下标在公式中的一项，不是单独移动这个字符要花的次数。\n                ll cost=(j<=2 ? -1LL : 1LL)*i;\n                // 原 dp[j]：不选当前位，保留旧方案。\n                // dp[j-1]+cost：选当前位接到已选前缀后面。比较后只留更小的表达式结果。\n                // 如 j=2 时，新候选为 -p0-i，表示把当前 i 选为 p1。\n                dp[j]=min(dp[j],dp[j-1]+cost);\n            }\n        }\n        // 若 dp[4] 仍是 INF，说明原串里找不到这种原始顺序的四个位置。\n        // 否则 dp[4]-4 是聚拢费用，inv 是固定的内部重排费用，两者相加更新答案。\n        if (dp[4]!=INF) ans=min(ans,dp[4]-4+inv);\n    }\n    // 这里只输出最少交换次数，不输出实际选择的位置或交换步骤。\n    cout<<ans<<'\\n';\n}\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    // 这一段只与四个目标字符有关，与具体测试串无关，所以放在读取 T 前做一次。\n    // 从字典序最小的 0122 开始，才能用 next_permutation 不遗漏地枚举所有排列。\n    string pat=\"0122\";\n    // do...while 先处理当前排列，再判断能否变到下一种；初始的 0122 也会被处理。\n    do{\n        // rank[i] 是 pat 第 i 个字符在目标 2012 中应去的位置。\n        // count2 用于区分先遇到和后遇到的两个 2；每种 pat 都从 0 重新计数。\n        // inv 是 inversion count（逆序对数），不是逆元。\n        int rank[4],count2=0,inv=0;\n        for (int i=0;i<4;i++){\n            // 目标 2012 的下标 1 是字符 0，下标 2 是字符 1。\n            if (pat[i]=='0') rank[i]=1;\n            else if (pat[i]=='1') rank[i]=2;\n            // 剩下必是字符 2。count2++ 先用旧值比较，再递增：\n            // 第一个 2 的旧值为 0，去目标下标 0；第二个去目标下标 3。\n            else rank[i]=(count2++==0 ? 0 : 3);\n        }\n        // 对四个目标编号统计逆序对：只枚举 i<j，同一对不重复统计。\n        for (int i=0;i<4;i++){\n            for (int j=i+1;j<4;j++){\n                // 如果靠左的字符在目标中应当更靠右，这一对就需要改变先后顺序。\n                if (rank[i]>rank[j]) inv++;\n            }\n        }\n        // 保存该排列及它固定的内部交换费，后续每组输入直接使用。\n        patterns.push_back({pat,inv});\n    // 两个 2 相同，next_permutation 只枚举不同的字符排列，因此是 12 项而非 24 项。\n    // 当已经是最后一个排列时返回 false，结束预处理。\n    }while (next_permutation(pat.begin(),pat.end()));\n\n    int T;\n    cin>>T;\n    // 每组 solve 内重新创建 cnt、ans、dp，各组数据不会互相影响。\n    while (T--) solve();\n}\n"},{"name":"ERROR 目录原稿","language":"C++","status":"error","path":"2026重庆大学程序设计新生赛暨邀请赛/src/ERROR/D 贰零壹贰.cpp","code":"/*\r\n部分正确\n\n错误记录（只补注释，未修改代码）：\n1. 只寻找原串已有的 2、0、1、2 顺序，漏掉通过交换改变字符顺序的方案。\n   反例：T=1，n=4，s=0122；0122 -> 0212 -> 2012，只需 2 次，当前输出 -1。\n2. 未找到 01 时 min01=LLONG_MAX，仍参与加法，可能产生巨大错误值或有符号溢出。\n   反例：T=1，n=6，s=200002；缺少 1，应输出 -1，当前测试输出 LLONG_MIN。\n3. 两层枚举 2 的位置，加上内部寻找 0、1，最坏可达 O(n^4)，不能处理 n=2e5。\n只加 min01!=INF 判断能修复哨兵参与运算，不能修复漏掉交换顺序或复杂度问题。\n\r\n可直接运行的反例：\r\n输入：\r\n1\r\n4\r\n0122\r\n期望输出：2；当前输出：-1。\r\n两个 2 原先相邻，不代表无解；它们可以通过相邻交换移动到目标的两端。\r\n\r\n输入：\r\n1\r\n4\r\n2002\r\n期望输出：-1；当前输出：9223372036854775806（LLONG_MAX-1）。\r\n这里甚至不需要发生溢出：min01 仍为 INF，却被减去 1，变成貌似有效的候选。\r\n之后只判断 ans==INF 已经识别不出“根本没有找到 01”。\r\n\r\n输入：\r\n1\r\n6\r\n200002\r\n期望输出：-1；此时 INF 参与加法还会触发有符号整数溢出，属于未定义行为。\r\n旧测试出现 LLONG_MIN，但不能依赖所有编译器都输出相同数值。\r\n\r\n性能反例结构：很多 2 + 很多 0 + 很多 2，且没有 1。\r\n两侧 2 的位置对有平方级，每一对又在中间反复扫描 0 和其后字符，可达到四次方级。\r\n正确方向：枚举 0、1、2、2 的 12 种原始顺序，不局限于现成的 2012 子序列；\r\n选中下标 p0<p1<p2<p3 的代价为 -p0-p1+p2+p3-4 加内部重排的逆序对数。\r\n每种顺序用四阶段子序列 DP 可线性求最小位置代价。\r\n*/\n#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\n\r\nvoid solve(){\r\n    ll n;\r\n    cin>>n;\r\n    string s;\r\n    cin>>s;\r\n    vector<ll> plc2;\r\n    for (ll i=0;i<n;i++){\r\n        if (s[i]=='2') plc2.push_back(i);\r\n    }\r\n    ll n2=plc2.size();\n    ll ans=INF;\n    // 性能：这里枚举所有 2 的位置对，内部又逐项找 01，最坏复杂度过高。\n    for (ll i=0;i<n2-1;i++){\n        for (ll j=i+1;j<n2;j++){\n            // 逻辑遗漏：原来两个 2 距离不足 3，也可能通过交换与其他字符构成 2012。\n            if (plc2[j]-plc2[i]<3) continue;\n            // INF 只表示“未找到合法 01”，不能把它当真实费用参与后面的加减。\r\n            ll min01=INF;\r\n            for (ll k0=plc2[i]+1;k0<=plc2[j]-2;k0++){\r\n                if (s[k0]=='0'){\r\n                    for (int k1=k0+1;k1<=plc2[j]-1;k1++){\r\n                        if (s[k1]=='1'){\r\n                            min01=min(min01,k1-k0);\r\n                            break;  \r\n                        }\r\n                    }\r\n                }\n            }\n            // 溢出风险：min01 可能仍是 INF；必须先确认找到 01，才能代入代价公式。\n            // 这条公式只覆盖选中字符原本已按 2012 顺序排列的情况。\n            ans=min(ans,plc2[j]-plc2[i]-3+min01-1);\n        }\r\n    }\r\n    // 仅判断等于 INF 不足以补救前面的错误：INF-1 或溢出结果都不会在此变成 -1。\r\n    if (ans==INF) ans=-1;\r\n    cout<<ans;\r\n}\r\n\r\nint main(){\r\n    int T=1;\r\n    cin>>T;\r\n    while (T--){\r\n        solve();\r\n        if (T) cout<<'\\n';\r\n    }\r\n}\n"}],"statement":"","links":[],"editorial":"【先看这份程序在干什么】\n目标始终是：交换相邻字符，使原串出现连续的 2012。\n最终这四个字符一定来自原串中的某四个位置，我们要找“选哪四个位置”最省交换。\n可以按以下顺序理解，不必一开始就接受 DP 公式：\n    1. 选中的四个字符，原来是什么顺序？\n    2. 把它们挤成连续四格，需要几次？\n    3. 连续四格内部再调整成 2012，需要几次？\n    4. 怎样不枚举四个位置，也能找到最便宜的选法？\n\n一、pat 是“原来的顺序”，不是“最终目标”\n------------------------------------------------------------\n最终目标永远是 2012，但选中的四个字符原来不一定按 2012 排列。\n例如原串 0122：0122 -> 0212 -> 2012，只需 2 次。\n因此只寻找原串里现成的 2012 子序列，会漏掉答案。\n\n四个选中字符必须恰好为一个 0、一个 1、两个 2。\n它们原来的顺序可能是 0122、0212、2012、2210 等，共 12 种不同排列。\n变量 pat 表示其中一种；程序把 12 种全部尝试，再取最小答案。\n同一个 pat 还可能对应很多组不同位置，这些位置选法由后面的 DP 处理。\n\n二、先只考虑把四个选中字符挤成连续四格\n------------------------------------------------------------\n按原串从左到右，把选中的位置记为 p0<p1<p2<p3，下标从 0 开始。\n为了画图，临时把四个选中字符标成 A、B、C、D，没有选中的字符画成点：\n\n    A ... B ..... C .. D\n      g0     g1    g2\n\n点仍是输入中的 0、1、2，只是本次没有选中，不是额外的字符种类。\n三个间隙里“没选中字符”的数量分别为：\n    g0=p1-p0-1，g1=p2-p1-1，g2=p3-p2-1。\n\n为什么聚拢的最少费用是 g0+2*g1+g2？\n  - A、B 之间的一个点，要移到四个选中字符之外：\n    往左只需跨过 A（1 次），往右需跨过 B、C、D（3 次），选便宜的左边。\n  - B、C 之间的一个点：\n    往左需跨过 A、B，往右需跨过 C、D，都要 2 次。\n  - C、D 之间的一个点：\n    往右只需跨过 D（1 次），选便宜的右边。\n所以三个间隙里的每个点，分别需要 1、2、1 次交换。\n\n这个下界能做到：先让 A 向右靠到 B，让 D 向左靠到 C；\n再把相邻的 AB 整体向右移动，跨过中间的点，与 CD 接起来。\n四个选中字符便连续了，彼此顺序仍为原来的 pat。\n原本就在 A 左边或 D 右边的字符不挡路，不需要额外处理。\n\n把间隙公式展开：\n    (p1-p0-1)+2*(p2-p1-1)+(p3-p2-1)\n  = -p0-p1+p2+p3-4。\n\n例如选中位置为 1、3、6、8，间隙为 1、2、1：\n    聚拢费用 = 1+2*2+1 = 6；\n    展开式   = -1-3+6+8-4 = 6。\n代码中的 -4 就来自间隙公式，不是额外做了 4 次操作。\n\n三、再把连续四格内部的顺序从 pat 调整成 2012\n------------------------------------------------------------\n目标 2012 的四个位置编号如下：\n    目标字符：2 0 1 2\n    目标位置：0 1 2 3\n\n所以字符 0 要去位置 1，字符 1 要去位置 2。\n两个 2 按原有先后分别去位置 0、3，交换两个相同的 2 没有收益。\nrank 保存“每个字符最终要去哪个位置”，不是按字符大小排名。\n\n例如 pat=0122，映射后得到 rank=[1,2,0,3]。\n这里 1 在 0 前、2 在 0 前，都与最终 [0,1,2,3] 的顺序相反。\n这种“左边编号比右边大”的一对叫逆序对，本例有 2 对。\n一次相邻交换最多消掉一个逆序对；按冒泡排序逐个消掉，也确实能做到。\n因此逆序对数量 inv 就是内部重排的最少交换次数：\n    0122 -> 0212 -> 2012，正好 2 次。\n\n聚拢时交换“选中字符与没选中字符”，内部重排时交换“两个选中字符”。\n两类必要交换不互相抵扣；先聚拢再重排能达到两部分费用之和。\n所以固定选中位置和原始顺序后：\n    完整费用 = -p0-p1+p2+p3-4+inv。\n\n四、DP 怎样避免枚举所有四元组\n------------------------------------------------------------\nDP 是 Dynamic Programming（动态规划）。\n直接四层循环枚举 p0、p1、p2、p3 太慢。\n但固定 pat 后，inv 已经固定，-4 也固定，只需最小化：\n    -p0-p1+p2+p3。\n\n把“选择四个字符”拆成四个阶段。扫描过原串的某一段后：\n    dp[0]：没选字符，值为 0。\n    dp[1]：选好 pat 第 1 位，保存 -p0 的最小值。\n    dp[2]：选好 pat 前 2 位，保存 -p0-p1 的最小值。\n    dp[3]：选好 pat 前 3 位，保存 -p0-p1+p2 的最小值。\n    dp[4]：四位全选好，保存 -p0-p1+p2+p3 的最小值。\nINF 表示还没有合法选法；这些状态不是方案数量，也不是完整交换次数。\n例如 dp[2] 为负完全正常，不能因为“费用不能为负”就把它改成 0。\n\n扫描到原下标 i，如果当前字符等于 pat 的第 j 位，可以把它接到前 j-1 位后面：\n    选第 1、2 位：本次位置在公式中贡献 -i。\n    选第 3、4 位：本次位置在公式中贡献 +i。\n    新候选 = dp[j-1]+本次贡献。\n    dp[j] 取“原来的值”与“新候选”的较小者。\n保留原值表示不选当前字符，采用新候选表示选择当前字符。\n\n为什么不记录之前具体选了哪些位置？\n扫描从左到右，旧状态所选位置全在当前 i 左侧，先后顺序已由扫描保证。\n同一阶段的两个旧方案，接下来的候选都来自尚未扫描的后缀；\n谁当前的数值更小，接上同样的后续位置后谁仍更小，所以只留最小值就够了。\n\n五、把原串 0122、pat=0122 的 DP 完整算一遍\n------------------------------------------------------------\n此 pat 的 inv=2，INF 表示该阶段还做不到：\n\n    处理到哪里          dp[0] dp[1] dp[2] dp[3] dp[4]\n    还没扫描              0   INF   INF   INF   INF\n    下标 0 的 '0'         0     0   INF   INF   INF\n    下标 1 的 '1'         0     0    -1   INF   INF\n    下标 2 的第一个 '2'   0     0    -1     1   INF\n    下标 3 的第二个 '2'   0     0    -1     1     4\n\n各次有效转移：\n    dp[1]=dp[0]-0=0；\n    dp[2]=dp[1]-1=-1；\n    dp[3]=dp[2]+2=1；\n    dp[4]=dp[3]+3=4。\n最终答案为 dp[4]-4+inv=4-4+2=2。\n4 是下标表达式的结果；减去 4 后聚拢费为 0，再加 2 次内部交换。\n\n六、为什么 j 必须倒序更新\n------------------------------------------------------------\npat=0122 的最后两位都是 2，扫描到原串的第一个 2 时：\n如果先更新 dp[3]，再用刚更新的 dp[3] 更新 dp[4]，\n就把同一个原下标同时当作两个 2，错误地选了一次又选一次。\n本例甚至会算出 dp[4]=3，最后得到错误答案 1。\n\n倒序时先尝试 dp[4]，它只能读取上一轮的 dp[3]；\n之后才更新 dp[3]，因此同一个位置在同一条选择方案里最多用一次。\n\n【程序运行顺序】\nmain 先生成 12 种 pat，计算各自的 inv，存进 patterns，所有测试组复用。\n每组 solve：检查字符数量 -> 枚举 pat -> 扫描原串做四阶段 DP -> 取最小答案。\n缺少 0、1 或不足两个 2 时才无解，因为交换不能创造字符；\n数量满足时，总能通过重新排列得到 2012。\n\n每种 pat 扫描 n 位，每位只试 4 个阶段；12 是常数，总时间 O(n)。\n除输入字符串外，只需要固定大小的 DP 和排列记录，额外空间 O(1)。","editorialSource":"原文件中的 AI 参考注释 · 请结合题面与原稿复核","number":"D","hasIssues":true},{"id":"cqu2026-C","title":"丝柯克的加法","source":"2026 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2026","category":"字符串","tags":["数位模拟","大整数"],"level":"基础","summary":"把两数作为字符串从低位对齐，每位相加取模 10，再去除前导零。","caution":"至少保留一个 0，避免结果为空。","versions":[{"name":"AC 目录存档","language":"C++","status":"ac-directory","path":"2026重庆大学程序设计新生赛暨邀请赛/src/AC/C 丝柯克的加法-AC.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nvoid solve(){\r\n    ll a,b;\r\n    cin>>a>>b;\r\n    string ans=\"\";\r\n    while (a>0 or b>0){\r\n        ll tmp=(a%10+b%10)%10;\r\n        ans=to_string(tmp)+ans;\r\n        a/=10;\r\n        b/=10;\r\n    }\r\n    ll if0=true;\r\n    for (ll i=0;i<ans.size();i++){\r\n        if (ans[i]=='0' and if0) continue;\r\n        else{\r\n            if0=false;\r\n            cout<<ans[i];\r\n        }\r\n    }\r\n    if (if0) cout<<0;\r\n    cout<<'\\n';\r\n}\r\n\r\nint main(){\r\n    int T=1;\r\n    cin>>T;\r\n    while (T--) solve();\r\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/AI/C 丝柯克的加法-AI.cpp","code":"/*\n【思路】不进位加法中，每个十进制位互不影响，直接计算 (当前两位之和)%10。\n把输入当字符串，从右往左按个位、十位、百位依次对齐；短的数缺失高位按 0 处理。\n用 push_back 收集的顺序是低位到高位，所以最后要 reverse。\n\n【前导零】\n翻转前的末尾零，正好是正常数位顺序中的前导零，因此先从末尾删除。\n但至少留一位，避免 10 与 90 的结果全部为 0 时，输出成空串。\n\n【变量】i、j 是两个字符串当前尚未处理的下标；ans 暂存倒序结果。\n字符减 '0' 得到数位值，数位加 '0' 再转成 char 才能作为字符放回字符串。\n例如数位 9 与 8 相加得到 17，当前位只保留 7，不向左边额外加 1。\n每组输入独立调用 solve，时间与空间均 O(max(|a|,|b|))。\n*/\n#include <bits/stdc++.h>\nusing namespace std;\n\nvoid solve(){\n    string a,b;\n    cin>>a>>b;\n    string ans;\n    // 转成有符号 int 后减 1；后续能用 -1 表示“这个数已经没有剩余数位”。\n    int i=(int)a.size()-1,j=(int)b.size()-1;\n    // 从个位往高位处理，每位独立相加取模，不向下一位进位。\n    while (i>=0 || j>=0){\n        // 条件运算符只执行被选的一侧：下标为负时不会访问字符串，也不会继续 i--。\n        int x=(i>=0 ? a[i--]-'0' : 0);\n        int y=(j>=0 ? b[j--]-'0' : 0);\n        ans.push_back(char('0'+(x+y)%10));\n    }\n    // 当前 ans 是倒序数位；末尾多余的 0 对应正常结果的前导零。\n    while (ans.size()>1 && ans.back()=='0') ans.pop_back();\n    // begin 到 end 是整个字符串的半开范围，将倒序数位翻成正常输出顺序。\n    reverse(ans.begin(),ans.end());\n    cout<<ans<<'\\n';\n    // 不需要把整串转成整数，避免大整数溢出；时间和空间 O(最大位数)。\n}\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int T;\n    cin>>T;\n    while (T--) solve();\n}\n"}],"statement":"","links":[],"editorial":"【思路】不进位加法中，每个十进制位互不影响，直接计算 (当前两位之和)%10。\n把输入当字符串，从右往左按个位、十位、百位依次对齐；短的数缺失高位按 0 处理。\n用 push_back 收集的顺序是低位到高位，所以最后要 reverse。\n\n【前导零】\n翻转前的末尾零，正好是正常数位顺序中的前导零，因此先从末尾删除。\n但至少留一位，避免 10 与 90 的结果全部为 0 时，输出成空串。\n\n【变量】i、j 是两个字符串当前尚未处理的下标；ans 暂存倒序结果。\n字符减 '0' 得到数位值，数位加 '0' 再转成 char 才能作为字符放回字符串。\n例如数位 9 与 8 相加得到 17，当前位只保留 7，不向左边额外加 1。\n每组输入独立调用 solve，时间与空间均 O(max(|a|,|b|))。","editorialSource":"原文件中的 AI 参考注释 · 请结合题面与原稿复核","number":"C","hasIssues":false},{"id":"cqu2026-B","title":"Bubble Pop X","source":"2026 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2026","category":"动态规划","tags":["状态压缩","字符串","子序列计数"],"level":"挑战","summary":"用消除后交替串的首尾两位表示状态，按最后选中位置统计能消成一位的子序列。","caution":"首尾相同不代表仅剩一位；每轮转移必须读旧 dp。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/hyper/B Bubble Pop X-hyper.cpp","code":"#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\nconst ll INF=LLONG_MAX;\nconst ll mod=1e9+7;\n\nvoid solve() {\n    string s;\n    cin>>s;\n    vector<vector<ll>> dp(2,vector<ll>(2,0));\n    ll ans=0;\n    for (char ch : s){\n        ll c=ch-'0';\n        ans=(ans+1+dp[1][c]+dp[0][c])%mod;\n        auto ndp=dp;\n        for (ll i=0;i<=1;i++){\n            for (ll j=0;j<=1;j++){\n                if (c!=j) ndp[i][c]=(ndp[i][c]+dp[i][j])%mod;\n                else ndp[1-i][1-i]=(ndp[1-i][1-i]+dp[i][c])%mod;\n            }\n        }\n        ndp[c][c]=(ndp[c][c]+1)%mod;\n        swap(dp,ndp);\n    }\n    cout<<ans;\n}\n\nint main() {\n    int T=1;\n    // cin >> T;\n    while (T--) solve();\n    return 0;\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/AI/B Bubble Pop X-AI.cpp","code":"/*\n【目标】统计按“最左边相邻相同字符合并成相反字符”消除后，只剩一位的非空子序列。\n相同字符串若来自不同下标选择，仍是不同子序列；答案对 1e9+7 取模。\n\n【先理解单个字符串的消除】\n完全消除后，不再有相邻相同位，所以结果一定是交替串，例如 0101、101、0。\n按原顺序加入新字符 c，先把旧前缀消除完，与题目“每次优先消最左一对”一致。\n设旧交替串首为 a、尾为 b：\n1. b!=c：新字符直接接在末尾，旧首 a 不变，新尾为 c。\n2. b==c：末尾合并成 1-b，它与前一位又相同，沿交替串一直向左连锁。\n   直到只剩一位，最终是 1-a。例如 010 加 0：0100 -> 011 -> 00 -> 1。\n判断这两种转移只需首尾，不必记录整段交替串或它的长度。\n\n【DP（Dynamic Programming，动态规划）】\ndp[a][b]：已经扫描的前缀中，所选非空子序列消除后首为 a、尾为 b 的方案数。\n每个新位置有不选、接在旧子序列末尾、单独构成一条子序列三种来源。\nndp 是处理完当前字符后的新状态；dp 在本轮内保持不变，避免一个位置选多次。\n\n【为什么另设 ans，而不直接统计首尾相同】\n010 的首尾也是 0，但无法继续消除，不是美丽串。\n按“最后一个被选位置”计数：只选当前位贡献 1；旧尾与当前 c 相同时，\n追加当前位必连锁变成一位，贡献 dp[0][c]+dp[1][c]；其他来源不贡献。\n每个非空子序列只有一个最后位置，因此这样恰好统计一次。\n例：S=010，三个单字符和选择两个 0 得到的 00 美丽，答案为 4，整串 010 不计。\n\n【复杂度】每位仅处理 4 个状态，时间 O(|S|)，除输入串外空间 O(1)。\n*/\n#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\n// MOD：modulus，模数，避免方案数量指数增长而溢出。\nconst ll MOD=1000000007;\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    string s;\n    cin>>s;\n    // 消除后的结果必为交替串，只记它的首、尾字符。\n    // dp[a][b]：已扫描前缀中，所选非空子序列的消除结果首为 a、尾为 b 的数量。\n    // 两层 array 各长 2，即 2*2 的定长数组；{} 将四项全部初始化为 0。\n    array<array<ll,2>,2> dp{};\n    ll ans=0;\n    for (char ch : s){\n        // 字符 '0'/'1' 转成整数 0/1，作为状态下标。\n        int c=ch-'0';\n        // 按最后一个被选位置统计美丽子序列，必须使用更新前的 dp。\n        // 单选当前字符贡献 1；旧结果尾为 c 时，追加 c 会连锁消成一个字符。\n        ans=(ans+1+dp[0][c]+dp[1][c])%MOD;\n        // 完整复制旧状态：每一条旧子序列都可以跳过当前位置，原方案保留一次。\n        auto ndp=dp; // 不选择当前字符。\n        for (int a=0;a<2;a++){\n            for (int b=0;b<2;b++){\n                if (b!=c){\n                    // 尾部不同，不发生消除，首字符保持 a，尾字符变成 c。\n                    ndp[a][c]=(ndp[a][c]+dp[a][b])%MOD;\n                }else{\n                    // 尾部相同，会一路向左连锁消除，最终只剩 1-a。\n                    int v=1-a;\n                    ndp[v][v]=(ndp[v][v]+dp[a][b])%MOD;\n                }\n            }\n        }\n        ndp[c][c]=(ndp[c][c]+1)%MOD; // 只选当前字符，空子序列不计。\n        // 本轮所有转移结束，才把新状态替换成旧状态，进入下一位。\n        dp=ndp;\n    }\n    // 不能直接输出 dp[0][0]+dp[1][1]，因为 010 等长交替串也首尾相同。\n    cout<<ans<<'\\n';\n    // 时间 O(|s|)，除输入字符串外，额外空间 O(1)。\n}\n"}],"statement":"","links":[],"editorial":"【目标】统计按“最左边相邻相同字符合并成相反字符”消除后，只剩一位的非空子序列。\n相同字符串若来自不同下标选择，仍是不同子序列；答案对 1e9+7 取模。\n\n【先理解单个字符串的消除】\n完全消除后，不再有相邻相同位，所以结果一定是交替串，例如 0101、101、0。\n按原顺序加入新字符 c，先把旧前缀消除完，与题目“每次优先消最左一对”一致。\n设旧交替串首为 a、尾为 b：\n1. b!=c：新字符直接接在末尾，旧首 a 不变，新尾为 c。\n2. b==c：末尾合并成 1-b，它与前一位又相同，沿交替串一直向左连锁。\n   直到只剩一位，最终是 1-a。例如 010 加 0：0100 -> 011 -> 00 -> 1。\n判断这两种转移只需首尾，不必记录整段交替串或它的长度。\n\n【DP（Dynamic Programming，动态规划）】\ndp[a][b]：已经扫描的前缀中，所选非空子序列消除后首为 a、尾为 b 的方案数。\n每个新位置有不选、接在旧子序列末尾、单独构成一条子序列三种来源。\nndp 是处理完当前字符后的新状态；dp 在本轮内保持不变，避免一个位置选多次。\n\n【为什么另设 ans，而不直接统计首尾相同】\n010 的首尾也是 0，但无法继续消除，不是美丽串。\n按“最后一个被选位置”计数：只选当前位贡献 1；旧尾与当前 c 相同时，\n追加当前位必连锁变成一位，贡献 dp[0][c]+dp[1][c]；其他来源不贡献。\n每个非空子序列只有一个最后位置，因此这样恰好统计一次。\n例：S=010，三个单字符和选择两个 0 得到的 00 美丽，答案为 4，整串 010 不计。\n\n【复杂度】每位仅处理 4 个状态，时间 O(|S|)，除输入串外空间 O(1)。","editorialSource":"原文件中的 AI 参考注释 · 请结合题面与原稿复核","number":"B","hasIssues":false},{"id":"cqu2026-A","title":"你怎么舍得让我的泪流向海","source":"2026 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2026","category":"数据结构","tags":["map","set","懒偏移"],"level":"挑战","summary":"把位置转成固定坐标，维护按位置与按体积的两份索引，全体平移只改 offset。","caution":"每次增删改需同步两个容器；位置为 0 也入海。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/hyper/A 你怎么舍得让我的泪流向海-hyper.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\n\r\nvoid solve(){\r\n    ll q;\r\n    cin>>q;\r\n    ll offset=0,sea=0;\r\n    map<ll,ll> mp;\r\n    set<pair<ll,ll>> order;\r\n    while(q--){\r\n        string s;\r\n        cin>>s;\r\n        if (s==\"A\"){\r\n            ll x,v;\r\n            cin>>x>>v;\r\n            ll pos=x+offset;\r\n            auto it=mp.find(pos);\r\n            if (it==mp.end()){\r\n                mp[pos]=v;\r\n                order.insert({-v,pos});\r\n            }\r\n            else{\r\n                order.erase({-it->second,pos});\r\n                it->second+=v;\r\n                order.insert({-it->second,pos});\r\n            }\r\n        }\r\n        else if (s==\"W\"){\r\n            ll d;\r\n            cin>>d;\r\n            offset+=d;\r\n            while (!mp.empty() and mp.begin()->first<=offset){\r\n                auto it=mp.begin();\r\n                sea+=it->second;\r\n                order.erase({-it->second,it->first});\r\n                mp.erase(it);\r\n            }\r\n        }\r\n        else if (s==\"C\"){\r\n            if (order.empty()) continue;\r\n            auto it=order.begin();\r\n            ll pos=it->second;\r\n            mp.erase(pos);\r\n            order.erase(it);\r\n        }\r\n        else if (s==\"Q\") cout<<mp.size()<<\" \"<<sea<<'\\n';\r\n    }\r\n    cout<<mp.size()<<\" \"<<sea<<'\\n';\r\n    for (auto [pos,v] : mp){\r\n        cout<<pos-offset<<\" \"<<v<<'\\n';\r\n    }\r\n}\r\n\r\nint main(){\r\n    int T=1;\r\n    // cin>>T;\r\n    while (T--) solve();\r\n}\r\n"},{"name":"AI 参考","language":"C++","status":"reference","path":"2026重庆大学程序设计新生赛暨邀请赛/src/upsolve/AI/A 你怎么舍得让我的泪流向海-AI.cpp","code":"/*\n【题意】\nA：在实际位置 x 增加泪水，同位置合并；W：所有位置向左平移；\nC：接住体积最大的一团，同体积时取最小位置；Q：查询团数和累计入海体积。\n全部事件结束后，还要独立输出最终状态和剩余每一团的位置、体积。\n\n【为什么不能每次风吹都修改所有坐标】\n泪团最多有 q 个，每次逐个平移，最坏 O(q^2)。\n所有泪团受同样的风，因此可以用一个累计位移 offset 代替逐团修改。\n约定：固定坐标 pos = 实际位置 x + offset，实际位置 x = pos-offset。\n风吹 d 后，只需 offset+=d，每团的实际位置自然减少 d。\n新落下的泪水也必须存成 x+offset，不能直接把实际位置 x 当固定坐标。\n\n【两个容器，各负责一种排序】\nmp[pos]=v：按固定坐标升序排列，负责同位置合并、删除入海泪团和最终按位置输出。\norder 存 {-v,pos}：pair 先比第一项，再比第二项，所以首项恰好是要接住的团。\n体积越大，负体积越小；同体积时固定坐标越小，实际位置也越小。\n不变式：两个容器始终记录完全相同的一批岸上泪团，任何增删改都必须同步。\n\n【计数和边界】\nsea 只在泪团入海时增加；被纸巾接住不算入海。mp.size() 就是当前团数。\n位置恰为 0 也入海，因此判断 pos<=offset；空场 C 不做任何事。\n例：offset=3 时在实际位置 5 新落泪，存 pos=8；再吹 2 后实际位置为 8-5=3。\n\n【复杂度】\n单次 W 可能删除很多团，但每个新建的活动团最多消失一次。\n所有删除合计 O(q)，每次容器操作 O(log q)，总时间 O(q log q)，空间 O(q)。\n坐标累计位移、合并体积和入海总量都可能超过 int，使用 long long。\n*/\n#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int q;\n    cin>>q;\n    // offset：累计向海移动的距离；sea：从开始至今已流入海中的总体积。\n    ll offset=0,sea=0;\n    // 固定坐标 = 实际位置 + offset，风吹时只增加 offset。\n    map<ll,ll> mp;\n    // 按 {-体积,固定坐标} 排序：体积最大优先，同体积时最靠海优先。\n    set<pair<ll,ll>> order;\n\n    while (q--){\n        char op;\n        cin>>op;\n        if (op=='A'){\n            ll x,v;\n            cin>>x>>v;\n            // 输入 x 是此刻相对于海岸的位置，转换成不会随风变化的固定坐标。\n            ll pos=x+offset;\n            auto it=mp.find(pos);\n            // find 不会创建元素；end() 表示原来这里没有泪团。\n            if (it==mp.end()){\n                // 新建一团，在位置表和体积排序表中各插入一条记录。\n                mp[pos]=v;\n                order.insert({-v,pos});\n            }else{\n                // 体积改变时，先删除旧的排序项，再插入新的排序项。\n                // 若只改 mp 而不改 order，后续 C 就会按旧体积挑错泪团。\n                order.erase({-it->second,pos});\n                it->second+=v;\n                order.insert({-it->second,pos});\n            }\n        }else if (op=='W'){\n            ll d;\n            cin>>d;\n            offset+=d;\n            // 实际位置 <=0 等价于固定坐标 <=offset。\n            while (!mp.empty() && mp.begin()->first<=offset){\n                // mp.begin() 是当前最靠海的一团。它仍在岸上，则后面的团也都在岸上。\n                // && 从左往右短路求值，先保证非空，才能读取 begin()->first。\n                auto it=mp.begin();\n                sea+=it->second;\n                order.erase({-it->second,it->first});\n                // 删除后 it 失效，不再使用它；下一轮重新取 mp.begin()。\n                mp.erase(it);\n            }\n        }else if (op=='C'){\n            if (order.empty()) continue;\n            // order 的首元素是 {-最大体积,同体积中的最小固定坐标}。\n            auto it=order.begin();\n            ll pos=it->second;\n            mp.erase(pos);\n            order.erase(it);\n            // 被纸巾接住不算入海，不修改 sea。\n        }else if (op=='Q'){\n            cout<<mp.size()<<\" \"<<sea<<'\\n';\n        }\n    }\n\n    // 最终状态必须独立输出，不能因为最后有 Q 就省略。\n    cout<<mp.size()<<\" \"<<sea<<'\\n';\n    // 所有固定坐标减去同一个 offset，原排序不变，直接升序遍历即可。\n    for (auto [pos,v] : mp){\n        cout<<pos-offset<<\" \"<<v<<'\\n';\n    }\n    // 每团最多创建、消失一次；所有事件合计 O(q log q)，空间 O(q)。\n}\n"},{"name":"ERROR 目录原稿","language":"C++","status":"error","path":"2026重庆大学程序设计新生赛暨邀请赛/src/ERROR/A 你怎么舍得让我的泪流向海.cpp","code":"/*\r\nRE\n多种错误\n\n错误记录（只补注释，未修改代码）：\n1. W 中遍历 map 时删除当前元素，循环迭代器失效；删除后继续使用引用 x 也不安全。\n2. 题目要求累计入海体积，但 sum 在 A 时增加、W 时减少，统计含义错误。\n3. C 删除一团后没有减少 count，查询数量错误。\n4. 全部事件结束后，缺少最终 m、s 和剩余泪团的位置、体积输出。\n5. A、W、C 都可能扫描所有泪团，总体最坏 O(q^2)，无法处理 q=2e5。\n反例：q=2，依次 A 1 5、Q；查询应为 1 0，随后最终状态为 1 0、1 5。\n反例：q=3，依次 A 1 5、C、Q；查询和最终状态都应为 0 0。\nRE 反例：q=2，依次 A 1 5、W 1，触发删除当前遍历元素。\n优化方向：累计风偏移 offset，map 存固定坐标 x+offset，实际位置为 key-offset；\n用 set<pair<ll,ll>> 存 {-体积,固定坐标} 取最大体积、最小位置，两容器同步维护。\n\r\n可直接运行的反例（输入/输出每项独占一行）：\r\n输入：\r\n2\r\nA 1 5\r\nQ\r\n期望输出：\r\n1 0\r\n1 0\r\n1 5\r\n当前输出只有 1 5：查询把岸上体积当成入海体积，同时遗漏最终状态。\r\n\r\n输入：\r\n3\r\nA 1 5\r\nC\r\nQ\r\n期望输出：\r\n0 0\r\n0 0\r\n当前输出只有 1 5：接住后 count 没减少，且 sum 仍保留这团的体积。\r\n\r\n补充说明：\r\n- 范围 for 的结构化绑定是引用，不是拷贝。erase 当前元素后，迭代器及 x、v 都失效。\r\n  入海分支会在循环自增时使用失效迭代器；平移分支还会立即读取悬空引用 x。\r\n- 即使把 sum 理解成岸上总量，C 时也缺少扣减；应将累计入海量单独维护。\r\n- 相同体积时取最小位置这一点目前是对的：map 升序遍历，且只在 v>max_v 时替换。\r\n- 每次 A 至多新建一团；用整体偏移后，每团至多被删除一次，删除过程可均摊分析。\r\n*/\n#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\n\r\nvoid solve(){\r\n    ll q;\r\n    cin>>q;\r\n    ll sum=0;\r\n    ll count=0;\r\n    map<ll,ll> mp;\r\n    while(q--){\r\n        string s;\r\n        cin>>s;\r\n        if (s==\"A\"){\r\n            ll x,v;\r\n            cin>>x>>v;\r\n            bool found=false;\n            // 性能：map 可直接按键查找，不必逐个扫描，当前查找为 O(泪团数)。\n            for (auto& [key,val]:mp){\n                if (key==x){\n                    // 统计错误：新落下的体积尚未入海，累计入海量不应在这里增加。\n                    sum+=v;\n                    val+=v;\r\n                    found=true;\r\n                    break;\r\n                }\r\n            }\r\n            if (!found){\n                count++;\n                // 同上：sum 若用于输出累计入海量，不能在 A 时增加。\n                sum+=v;\n                mp[x]=v;\r\n            }\r\n        }\r\n        else if (s==\"W\"){\r\n            ll d;\n            cin>>d;\n            // RE：下面删除当前元素会使范围 for 的迭代器失效。\n            // 同时不必逐团修改坐标，可通过累计风偏移统一表示位置变化。\n            for (auto& [x,v]:mp){\n                if (x-d<=0){\n                    // 统计错误：这团流入海中，累计入海量应增加 v，而不是减少。\n                    sum-=v;\n                    count--;\r\n                    // erase 不会替范围 for 更新迭代器，下一次循环自增仍会访问已删除元素。\r\n                    mp.erase(x);\r\n                }\r\n                else{\r\n                    ll tmp_v=v;\n                    mp.erase(x);\n                    // RE：x 是被删除 map 元素的引用，erase 后不能继续读取 x。\n                    mp[x-d]=tmp_v;\n                }\r\n            }\r\n        }\r\n        else if (s==\"C\"){\r\n            if (mp.empty()) continue;\r\n            ll max_v=0;\r\n            ll tmp_x=-1;\r\n            // 性能：这里为 O(团数)；正确的平局规则已由 map 升序和严格 > 保证。\r\n            for (auto& [x,v]:mp){\r\n                if (v>max_v){\r\n                    max_v=v;\r\n                    tmp_x=x;\r\n                }\r\n            }\n            mp.erase(tmp_x);\n            // 数量错误：已删除一团，但没有 count--；也可直接用 mp.size() 查询团数。\n        }\r\n        else if (s==\"Q\"){\r\n            // Q 的第二项应为累计入海量，不是当前岸上总量或累计新增量。\r\n            // 此处同时受到 A/W 中 sum 含义错误和 C 中 count 未更新的影响。\r\n            cout<<count<<\" \"<<sum<<'\\n';\n        }\n    }\n    // 输出遗漏：这里还必须输出最终团数、累计入海量，并按位置升序输出剩余泪团。\n    // 即使最后一个事件是 Q，也不能省略这份最终状态。\n}\n\r\nint main(){\r\n    int T=1;\r\n    // cin>>T;\r\n    while (T--) solve();\r\n}\n"}],"statement":"","links":[],"editorial":"【题意】\nA：在实际位置 x 增加泪水，同位置合并；W：所有位置向左平移；\nC：接住体积最大的一团，同体积时取最小位置；Q：查询团数和累计入海体积。\n全部事件结束后，还要独立输出最终状态和剩余每一团的位置、体积。\n\n【为什么不能每次风吹都修改所有坐标】\n泪团最多有 q 个，每次逐个平移，最坏 O(q^2)。\n所有泪团受同样的风，因此可以用一个累计位移 offset 代替逐团修改。\n约定：固定坐标 pos = 实际位置 x + offset，实际位置 x = pos-offset。\n风吹 d 后，只需 offset+=d，每团的实际位置自然减少 d。\n新落下的泪水也必须存成 x+offset，不能直接把实际位置 x 当固定坐标。\n\n【两个容器，各负责一种排序】\nmp[pos]=v：按固定坐标升序排列，负责同位置合并、删除入海泪团和最终按位置输出。\norder 存 {-v,pos}：pair 先比第一项，再比第二项，所以首项恰好是要接住的团。\n体积越大，负体积越小；同体积时固定坐标越小，实际位置也越小。\n不变式：两个容器始终记录完全相同的一批岸上泪团，任何增删改都必须同步。\n\n【计数和边界】\nsea 只在泪团入海时增加；被纸巾接住不算入海。mp.size() 就是当前团数。\n位置恰为 0 也入海，因此判断 pos<=offset；空场 C 不做任何事。\n例：offset=3 时在实际位置 5 新落泪，存 pos=8；再吹 2 后实际位置为 8-5=3。\n\n【复杂度】\n单次 W 可能删除很多团，但每个新建的活动团最多消失一次。\n所有删除合计 O(q)，每次容器操作 O(log q)，总时间 O(q log q)，空间 O(q)。\n坐标累计位移、合并体积和入海总量都可能超过 int，使用 long long。","editorialSource":"原文件中的 AI 参考注释 · 请结合题面与原稿复核","number":"A","hasIssues":true},{"id":"nowcoder-r9-H","title":"Set","source":"2026 牛客多校 · 第 9 场","platform":"牛客","date":"","group":"nowcoder","category":"数学与数论","tags":["奇偶性","set","去重"],"level":"进阶","summary":"用总奇数个数与候选值奇偶性判断，分别统计已出现及未出现的偶数和奇数。","caution":"集合去重后的数量与原数组奇数数量承担不同含义。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"牛客多校/9/H-Set.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nint main() {\r\n    ll n;\r\n    cin >> n;\r\n    \r\n    vector<ll> arr(n);\r\n    ll odd_count = 0;\r\n    ll max_a = 0;\r\n    \r\n    for (ll i = 0; i < n; i++) {\r\n        cin >> arr[i];\r\n        if (arr[i] % 2 == 1) odd_count++;\r\n        max_a = max(arr[i], max_a);\r\n    }\r\n    \r\n    set<ll> s(arr.begin(), arr.end());\r\n    ll res = 0;\r\n    ll exist_even = 0;\r\n\r\n    for (ll x : s) {\r\n        if ((odd_count - (x % 2 == 1)) % 2 == 0) {res++;}\r\n        if (x % 2 == 0) exist_even++;\r\n    }\r\n\r\n    ll exist_odd = s.size() - exist_even;\r\n    ll not_exist_even = (max_a / 2) - exist_even;\r\n    ll not_exist_odd = (max_a - max_a / 2) - exist_odd;\r\n    \r\n    if (odd_count % 2 == 0) res += not_exist_even;\r\n    if (odd_count % 2 == 1) res += not_exist_odd;\r\n    \r\n    cout << res << endl;\r\n    return 0;\r\n}"}],"statement":"","links":[],"number":"H","hasIssues":false},{"id":"nowcoder-r9-B","title":"Bingo Game","source":"2026 牛客多校 · 第 9 场","platform":"牛客","date":"","group":"nowcoder","category":"模拟与实现","tags":["行列计数","最小值"],"level":"基础","summary":"行、列计数初始化为 n，每次读入标记坐标后同时减去相应行列的剩余量，最后取最小值。","caution":"若输入可能重复标记同一格，需要去重；是否允许重复应依据原题保证。","versions":[{"name":"hyper 原稿","language":"Python","status":"original","path":"牛客多校/9/B-Bingo Game.py","code":"n,m=map(int,input().split())\r\nrow=[n]*n\r\ncol=[n]*n\r\nfor i in range(m):\r\n    x,y=map(int,input().split())\r\n    row[x-1]-=1\r\n    col[y-1]-=1\r\n\r\nres=n\r\nfor i in range(n):\r\n    res=min(row[i],col[i],res) \r\n\r\nprint(res,end=\"\")"}],"statement":"","links":[],"number":"B","hasIssues":false},{"id":"nowcoder-r8-I","title":"Bridge VI","source":"2026 牛客多校 · 第 8 场","platform":"牛客","date":"","group":"nowcoder","category":"贪心与双指针","tags":["极值","分类讨论"],"level":"进阶","summary":"按每一对数的大小与预算分别统计可能赢下的最少、最多数量。","caution":"严格大于与大于等于不可混淆；每对的分支必须互斥。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"牛客多校/8/I-Bridge VI.cpp","code":"#include <bits/stdc++.h>\r\n#include <algorithm>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nint main(){\r\n    int t;\r\n    cin>>t;\r\n    \r\n    while (t--){\r\n        int n,m;\r\n        cin>>n>>m;\r\n        \r\n        vector<ll> arr(2*n);\r\n        \r\n        for (auto& x : arr) cin>>x;\r\n        \r\n        ll sum_min=0;\r\n        ll sum_max=0;\r\n        ll a1=arr[0];\r\n        \r\n        sum_min+=(arr[0]+m<arr[1]);\r\n        sum_max+=(arr[0]<arr[1]+m);\r\n        \r\n        for (int i=1;i<n;i++){\r\n            ll min_a=min(arr[2*i],arr[2*i+1]);\r\n            ll max_a=max(arr[2*i],arr[2*i+1]);\r\n            \r\n            if (min_a>a1+m) {sum_min+=2;}\r\n            else if ((min_a+max_a+m)>2*(a1+m)) {sum_min+=1;}\r\n            else if (max_a>a1+m) {sum_min+=1;}\r\n            \r\n            if (min_a+m>a1 and (min_a+max_a+m)>2*a1) {sum_max+=2;}\r\n            else if (max_a+m>a1) {sum_max+=1;}\r\n        }\r\n        \r\n        cout<<sum_min<<\" \"<<sum_max<<endl;\r\n    }\r\n}"}],"statement":"","links":[],"number":"I","hasIssues":false},{"id":"nowcoder-r7-L","title":"Bobo的幸运取模","source":"2026 牛客多校 · 第 7 场","platform":"牛客","date":"","group":"nowcoder","category":"数学与数论","tags":["取模","分块计数","枚举"],"level":"进阶","summary":"枚举 b，将满足条件的 a 写成若干连续区间，累加区间长度。","caution":"当前还有内层区间枚举，需要分析最坏复杂度。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"牛客多校/7/L-Bobo的幸运取模.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    \r\n    ll n;\r\n    cin>>n;\r\n    \r\n    ll ans=0;\r\n    ll maxb=sqrt(n);\r\n    \r\n    for (ll b=1; b<=maxb;b++) {\r\n        ll base = b * (b + 1);\r\n        ll max_t = (n + b) / base;\r\n        for (ll i=1;i<max_t;i++){\r\n            ll a_min=i*(b+1)*b-b;\r\n            ll a_max=i*(b+1)*b-1;\r\n            ans+=a_max-a_min+1;\r\n        }\r\n        \r\n        ll a_min=max_t*(b+1)*b-b;\r\n        ll a_max=max_t*(b+1)*b-1;\r\n        if (a_max>n) a_max=n;\r\n        if (a_min<=a_max) {\r\n            ans+=a_max-a_min+1;\r\n        }\r\n    }\r\n    cout<<ans<<'\\n';\r\n    return 0;\r\n}"}],"statement":"","links":[],"number":"L","hasIssues":false},{"id":"nowcoder-r7-K","title":"D-Mail","source":"2026 牛客多校 · 第 7 场","platform":"牛客","date":"","group":"nowcoder","category":"字符串","tags":["缩写","map","冲突消解"],"level":"进阶","summary":"先取单词首字母作为缩写，将冲突组逐轮展开更多完整单词。","caution":"若所有单词已展开仍有相同姓名，原循环可能不终止；需核对题目保证。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"牛客多校/7/K-D-Mail.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    \r\n    int n;\r\n    cin>>n;\r\n    cin.ignore();\r\n    \r\n    vector<vector<string>> names(n);\r\n    vector<int> wordCnt(n);\r\n    \r\n    for (int i=0;i<n;i++) {\r\n        string line;\r\n        getline(cin,line);\r\n        stringstream ss(line);\r\n        string word;\r\n        while (ss>>word) {\r\n            names[i].push_back(word);    \r\n        }\r\n        wordCnt[i]=names[i].size();\r\n    }\r\n    \r\n    vector<string> abbr(n);\r\n    vector<int> cnt(n,1);\r\n    for (int i=0;i<n;i++){\r\n        string s=\"\";\r\n        for (auto& p : names[i]){\r\n            s+=p[0];\r\n        }\r\n        abbr[i]=s;\r\n    }\r\n    \r\n    bool ifctn=true;\r\n    while (ifctn) {\r\n        map<string,vector<int>> groups;\r\n        for (int i=0;i<n;i++){\r\n            groups[abbr[i]].push_back(i);\r\n        }\r\n        ifctn=false;\r\n        for (auto& p:groups){\r\n            if (p.second.size()>1){\r\n                ifctn=true;\r\n                for (auto& q:p.second){\r\n                    string s=\"\";\r\n                    for (int i=0;i<names[q].size();i++){\r\n                        if (i<cnt[q]) s+=names[q][i];\r\n                        else s+=names[q][i][0];\r\n                    }\r\n                    abbr[q]=s;\r\n                    cnt[q]++;\r\n                }\r\n            }\r\n        }\r\n    }\r\n    \r\n    for (int i=0;i<n;i++){\r\n        cout<<abbr[i]<<endl;\r\n    }\r\n}"}],"statement":"","links":[],"number":"K","hasIssues":false},{"id":"nowcoder-r7-G","title":"瞬、心心相印","source":"2026 牛客多校 · 第 7 场","platform":"牛客","date":"","group":"nowcoder","category":"待补全","tags":["空文件"],"level":"待补全","summary":"目录保留了题名，但源码文件为空，作为后续补题占位。","caution":"当前没有足够代码依据进行算法分类。","versions":[{"name":"空文件 · 待补全","language":"C++","status":"empty","path":"牛客多校/7/G-瞬、心心相印.cpp","code":""}],"statement":"","links":[],"number":"G","hasIssues":true},{"id":"nowcoder-r4-I","title":"Rounddog II","source":"2026 牛客多校 · 第 4 场","platform":"牛客","date":"","group":"nowcoder","category":"字符串","tags":["循环字符串","匹配"],"level":"进阶","summary":"将 S 拼接成 S+S，搜索 Rounddo 加 k 个 g 的模式串，统计环上出现。","caution":"复制串中的匹配并非全部对应不同环上起点；核对范围与重复计数。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"牛客多校/4/I-Rounddog II.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(0);\r\n    \r\n    int t;\r\n    cin>>t;\r\n\r\n    while (t--){\r\n\r\n        string S;\r\n        int k;\r\n        cin>>S>>k;\r\n        int n = S.size();\r\n\r\n        string target = \"Rounddo\" + string(k, 'g');\r\n        int targetLen=target.size();\r\n        \r\n        string SS=S+S;\r\n        int len=SS.size();\r\n        \r\n        int ans = 0;\r\n        int start = 0;\r\n        int cnt=0;\r\n        while (1) {\r\n            int pos = SS.find(target, start);\r\n            if (pos == -1 or pos >= 2*n) break;\r\n            cnt++;\r\n            if (cnt>=3) {\r\n                ans=n;\r\n                break;\r\n            }\r\n            else ans=n-targetLen+1;\r\n            start = pos + 1;\r\n        }\r\n        \r\n        cout<<ans<<'\\n';\r\n    }\r\n    \r\n    return 0;\r\n}"}],"statement":"","links":[],"number":"I","hasIssues":false},{"id":"nowcoder-r3-K","title":"Turn-by-Turn Navigation","source":"2026 牛客多校 · 第 3 场","platform":"牛客","date":"","group":"nowcoder","category":"计算几何","tags":["叉积","方向判断"],"level":"基础","summary":"对连续三点的两段向量取叉积，符号对应左转、右转或直行。","caution":"乘法可能超过 int，使用 long long；共线时输出 STRAIGHT。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"牛客多校/3/K-Turn-by-Turn Navigation.cpp","code":"#include <iostream>\r\n#include <vector>\r\nusing namespace std;\r\n\r\nstruct point {\r\n    long long x;\r\n    long long y;\r\n};\r\n\r\nint main() {\r\n    int T;\r\n    cin >> T;\r\n    \r\n    for (int i = 0; i < T; i++) {\r\n        int n;\r\n        cin >> n;\r\n        vector<point> points(n);\r\n        \r\n        for (int j = 0; j < n; j++) {\r\n            cin >> points[j].x >> points[j].y;\r\n        }\r\n        \r\n        for (int j = 1; j < n - 1; j++) {\r\n            long long ax = points[j].x - points[j-1].x;\r\n            long long ay = points[j].y - points[j-1].y;\r\n            \r\n            long long bx = points[j+1].x - points[j].x;\r\n            long long by = points[j+1].y - points[j].y;\r\n            \r\n            long long cross = ax * by - ay * bx;\r\n            \r\n            if (cross > 0) {\r\n                cout << \"LEFT\";\r\n            } \r\n            else if (cross < 0) {\r\n                cout << \"RIGHT\";\r\n            } \r\n            else {\r\n                cout << \"STRAIGHT\";\r\n            }\r\n            if (j < n - 2) cout << \" \";\r\n        }\r\n        cout<<endl;\r\n    }\r\n    return 0;\r\n}"}],"statement":"","links":[],"number":"K","hasIssues":false},{"id":"nowcoder-r1-B","title":"Cast off as Cast","source":"2026 牛客多校 · 第 1 场","platform":"牛客","date":"","group":"nowcoder","category":"计算几何","tags":["建图","Dijkstra","圆弧"],"level":"挑战","summary":"把端点作为节点，以圆弧长度和同角径向距离建立带权图，运行 Dijkstra。","caution":"角度存在循环区间；double 精度和不可达情况需核对。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"牛客多校/1/B Cast off as Cast.cpp","code":"#include <iostream>\r\n#include <vector>\r\n#include <cmath>\r\n#include <iomanip>\r\n#include <queue>\r\nusing namespace std;\r\n\r\nconst double PI=acos(-1.0); \r\nconst double k=PI*2/100000;\r\nconst double INF = 1e18;\r\n\r\nstruct arc{ \r\n    int r;\r\n    int d1;\r\n    int d2;\r\n};\r\n\r\nstruct point{\r\n    int r;\r\n    int d;\r\n};\r\n\r\ndouble get_d(int d1, int d2) {\r\n    if (d2 >= d1) return d2 - d1;\r\n    return 100000 - d1 + d2;    \r\n}\r\n\r\nint main(){\r\n    int n;\r\n    vector<point> points(2);\r\n    cin>>n>>points[0].r>>points[0].d>>points[1].r>>points[1].d;\r\n    vector<arc> arcs;\r\n    for (int i=0;i<n;i++){\r\n        int r,d1,d2;\r\n        cin>>r>>d1>>d2;\r\n        arcs.push_back({r,d1,d2});  \r\n        points.push_back({r,d1});\r\n        points.push_back({r,d2});\r\n    }\r\n    int V=points.size();\r\n    vector<vector<pair<int, double>>> adj(V);\r\n\r\n    for (int i=2;i<V;i+=2){\r\n        int j=i+1;\r\n        auto p=arcs[(i-2)/2];\r\n        double cost = k*p.r*get_d(p.d1,p.d2);\r\n        adj[i].push_back({j,cost});\r\n        adj[j].push_back({i,cost});\r\n        \r\n    }\r\n\r\n    for (int i = 0; i < V; i++) {\r\n        for (int j = i + 1; j < V; j++) {\r\n            if (points[i].d == points[j].d and points[i].r > 0 and points[j].r > 0) {\r\n                double cost = abs(points[i].r - points[j].r);\r\n                adj[i].push_back({j, cost});\r\n                adj[j].push_back({i, cost});\r\n            }\r\n        }\r\n    }\r\n\r\n    vector<double> dist(V, INF);\r\n    priority_queue<pair<double, int>, vector<pair<double, int>>, greater<pair<double, int>>> q;\r\n    dist[0] = 0;\r\n    q.push({0, 0});\r\n\r\n    while (!q.empty()) {\r\n        auto p=q.top();\r\n        q.pop();\r\n        double d = p.first;\r\n        int u = p.second;\r\n\r\n        if (d > dist[u]) continue;\r\n        if (u == 1) break;\r\n\r\n        for (int i = 0; i < adj[u].size(); i++){\r\n            int v = adj[u][i].first;\r\n            double w = adj[u][i].second;\r\n            if (dist[u] + w < dist[v]) {\r\n                dist[v] = dist[u] + w;\r\n                q.push({dist[v], v});\r\n            }\r\n        }\r\n    }\r\n\r\n    if (dist[1]==INF){\r\n        cout<<\"Cast off as cast!\";\r\n    }\r\n    else{\r\n        cout<<fixed<<setprecision(10)<<dist[1];\r\n    }\r\n}\r\n"}],"statement":"","links":[],"number":"B","hasIssues":false},{"id":"icpc2026-r2-L","title":"Problem L","source":"2026 ICPC 网络赛 · 第二场","platform":"QOJ","date":"","group":"icpc","category":"数学与数论","tags":["路径转化","一维游走","贪心"],"level":"挑战","summary":"用 d=i−j 将循环移位网格路径变成一维往返，枚举最低代价边重复经过的最优结构。","caution":"d 本身不取模，只有读权值时取模；起点权值只单独计一次。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"2026ICPC网络赛/2/upsolve/L-hyper.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst int N = 1e5+10;\r\n\r\n\r\n\r\nvoid solve(){\r\n    ll n;\r\n    cin >> n;\r\n    vector<ll> a(n);\r\n    for (int i = 0; i < n; i++) cin >> a[i];\r\n    if (n == 1) {\r\n        cout << a[0] << \"\\n\";\r\n        return;\r\n    }\r\n    ll ans=LLONG_MAX;\r\n    for (int dir : {1,-1}){\r\n        ll sum=0;\r\n        ll last=0;\r\n        for (ll i=1;i<n;i++){\r\n            ll now=(dir*i+n)%n;\r\n            ll cost=a[now]+a[last];\r\n            sum+=cost;\r\n            ll tmp=a[0]+sum+(n-1-i)*cost;\r\n            ans=min(ans,tmp);\r\n            last=now;\r\n        }\r\n    }\r\n    cout << ans << \"\\n\";\r\n}\r\n\r\nint main(){\r\n    int t;\r\n    cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"2026ICPC网络赛/2/upsolve/L-AI.cpp","code":"#include <bits/stdc++.h>\nusing namespace std;\n// 路径有 2*n-1 个格子，每个权值最多 10^9，必须使用 long long。\nusing ll = long long;\n\n/*\n思路：把二维网格上的路径转换成一维下标差的移动。\n\n1. 设当前格子为 (i,j)，令 d=i-j。\n   第 j 列是第 0 列向下循环移动 j 次，所以格子权值为：\n       arr[(d+n)%n]\n   向下走：i 加一，d 加一。\n   向右走：j 加一，d 减一。\n   起点 (0,0) 和终点 (n-1,n-1) 的 d 都是 0。\n   因而路径等价于：从 d=0 出发，加一、减一各 n-1 次，最后返回 0。\n   d 是整数线上的位置，不取模；只有读取数组权值时才取模。\n\n2. 把整数线上相邻的两个位置看成一条边。\n   因为最终返回 0，每条走过的边向两个方向经过的次数相同。\n   每经过这条边并返回一次，就计入两端的权值之和 cost。\n   注意这只是费用统计，不要求路径实际连续完成这次往返。\n   总步数为 2*(n-1)，所以共有 n-1 次这样的往返。\n\n3. 为什么只需枚举一条边来反复往返？\n   对任意合法路径，选择它经过的、cost 最小的一条边。\n   假设这条边离 0 的远端距离为 t：\n   要经过它，就必须走过从 0 到它之间的 t 条边，并最终回来。\n   这部分是必要费用。其余 n-1-t 次往返，每次费用都至少是 cost。\n   可以直接去这条边上反复往返，最后回到 0，达到这个费用下界。\n   所以至少有一条最优路径符合这种形式，枚举所有候选边即可。\n\n4. 构造的路径是否合法？\n   去到距离 t 的位置再回来，加一、减一各用了 t 次。\n   剩余 n-1-t 次往返，加一、减一各再用 n-1-t 次。\n   总计两种移动各 n-1 次，正好到达网格右下角，也不会越界。\n\n时间复杂度 O(n)：正、负方向各扫描一次。\n空间复杂度 O(n)：存储输入数组，不创建 n*n 的网格。\n*/\nint main(){\n    // 关闭 C 和 C++ 输入输出同步，加快 cin、cout。\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int T;\n    cin>>T;\n    while (T--){\n        int n;\n        cin>>n;\n        vector<ll> arr(n); // 使用下标 0 到 n-1，与题面一致。\n        for (int i=0;i<n;i++){\n            cin>>arr[i];\n        }\n\n        // 只有一个格子，不需要移动，但起点的权值仍要计入。\n        if (n==1){\n            cout<<arr[0]<<'\\n';\n            continue;\n        }\n\n        ll ans=LLONG_MAX; // 先设为 long long 的最大值，再不断取最小值。\n        // dir=1：d 为 0,1,2,...，对应先向下走。\n        // dir=-1：d 为 0,-1,-2,...，对应先向右走。\n        // 两个方向都要枚举，因为两侧遇到的权值顺序不同。\n        for (int dir : {1,-1}){\n            ll sum=0; // 从 0 到当前候选边之间，每条边往返一次的费用之和。\n            int last=0; // 上一个位置对应的数组下标，最初为 arr[0]。\n            // 距离最多为 n-1；再远就需要超过允许的移动次数。\n            for (int t=1;t<n;t++){\n                // 当前整数位置 d=dir*t，转换为数组下标。\n                // 加 n 是为了避免负数取模得到负下标。\n                // 正方向下标：1,2,...,n-1；负方向：n-1,n-2,...,1。\n                int now=(dir*t+n)%n;\n                // 在 last 与 now 对应的两个位置之间往返两步：\n                // 一步到达 now，一步到达 last，所以费用为两端权值之和。\n                ll cost=arr[last]+arr[now];\n                // 加上新边的费用后，sum 包含从 0 到距离 t 的所有边。\n                // 每条边往返一次，共 2*t 步；这里不包含出发时的起点费用。\n                sum+=cost;\n                // arr[0]：出发时访问起点的费用，只单独加一次。\n                // sum：走到当前边再回到 0 的必要费用，已含返回时的 arr[0]。\n                // (n-1-t)*cost：剩余往返全部放在当前边上。\n                // 这里只枚举“把剩余次数放在当前边”的方案，\n                // 当前边不一定最便宜，但所有边都会枚举到，最后取最小值。\n                ll tmp=arr[0]+sum+(n-1-t)*cost;\n                ans=min(ans,tmp);\n                last=now; // 下一轮枚举更远的一条边。\n            }\n        }\n        cout<<ans<<'\\n';\n    }\n}\n"},{"name":"未完成稿","language":"C++","status":"incomplete","path":"2026ICPC网络赛/2/L.cpp","code":"#include<iostream>\r\n#define int long long \r\nusing namespace std;\r\nconst int N = 1e5+10;\r\nint a[N];\r\nint dp[N];\r\nsigned main()\r\n{\r\n    int t;\r\n    cin >> t;\r\n    while(t--)\r\n    {\r\n        int n;\r\n        cin >> n;\r\n        for(int i=1;i<=n;i++)\r\n        cin >> a[i];\r\n        dp[1] = a[1];\r\n        for(int i=2;i<=n-1;i++)\r\n        {\r\n           dp[i] = dp[i-1] + max(a[i], a[i+1]);\r\n        }\r\n    }\r\n}"}],"statement":"","links":[{"label":"题档中的 QOJ 链接","url":"https://qoj.ac/contest/4113"}],"number":"L","hasIssues":true},{"id":"icpc2026-r2-K","title":"Problem K","source":"2026 ICPC 网络赛 · 第二场","platform":"QOJ","date":"","group":"icpc","category":"数据结构","tags":["mex","频次","配对","记忆化"],"level":"挑战","summary":"按 {t,k−t} 成对分配频次，把每一对对 mex 的约束合并，并缓存重复 k 的结果。","caution":"AI 参考对小 k 的不同询问逐一枚举，最坏复杂度仍需依据数据范围评估。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"2026ICPC网络赛/2/K.cpp","code":"#include <bits/stdc++.h>\r\n#define ll long long \r\nusing namespace std;\r\n\r\n/*\r\n * 当前文件保留的是旧版做法：每次询问都重新扫描一遍数组。\r\n *\r\n * sets 中保存当前能够构造出的一些值。\r\n * 对于每个 a[i]：\r\n * - 如果 a[i] > k，那么 k-a[i] < 0，负值对非负 mex 没有帮助，\r\n *   所以只尝试保留 a[i]；\r\n * - 否则两个选择是 a[i] 和 k-a[i]，先尝试较小的值，\r\n *   如果较小值已经出现，就尝试使用另一个值。\r\n *\r\n * 最后从 0 开始找第一个没有出现在 sets 中的整数，\r\n * 它就是当前构造下的 mex，并将其异或进本组数据的答案。\r\n *\r\n * 本次只补充中文注释，不修改原有逻辑。\r\n */\r\n\r\nint main(){\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    int T;\r\n    cin>>T;\r\n\r\n    while(T--){\r\n        int n;\r\n        cin>>n;\r\n        vector<ll> arr(n);\r\n        for (int i=0;i<n;i++){\r\n            ll x;\r\n            cin>>x;\r\n            arr[i]=x;\r\n        }\r\n        \r\n        // 每组测试数据的询问数量。\r\n        int q;\r\n        cin>>q;\r\n\r\n        // ans 保存本组所有询问答案的异或和。\r\n        ll ans=0;\r\n\r\n        // 每个询问彼此独立，因此下面重新为每个 k 构造一次。\r\n        for (int i=0;i<q;i++){\r\n            int k;\r\n            cin>>k;\r\n\r\n            // 这个变量在当前逻辑中没有被使用，可以理解为计算 k/2 的中间量。\r\n            double kk=k/2;\r\n\r\n            // sets 记录当前能够构造出的值。\r\n            unordered_set<ll> sets;\r\n\r\n            // 逐个处理数组元素，决定保留原值还是使用 k-x。\r\n            for (auto x:arr){\r\n                if (x>k){\r\n                    // k-x < 0，不能帮助形成非负整数，因此只保留 x。\r\n                    sets.insert(x);\r\n                }\r\n                else{\r\n                    // 优先取较小的可选值。\r\n                    ll min_x=min(x,k-x);\r\n\r\n                    // 如果较小值还没出现，就使用较小值；\r\n                    // 否则尝试使用另一个值 k-min_x。\r\n                    if (sets.count(min_x)==0) sets.insert(min_x);\r\n                    else sets.insert(k-min_x);\r\n                }\r\n            }\r\n\r\n            // 从 0 开始寻找第一个未出现的非负整数，即 mex。\r\n            ll tmp=0;\r\n            while (1){\r\n                if (sets.count(tmp)==0) break;\r\n                tmp++;\r\n            }\r\n            // cout<<\" tmp:\"<<tmp<<'\\n';\r\n            // 第一个答案直接赋值，后面的答案依次异或。\r\n            if (i==0) ans=tmp;\r\n            else{\r\n                ans=ans^tmp;\r\n                // cout<<\" ans:\"<<ans<<'\\n';\r\n            }\r\n        }\r\n\r\n        // 输出本组所有询问答案的异或和。\r\n        cout<<ans;\r\n        if (T) cout<<'\\n';\r\n    }\r\n}\r\n"},{"name":"hyper 原稿","language":"C++","status":"original","path":"2026ICPC网络赛/2/upsolve/K-hyper.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nll solveSmall(ll k,ll n,const vector<ll>& freq){\r\n    ll ans=n;\r\n    ll half=k/2;\r\n    for (ll i=0;i<=n and i<=half;i++){\r\n        ll cnt=freq[i]+freq[k-i];\r\n        if (cnt==0) ans=min(ans,i);\r\n        else if (cnt==1){\r\n            if(!(k%2==0 and i==half)) ans=min(ans,k-i);\r\n        } \r\n    }\r\n    for (ll i=k+1;i<=n;i++){\r\n        if (freq[i]==0) ans=min(ans,i);\r\n    }\r\n    return min(ans,n);\r\n}\r\n\r\nint main(){\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    int T;\r\n    cin>>T;\r\n    while(T--){\r\n        int n;\r\n        cin>>n;\r\n        vector<ll> freq(2*n+1,0);\r\n        unordered_set<ll> big(n);\r\n        vector<ll> missingsmall;\r\n        for (int i=1;i<=n;i++){\r\n            ll x;\r\n            cin>>x;\r\n            if (x<=2*n) freq[x]++;\r\n            if (x>n) big.insert(x);\r\n        }\r\n        for (int i=0;i<=n;i++){\r\n            if (freq[i]==0) missingsmall.push_back(i);\r\n        }\r\n        int q;\r\n        cin>>q;\r\n        ll ans=0;\r\n        unordered_map<ll,ll> memo;\r\n        for (int i=0;i<q;i++){\r\n            ll k;\r\n            ll tmp=n;\r\n            cin>>k;\r\n            auto it=memo.find(k);\r\n            if (it!=memo.end()){\r\n                tmp=it->second;\r\n            }\r\n            else{\r\n                if (k<=2*n){\r\n                    tmp=solveSmall(k,n,freq);\r\n                    memo.insert({k,tmp});\r\n                }\r\n                else{\r\n                    for (ll i : missingsmall){\r\n                        if (big.count(k-i)==0){\r\n                            tmp=min(tmp,i);\r\n                            memo.insert({k,tmp});\r\n                            break;\r\n                        }\r\n                    }\r\n                }\r\n            }\r\n            ans=ans^tmp;\r\n        }\r\n        cout<<ans;\r\n        if (T) cout<<'\\n';\r\n    }\r\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"2026ICPC网络赛/2/upsolve/K-AI.cpp","code":"#include <bits/stdc++.h>\r\n#include <vector>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\n/*\r\n * =============================== 题意 ===============================\r\n * 给定 n 个整数 a[0..n-1]。有 q 次询问，每次给出一个整数 k。\r\n * 对数组里的每个数 x，你都可以选择「保留 x」或者「把它替换成 k - x」。\r\n * 对某个 k，问：经过任意替换之后，数组的 mex（最小的未出现的非负整数）\r\n * 最大能是多少？每次询问互相独立，最后输出所有询问答案的异或和。\r\n *\r\n * ============================= 关键观察 =============================\r\n * 1) 只有 [0, n] 范围内的值会影响答案。\r\n *    因为 mex = m 要求 0,1,...,m-1 全部出现，需要 m 个互不相同的数，\r\n *    而数组一共只有 n 个数，所以 mex 一定 <= n。\r\n *\r\n * 2) 值 t 和值 k - t 是一对可以互相转化的「搭档」：\r\n *    原数组中等于 t 或者等于 k - t 的元素，最终都能被安排成 t 或 k - t。\r\n *    记 P = freq[t] + freq[k - t]，这 P 个元素可以被自由地分配给 t 和 k - t。\r\n *\r\n * 于是对每一对 {t, k - t}（下面约定 t <= k - t，即 t <= k/2），有：\r\n *    * P == 0：t 和 k - t 一个都凑不出来，mex 至多为较小的 t；\r\n *    * P == 1：只能凑出其中一个。为了让 mex 尽量大，应该把较小的 t 凑出来，\r\n *              这样 k - t 必然缺失，mex 至多为 k - t；\r\n *              特例：k 为偶数且 t == k - t == k/2 时，这个值本身只要 1 个\r\n *              元素就够了，所以不产生任何限制。\r\n *    * P >= 2：两个值都能凑出来，不产生限制。\r\n * 另外，当 t > k 时 k - t < 0，没法参与配对，此时只要 freq[t] == 0，\r\n * mex 就至多为 t。\r\n *\r\n * 每个值恰好属于一个配对，各配对之间互不干扰，所以把上面的所有上界取最小值，\r\n * 就是该 k 的答案。\r\n *\r\n * ============================== 复杂度 ==============================\r\n * 读入并预处理 O(n)。solveSmall(k) 一次 O(n)，而 k <= 2n 只有 2n+1 种取值，\r\n * 结果会被记忆化；k > 2n 时一次询问 O(缺失的小值个数)，并用哈希表记忆化。\r\n *\r\n * ========================= 为什么按 k 分两类 =========================\r\n * * k <= 2n    ：k - t 仍然比较小，可能落在 [0, 2n] 内，直接用 freq 数组配对即可。\r\n * * k >  2n    ：对任意 t <= n 都有 k - t > n，也就是「搭档」只可能是一个大值，\r\n *                于是 t 能否被凑出来，只取决于 k - t 有没有在数组里真正出现过，\r\n *                用哈希表 largeValue 来判断。\r\n */\r\n\r\n// 处理 k <= 2n 的情况：直接枚举每一对 {t, k-t}，取所有上界的最小值。\r\nint solveSmall(ll k,int n,vector<int>& freq){\r\n    int ans=n;                // mex 不可能超过 n，作为初始上界\r\n    ll half=k/2;              // 配对时只需考虑 t <= k/2，避免重复枚举同一对\r\n\r\n    // 枚举所有配对 {t, k-t}，其中 t <= k-t 且 t <= n\r\n    for (ll t=0;t<=half and t<=n;t++){\r\n        // P：能变成 t 或 k-t 的元素总数\r\n        int cnt=freq[(int)t]+freq[(int)(k-t)];\r\n\r\n        if (cnt==0){\r\n            // 两个值都凑不出来，最早缺失的是较小的 t\r\n            ans=min(ans,(int)t);\r\n        }\r\n        else if (cnt==1){\r\n            // 只够凑一个：优先凑较小的 t，于是 k-t 缺失\r\n            // 例外：自配对（k 为偶数，t == k/2），一个元素就足以凑出该值\r\n            if (!(k%2==0 and t==half)){\r\n                ans=min(ans,(int)(k-t));\r\n            }\r\n        }\r\n        // cnt >= 2：t 和 k-t 都能凑出来，不产生限制\r\n    }\r\n\r\n    // t > k 时 k - t 是负数，没法参与配对，只能用原来的 t 本身\r\n    for (ll t=k+1;t<=n;t++){\r\n        if (freq[(int)t]==0){\r\n            ans=min(ans,(int)t);\r\n        }\r\n    }\r\n\r\n    // 再和 n 取一次 min，防止 k-t > n 造成的无用上界\r\n    return min(ans,n);\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    int T;\r\n    cin>>T;\r\n\r\n    while (T--) {\r\n        int n;\r\n        cin>>n;\r\n\r\n        vector<ll> a(n);\r\n        for (ll &x : a) cin>>x;\r\n\r\n        // freq[v]：原数组中值恰好等于 v 的元素个数。\r\n        // 因为 k <= 2n 时才有必要配对，而且只关心不超过 2n 的值，所以开 2n+1 大小。\r\n        vector<int> freq(2*n+1,0);\r\n\r\n        // largeValue：所有大于 n 的数的集合（去重），哈希表实现，查询是 O(1)。\r\n        // 这些大值只有在「被 k 减去后」才可能变成影响 mex 的小值。\r\n        unordered_set<ll> largeValue;\r\n        largeValue.reserve(2*n+10);      // 预留空间，减少 rehash\r\n\r\n        for (ll x : a){\r\n            if (x<=2LL*n){\r\n                freq[(int)x]++;          // 只统计范围内出现的次数\r\n            }\r\n            if (x>n){\r\n                largeValue.insert(x);    // 记录出现过的大值\r\n            }\r\n        }\r\n\r\n        // missingSmall：在 [0, n] 中从未出现的值（按从小到大排列）。\r\n        // 当 k > 2n 时，只有这些位置的缺失才会成为阻碍。\r\n        vector<int> missingSmall;\r\n        missingSmall.reserve(n+1);\r\n        for (int t=0;t<=n;t++){\r\n            if (freq[t]==0){\r\n                missingSmall.push_back(t);\r\n            }\r\n        }\r\n\r\n        int q;\r\n        cin>>q;\r\n\r\n        // 记忆化：同一个 k 只会被算一次，避免重复 O(n) 的计算\r\n        vector<int> smallMemo(2*n+1,-1);     // 小 k 用数组直接下标\r\n        unordered_map<ll,int> largeMemo;     // 大 k 用哈希表\r\n        largeMemo.reserve(2*q+10);\r\n\r\n        ll answerXor=0;\r\n\r\n        while (q--) {\r\n            ll k;\r\n            cin>>k;\r\n\r\n            int ans;\r\n\r\n            if (k<=2LL*n){\r\n                // ---------- 情况一：k 比较小，用 freq 数组算 ----------\r\n                if (smallMemo[(int)k]==-1) smallMemo[(int)k]=solveSmall(k,n,freq);\r\n                ans=smallMemo[(int)k];\r\n            }\r\n            else{\r\n                // ---------- 情况二：k > 2n，用哈希表算 ----------\r\n                auto it=largeMemo.find(k);\r\n                if (it!=largeMemo.end()){\r\n                    ans=it->second;\r\n                }\r\n                else{\r\n                    ans=n;   // 默认答案是 n（mex 的上界）\r\n\r\n                    // 对 t <= n 而言，k - t > n，是「大值」。\r\n                    // 若 t 本来就没出现过（在 missingSmall 里），\r\n                    // 只要数组里存在 k - t，就能把一个 k-t 换成 t，把 t 补上。\r\n                    // missingSmall 是从小到大排列的，所以第一次补不上的 t 就是 mex。\r\n                    for (auto t : missingSmall){\r\n                        ll x=k-t;\r\n                        if (largeValue.find(x)!=largeValue.end()){\r\n                            continue;   // t 可以被补上\r\n                        }\r\n                        ans=t;          // t 补不上，mex 就是 t\r\n                        break;\r\n                    }\r\n\r\n                    largeMemo.emplace(k,ans);\r\n                }\r\n            }\r\n\r\n            answerXor^=ans;   // 题目要求所有询问答案异或和\r\n        }\r\n\r\n        cout<<answerXor<<'\\n';\r\n    }\r\n}"}],"statement":"","links":[{"label":"题档中的 QOJ 链接","url":"https://qoj.ac/contest/4113"}],"number":"K","hasIssues":false},{"id":"icpc2026-r2-J","title":"Problem J","source":"2026 ICPC 网络赛 · 第二场","platform":"QOJ","date":"","group":"icpc","category":"字符串","tags":["模式匹配","计分","分支"],"level":"基础","summary":"将六类字符串模式对应到固定分数，匹配后累计并与阈值比较。","caution":"模式末尾字母的有效范围需遵守题意；输出的固定字符串要完全匹配。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"2026ICPC网络赛/2/J.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\n#define ll long long\r\nint main()\r\n{\r\n    int t;\r\n    cin >> t;\r\n    while(t--)\r\n    {\r\n        int n,p;\r\n        cin >> n >> p;\r\n        vector<string> arr={\r\n        \"WrongProblemX\",\r\n        \"SameProblemX\",\r\n        \"UnreasonableProblemArrangement\",\r\n        \"UnreasonableLimitForProblemX\",\r\n        \"WeakTestsForProblemX\",\r\n        \"BadProblemX\"\r\n        };\r\n        vector<ll> scores={100,30,10,5,3,1};\r\n        int ans=0;\r\n        for (int i=0;i<n;i++){\r\n            string s;\r\n            cin>>s;\r\n            for (int i=0;i<6;i++){\r\n                string x=arr[i];\r\n                if (s.size()==x.size()){\r\n                    for (size_t j=0;j<s.size();j++){\r\n                        if (s[j]==x[j]){\r\n                            if (j==s.size()-1) ans+=scores[i];\r\n                            continue;\r\n                        }\r\n                        else if (j==s.size()-1 and s[j]-'A'>=0 and s[j]-'L'<=0){\r\n                            ans+=scores[i];\r\n                        }\r\n                        else break;\r\n                    }\r\n                }\r\n            }\r\n        }\r\n        if (ans>p) cout<<\"Joker\";\r\n        else cout<<\"Judger\";\r\n\r\n        if (t) cout<<'\\n';\r\n    }\r\n}"}],"statement":"","links":[{"label":"题档中的 QOJ 链接","url":"https://qoj.ac/contest/4113"}],"number":"J","hasIssues":false},{"id":"cqu2025-M","title":"少废话，你GPA多少","source":"2025 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2025","category":"数学与数论","tags":["分段函数","加权平均","浮点"],"level":"基础","summary":"按成绩分段计算绩点，累计学分乘绩点后除以总学分。","caution":"除法要使用浮点类型；输出精度不足会造成误差。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"2025重庆大学程序设计新生赛暨邀请赛/M 少废话，你GPA多少-hyper.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\n\r\nint main(){\r\n    int n;\r\n    cin>>n;\r\n    double p_sum=0.0;\r\n    vector<double> g(n+1);\r\n    vector<double> p(n+1);\r\n    for (int i=1;i<=n;i++){\r\n        double pi;\r\n        int si;\r\n        cin>>pi>>si;\r\n        p_sum+=pi;\r\n        p[i]=pi;\r\n        g[i]=(si<60) ? 0.0 : (si>=60 and si<90) ? (si-60.0)/10.0+1.0 : 4.0;\r\n    }\r\n    double GPA=0;\r\n    for (int i=1;i<=n;i++){\r\n        GPA+=(g[i]*p[i])/p_sum;\r\n    }\r\n    cout<<GPA<<'\\n';\r\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"2025重庆大学程序设计新生赛暨邀请赛/M 少废话，你GPA多少-AI.cpp","code":"#include <bits/stdc++.h>\nusing namespace std;\n\nint main(){\n    int n;\n    cin>>n;\n    double p_sum=0,g_sum=0;\n    for (int i=0;i<n;i++){\n        double p;\n        int s;\n        cin>>p>>s;\n        // 不及格为 0，60~89 分按线性公式，90 分及以上为 4。\n        // 除数写成 10.0，确保使用浮点除法，保留成绩对应的小数绩点。\n        double g=(s<60) ? 0.0 : (s<90) ? (s-60)/10.0+1.0 : 4.0;\n        p_sum+=p;\n        g_sum+=g*p;\n    }\n    // 先求“绩点乘学分”的总和，再除以总学分。\n    // 输出 10 位小数，避免默认 6 位有效数字带来的精度不足。\n    cout<<fixed<<setprecision(10)<<g_sum/p_sum<<'\\n';\n}\n"}],"statement":"","links":[],"number":"M","hasIssues":false},{"id":"cqu2025-L","title":"转轮密码机","source":"2025 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2025","category":"字符串","tags":["仿射映射","取模","输入解析"],"level":"进阶","summary":"解析整行单词与密钥，按字符差值及模 26 的变换输出。","caution":"字符偏移转为非负余数；空格和换行要保持正确。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"2025重庆大学程序设计新生赛暨邀请赛/L 转轮密码机-hyper.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\nint main(){\r\n    string s;\r\n    getline(cin,s);\r\n    stringstream ss1(s);\r\n    vector<string> arr;\r\n    string w1;\r\n    while (ss1>>w1) arr.push_back(w1);\r\n\r\n    int n=arr.size();\r\n\r\n    getline(cin,s);\r\n    stringstream ss2(s);\r\n    vector<char> x;\r\n    char w2;\r\n    while (ss2>>w2) x.push_back(w2);\r\n    \r\n    for (int i=0;i<n;i++){\r\n        s=arr[i];\r\n        for (char c : s){\r\n            int k=c-x[0]+26;\r\n            k*=6;\r\n            k=(k+6*26)%26;\r\n            cout<<(char)((x[2]-'a'+k)%26+'a');\r\n        }\r\n        if (i!=n-1) cout<<\" \";\r\n    }\r\n    cout<<'\\n';\r\n}"}],"statement":"","links":[],"number":"L","hasIssues":false},{"id":"cqu2025-K","title":"mini 2048","source":"2025 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2025","category":"模拟与实现","tags":["2048","方向分支"],"level":"基础","summary":"对 2×2 棋盘按方向比较并合并相同非零格，再压缩空位。","caution":"一次移动中同一格是否可重复合并要遵守题意。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"2025重庆大学程序设计新生赛暨邀请赛/K mini 2048-hyper.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\n\r\nint main(){\r\n    int a11,a12,a21,a22,dir;\r\n    cin>>a11>>a12>>a21>>a22>>dir;\r\n    switch (dir) {\r\n        case 1:{\r\n            if (a11==a21 and a11!=0){\r\n                a11*=2;\r\n                a21=0;\r\n            }\r\n            if (a12==a22 and a12!=0){\r\n                a12*=2;\r\n                a22=0;\r\n            }\r\n            if (a11==0) swap(a11,a21);\r\n            if (a12==0) swap(a12,a22);\r\n            break;\r\n        }\r\n        case 2:{\r\n            if (a11==a12 and a11!=0){\r\n                a11*=2;\r\n                a12=0;\r\n            }\r\n            if (a21==a22 and a21!=0){\r\n                a21*=2;\r\n                a22=0;\r\n            }\r\n            if (a11==0) swap(a11,a12);\r\n            if (a21==0) swap(a21,a22);\r\n            break;\r\n        }\r\n        case 3:{\r\n            if (a11==a21 and a11!=0){\r\n                a21*=2;\r\n                a11=0;\r\n            }\r\n            if (a12==a22 and a12!=0){\r\n                a22*=2;\r\n                a12=0;\r\n            }\r\n            if (a21==0) swap(a11,a21);\r\n            if (a22==0) swap(a12,a22);\r\n            break;\r\n        }\r\n        case 4:{\r\n            if (a11==a12 and a11!=0){\r\n                a12*=2;\r\n                a11=0;\r\n            }\r\n            if (a21==a22 and a21!=0){\r\n                a22*=2;\r\n                a21=0;\r\n            }\r\n            if (a12==0) swap(a11,a12);\r\n            if (a22==0) swap(a21,a22);\r\n            break;\r\n        }\r\n    }\r\n    cout<<a11<<\" \"<<a12<<\" \"<<a21<<\" \"<<a22<<'\\n';\r\n}"}],"statement":"","links":[],"number":"K","hasIssues":false},{"id":"cqu2025-J","title":"Hide点对","source":"2025 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2025","category":"图与树","tags":["深度奇偶","树","组合计数"],"level":"进阶","summary":"树上两点距离为偶数等价于深度同奇偶，分别从两类节点中选两个。","caution":"hyper 原稿仅输入 n；AI 参考使用迭代遍历避免递归深度风险。","versions":[{"name":"AI 参考","language":"C++","status":"reference","path":"2025重庆大学程序设计新生赛暨邀请赛/J Hide点对-AI.cpp","code":"#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin>>n;\n    vector<vector<int>> tree(n+1);\n    for (int i=1;i<n;i++){\n        int u,v;\n        cin>>u>>v;\n        tree[u].push_back(v);\n        tree[v].push_back(u);\n    }\n\n    // 树上两点距离为偶数，才存在到两点距离相等的路径中点。\n    // 距离的奇偶性等于两个点深度奇偶性的异或。\n    // 因而两点深度同奇偶时构成合法点对。\n    vector<int> parity(n+1,-1),orders;\n    parity[1]=0;\n    orders.push_back(1);\n    ll cnt[2]={0,0};\n    // 用遍历序列代替递归，避免长链导致递归栈溢出。\n    for (int i=0;i<(int)orders.size();i++){\n        int u=orders[i];\n        cnt[parity[u]]++;\n        for (int v : tree[u]){\n            if (parity[v]!=-1) continue;\n            parity[v]=parity[u]^1;\n            orders.push_back(v);\n        }\n    }\n    // 分别从偶深度、奇深度的点中选两个不同的点，不计顺序。\n    cout<<cnt[0]*(cnt[0]-1)/2+cnt[1]*(cnt[1]-1)/2<<'\\n';\n}\n"},{"name":"未完成稿","language":"C++","status":"incomplete","path":"2025重庆大学程序设计新生赛暨邀请赛/J Hide点对-hyper.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\n\r\nint main(){\r\n    ll n;\r\n    cin>>n;\r\n    \r\n}"}],"statement":"","links":[],"number":"J","hasIssues":true},{"id":"cqu2025-I","title":"Ifrit","source":"2025 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2025","category":"贪心与双指针","tags":["分组","排序","滑动窗口"],"level":"进阶","summary":"分别按横坐标、纵坐标分组，在各组内排序并寻找跨度不超过 5 的窗口。","caution":"同组数据要排序；左右端点随窗口同步移动。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"2025重庆大学程序设计新生赛暨邀请赛/I Ifrit-hyper.cpp","code":"#include <bits/stdc++.h>\r\n#include <vector>\r\n#include <set>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\n\r\nint main(){\r\n    ll n;\r\n    cin>>n;\r\n    map<ll,vector<ll>> rows,cols;\r\n    for (ll i=0;i<n;i++){\r\n        ll x,y;\r\n        cin>>x>>y;\r\n        rows[x].push_back(y);\r\n        cols[y].push_back(x);\r\n    }\r\n    ll ans=0;\r\n    for (auto& [x,arr] : rows){\r\n        sort(arr.begin(),arr.end());\r\n        ll l=0;\r\n        ll m=arr.size();\r\n        for (ll r=0;r<m;r++){\r\n            while (arr[r]-arr[l]>5)l++;\r\n            ans=max(ans,r-l+1);\r\n        }\r\n    }\r\n    for (auto& [x,arr] : cols){\r\n        sort(arr.begin(),arr.end());\r\n        ll l=0;\r\n        ll m=arr.size();\r\n        for (ll r=0;r<m;r++){\r\n            while (arr[r]-arr[l]>5)l++;\r\n            ans=max(ans,r-l+1);\r\n        }\r\n    }\r\n    cout<<ans;\r\n}"}],"statement":"","links":[],"number":"I","hasIssues":false},{"id":"cqu2025-H","title":"Raidian","source":"2025 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2025","category":"动态规划","tags":["区间状态","切比雪夫距离"],"level":"挑战","summary":"AI 参考用已建点的坐标包围盒刻画后续距离费用，再进行状态转移。","caution":"hyper 原稿仅保留骨架，先从 AI 注释理清状态边界。","versions":[{"name":"AI 参考","language":"C++","status":"reference","path":"2025重庆大学程序设计新生赛暨邀请赛/H Raidian-AI.cpp","code":"#include <bits/stdc++.h>\nusing namespace std;\n\nvector<string> board(8);\nint dp[8][8][8][8];\n\n// box={最小行,最大行,最小列,最大列}，最大行=-1 表示没有已建基站。\nvoid add(vector<int>& box,int x,int y){\n    box[0]=min(box[0],x);\n    box[1]=max(box[1],x);\n    box[2]=min(box[2],y);\n    box[3]=max(box[3],y);\n}\n\nint cost(const vector<int>& box,int x,int y){\n    if (box[1]==-1) return 0; // 第一个基站没有其他基站需要调试。\n    // 切比雪夫距离的最大值只取决于已建点的四个坐标极值。\n    return max({abs(x-box[0]),abs(x-box[1]),abs(y-box[2]),abs(y-box[3])});\n}\n\nint sideCost(const vector<pair<int,int>>& points,const vector<int>& base){\n    // 内部的基站已经全部建好，现在依次建设同一条边上的基站。\n    // 边上按坐标排序；存在一种最优顺序，让当前最左或最右的基站最后建。\n    // f[l][r] 表示剩余 points[l..r] 时，建设这些点的最小新增费用。\n    // 在逆序思考中，区间外的边界点还没建，内部 base 始终已经建好。\n    int m=points.size();\n    if (m==0) return 0;\n    int f[8][8]={};\n    for (int len=1;len<=m;len++){\n        for (int l=0;l+len<=m;l++){\n            int r=l+len-1;\n            vector<int> box=base;\n            if (len>1){\n                add(box,points[l+1].first,points[l+1].second);\n                add(box,points[r].first,points[r].second);\n            }\n            int left=(len==1 ? 0 : f[l+1][r])+cost(box,points[l].first,points[l].second);\n\n            box=base;\n            if (len>1){\n                add(box,points[l].first,points[l].second);\n                add(box,points[r-1].first,points[r-1].second);\n            }\n            int right=(len==1 ? 0 : f[l][r-1])+cost(box,points[r].first,points[r].second);\n            f[l][r]=min(left,right);\n        }\n    }\n    return f[0][m-1];\n}\n\nint solve(int top,int bottom,int left,int right){\n    if (top>bottom or left>right) return 0;\n    int& ans=dp[top][bottom][left][right];\n    if (ans!=-1) return ans;\n    bool empty=true;\n    for (int i=top;i<=bottom;i++){\n        for (int j=left;j<=right;j++){\n            if (board[i][j]=='#') empty=false;\n        }\n    }\n    if (empty) return ans=0;\n\n    // 官方题解的矩形区间 DP：先建内部，再建某一侧的所有基站。\n    // 枚举哪一侧最后建设，剩下的是一个更小的矩形。\n    ans=INT_MAX;\n    for (int dir=0;dir<4;dir++){\n        int nt=top,nb=bottom,nl=left,nr=right;\n        if (dir==0) nt++;\n        if (dir==1) nb--;\n        if (dir==2) nl++;\n        if (dir==3) nr--;\n\n        vector<pair<int,int>> points;\n        vector<int> base={8,-1,8,-1};\n        for (int i=top;i<=bottom;i++){\n            for (int j=left;j<=right;j++){\n                if (board[i][j]!='#') continue;\n                bool onSide=(dir==0 and i==top) or (dir==1 and i==bottom)\n                    or (dir==2 and j==left) or (dir==3 and j==right);\n                if (onSide) points.push_back({i,j});\n                else add(base,i,j);\n            }\n        }\n        ans=min(ans,solve(nt,nb,nl,nr)+sideCost(points,base));\n    }\n    return ans;\n}\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    for (int i=0;i<8;i++) cin>>board[i];\n    memset(dp,-1,sizeof dp);\n    cout<<solve(0,7,0,7)<<'\\n';\n}\n"},{"name":"未完成稿","language":"C++","status":"incomplete","path":"2025重庆大学程序设计新生赛暨邀请赛/H Raidian-hyper.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\n\r\nint main(){\r\n    vector<string> s(8);\r\n    for (int i=0;i<8;i++) cin>>s[i];\r\n    \r\n}"}],"statement":"","links":[],"number":"H","hasIssues":true},{"id":"cqu2025-G","title":"小机器人","source":"2025 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2025","category":"数学与数论","tags":["等差数列","溢出"],"level":"基础","summary":"将最大围住点数归纳为 0+1+…+(m−1)。","caution":"hyper 原稿使用 int 做乘法，范围大时溢出；参考版改用 long long。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"2025重庆大学程序设计新生赛暨邀请赛/G 小机器人-hyper.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nint main(){\r\n    int m;\r\n    cin>>m;\r\n    cout<<m*(m-1)/2;\r\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"2025重庆大学程序设计新生赛暨邀请赛/G 小机器人-AI.cpp","code":"#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\n\nint main(){\n    ll m;\n    cin>>m;\n    // 最大围住的点数为 0+1+...+(m-1)=m*(m-1)/2。\n    // 原公式是正确的，使用 long long 避免 int 中间乘法溢出。\n    cout<<m*(m-1)/2<<'\\n';\n}\n"}],"statement":"","links":[],"number":"G","hasIssues":true},{"id":"cqu2025-F","title":"环上问题","source":"2025 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2025","category":"数据结构","tags":["数论","分组和","multiset"],"level":"挑战","summary":"按 n 的不同质因子得到候选步长，维护模类之和及动态最大贡献。","caution":"hyper 原稿只保留一个步长；对比 AI 参考理解为什么需要多个候选。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"2025重庆大学程序设计新生赛暨邀请赛/F 环上问题-hyper.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\n\r\nvoid solve(){\r\n    ll n,q,k=1;\r\n    cin>>n>>q;\r\n    for (ll i=2;i<=sqrt(n)+1;i++){\r\n        if (n%i==0) {k=n/i;break;}\r\n    }\r\n    vector<ll> sum(k,0);\r\n    vector<ll> arr(n+1);\r\n    for (int i=1;i<=n;i++){\r\n        cin>>arr[i];\r\n        sum[i%k]+=arr[i];\r\n    }\r\n    cout<<*max_element(sum.begin(),sum.end())*k<<'\\n';\r\n    while(q--){\r\n        ll p,x;\r\n        cin>>p>>x;\r\n        sum[p%k]-=arr[p];\r\n        arr[p]=x;\r\n        sum[p%k]+=x;\r\n        cout<<*max_element(sum.begin(),sum.end())*k<<'\\n';\r\n    }\r\n}\r\nint main(){\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    ll T;\r\n    cin>>T;\r\n    while(T--){\r\n        solve();\r\n    }\r\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"2025重庆大学程序设计新生赛暨邀请赛/F 环上问题-AI.cpp","code":"#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\n\nvoid solve(){\n    int n,q;\n    cin>>n>>q;\n    vector<ll> arr(n+1);\n    for (int i=1;i<=n;i++) cin>>arr[i];\n\n    // 跳跃步长 k 形成的环大小是 n/gcd(n,k)。\n    // 环的贡献是 gcd(n,k) 乘环上元素和。\n    // 复合数大小的环可以拆成质数大小的小环，其中至少一个贡献不小于大环。\n    // 因而只需考虑 n 的每个不同质因子 e，以及对应步长 d=n/e。\n    vector<int> steps;\n    int left=n;\n    for (int e=2;e<=left/e;e++){\n        if (left%e==0){\n            steps.push_back(n/e);\n            while (left%e==0) left/=e;\n        }\n    }\n    if (left>1) steps.push_back(n/left);\n\n    // sums[j][r]：steps[j] 为步长时，下标模该步长等于 r 的元素和。\n    vector<vector<ll>> sums;\n    // 保存所有候选环的贡献；允许相同贡献重复出现，所以用 multiset。\n    multiset<ll> values;\n    for (int d : steps){\n        vector<ll> sum(d,0);\n        for (int i=1;i<=n;i++) sum[i%d]+=arr[i];\n        for (ll x : sum) values.insert(x*d);\n        sums.push_back(move(sum));\n    }\n\n    // 正常题目中的 n>=2；保留 n=1 的处理，避免对空集合取最大值。\n    cout<<(values.empty() ? arr[1] : *values.rbegin())<<'\\n';\n    while (q--){\n        int p;\n        ll x;\n        cin>>p>>x;\n        for (int j=0;j<(int)steps.size();j++){\n            int d=steps[j];\n            ll& sum=sums[j][p%d];\n            // 每个步长下，修改一个位置只会影响一个环。\n            // erase(迭代器) 只删除一个贡献，不能使用 erase(值) 删除所有重复项。\n            values.erase(values.find(sum*d));\n            sum+=x-arr[p];\n            values.insert(sum*d);\n        }\n        arr[p]=x;\n        cout<<(values.empty() ? arr[1] : *values.rbegin())<<'\\n';\n    }\n    // 设不同质因子数为 h，每次修改 O(h*log n)，空间 O(n*h)。\n}\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int T;\n    cin>>T;\n    while (T--) solve();\n}\n"}],"statement":"","links":[],"number":"F","hasIssues":true},{"id":"cqu2025-E","title":"查查你的 DPS","source":"2025 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2025","category":"数学与数论","tags":["区间","线性约束","分类讨论"],"level":"挑战","summary":"按两个输出区间的覆盖类型，提取 u、v、u+v 的已知约束。","caution":"原稿与 AI 参考需对照验证，重复信息不等于多解。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"2025重庆大学程序设计新生赛暨邀请赛/E 查查你的 DPS-hyper.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\n\r\nint main(){\r\n    ll T,l1,r1,l2,r2;\r\n    cin>>T>>l1>>r1>>l2>>r2;\r\n    ll m;\r\n    cin>>m;\r\n    ll pre_t=-1,pre_d=-1;\r\n    ll u=-1,v=-1;\r\n    bool ifyes=true;\r\n    while(m--){\r\n        ll t,d;\r\n        cin>>t>>d;\r\n        if (pre_t==-1 and pre_d==-1){\r\n            pre_d=d;\r\n            pre_t=t;\r\n            continue;\r\n        }\r\n        ll a11=0,a12=0,a21=0,a22=0;\r\n        if (pre_t>=l1 and pre_t<=r1-1) a11=1;\r\n        if (pre_t>=l2 and pre_t<=r2-1) a12=1;\r\n        if (t>=l1 and t<=r1-1) a21=1;\r\n        if (t>=l2 and t<=r2-1) a22=1;\r\n        ll y=a11*a22-a12*a21;\r\n        if (y==0){\r\n            cout<<\"Multiple solution\"<<'\\n';\r\n            ifyes=false;\r\n            break;\r\n        }\r\n        if (u==-1 and v==-1){\r\n            u=(pre_d*a22-a12*d)/y;\r\n            v=(d*a11-pre_d*a21)/y;\r\n        }\r\n        else{\r\n            if (u!=(pre_d*a22-a12*d)/(a11*a22-a12*a21) or \r\n                v!=(d*a11-pre_d*a21)/(a11*a22-a12*a21)){\r\n                cout<<\"Multiple solution\"<<'\\n';\r\n                ifyes=false;\r\n                break;\r\n            }\r\n        }\r\n    }\r\n    if (ifyes) cout<<u<<\" \"<<v<<'\\n';\r\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"2025重庆大学程序设计新生赛暨邀请赛/E 查查你的 DPS-AI.cpp","code":"#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    ll T,l1,r1,l2,r2;\n    cin>>T>>l1>>r1>>l2>>r2;\n    int m;\n    cin>>m;\n    // 两个输出区间均为左闭右开：[l1,r1)、[l2,r2)。\n    // 每条信息只可能告诉我们 u、v、u+v，或者两者都不输出时的 0。\n    // 题目保证有解，同类信息不会互相矛盾，重复信息也不代表多解。\n    vector<ll> val(4,0);\n    vector<bool> known(4,false);\n    for (int i=0;i<m;i++){\n        ll t,d;\n        cin>>t>>d;\n        int type=0;\n        if (l1<=t and t<r1) type|=1;\n        if (l2<=t and t<r2) type|=2;\n        if (type!=0){\n            known[type]=true;\n            val[type]=d;\n        }\n    }\n\n    ll u=0,v=0;\n    if (known[1] and known[2]){\n        u=val[1];\n        v=val[2];\n    }\n    else if (known[1] and known[3]){\n        u=val[1];\n        v=val[3]-u;\n    }\n    else if (known[2] and known[3]){\n        v=val[2];\n        u=val[3]-v;\n    }\n    else if (known[3] and val[3]==0){\n        // u、v 都非负，所以仅知道 u+v=0 也能确定两者都是 0。\n        u=v=0;\n    }\n    else{\n        cout<<\"Multiple solution\"<<'\\n';\n        return 0;\n    }\n    cout<<u<<\" \"<<v<<'\\n';\n}\n"}],"statement":"","links":[],"number":"E","hasIssues":false},{"id":"cqu2025-D","title":"猜数字 II","source":"2025 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2025","category":"交互","tags":["二分","有理数","flush"],"level":"挑战","summary":"AI 参考通过最简分数进行查询，在候选范围中逐步缩小答案。","caution":"hyper 原稿仅输入 n，未完成；交互输出必须刷新并处理读取结束。","versions":[{"name":"AI 参考","language":"C++","status":"reference","path":"2025重庆大学程序设计新生赛暨邀请赛/D 猜数字 II-AI.cpp","code":"#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\n\nbool ask(ll p,ll q){\n    // 查询必须是最简分数，而且必须刷新输出。\n    ll g=gcd(p,q);\n    cout<<p/g<<\"/\"<<q/g<<endl; // endl 自带换行和 flush。\n    string reply;\n    if (!(cin>>reply)) exit(0); // 交互结束时不再继续输出查询。\n    return reply==\">=\";\n}\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    ll n;\n    cin>>n;\n\n    // 第一阶段：用分母 n 的网格二分，定位到 [l/n,r/n)。\n    // 0 和 1 是已知边界，不作为查询；最终 r=l+1。\n    ll l=0,r=n;\n    while (r-l>1){\n        ll mid=(l+r)/2;\n        if (ask(mid,n)) l=mid;\n        else r=mid;\n    }\n\n    // 第二阶段：列出这个窄区间里分母不超过 n 的所有最简分数。\n    // 对每个分母 q，区间宽度乘 q 为 q/n<=1，最多包含一个分子。\n    vector<pair<ll,ll>> candidates;\n    for (ll q=2;q<=n;q++){\n        ll p=max(1LL,(l*q+n-1)/n); // ceil(l*q/n)，且分子必须大于 0。\n        if (p<q and p*n<r*q and gcd(p,q)==1){\n            candidates.push_back({p,q});\n        }\n    }\n    // 使用交叉相乘精确比较分数，避免浮点误差。\n    sort(candidates.begin(),candidates.end(),[](auto a,auto b){\n        return a.first*b.second<b.first*a.second;\n    });\n\n    int low=0,high=(int)candidates.size()-1;\n    while (low<high){\n        int mid=(low+high+1)/2;\n        if (ask(candidates[mid].first,candidates[mid].second)) low=mid;\n        else high=mid-1;\n    }\n    cout<<\"! \"<<candidates[low].first<<\"/\"<<candidates[low].second<<endl;\n    // 两阶段各不超过 ceil(log2(n)) 次，n<=10^5 时最多 34 次。\n    // 这是交互题，不能把题面示例响应当成普通固定输入验证。\n}\n"},{"name":"未完成稿","language":"C++","status":"incomplete","path":"2025重庆大学程序设计新生赛暨邀请赛/D 猜数字 II-hyper.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\n\r\nint main(){\r\n    ll n;\r\n    cin>>n;\r\n    \r\n}"}],"statement":"","links":[],"number":"D","hasIssues":true},{"id":"cqu2025-C","title":"说好的幸福呢 II","source":"2025 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2025","category":"数学与数论","tags":["贡献法","等差数列","奇偶性"],"level":"挑战","summary":"将 01 与 10 的数量差转成各个 1 的位置贡献，枚举可修改区间内放置的 1 的数量。","caution":"同时检查贡献上下界和步长为 2 的奇偶条件。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"2025重庆大学程序设计新生赛暨邀请赛/C 说好的幸福呢 II-hyper.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\n\r\nvoid solve(){\r\n    ll n,l,r;\r\n    string s;\r\n    cin>>n>>s>>l>>r;\r\n    ll tmp=0;\r\n    for (int i=1;i<=n;i++){\r\n        if ((i<l or i>r) and s[i-1]=='1') tmp+=2*i-n-1;\r\n    }\r\n    tmp=-tmp;\r\n    for (int x=0;x<=r-l+1;x++){\r\n        ll mintmp=(2*l+(x-1))*x-x*(n+1);\r\n        ll maxtmp=(2*r-(x-1))*x-x*(n+1);\r\n        if (tmp<=maxtmp and tmp>=mintmp and (tmp-mintmp)%2==0){\r\n            cout<<\"Yes\"<<'\\n';\r\n            return;\r\n        }\r\n    }\r\n    cout<<\"No\"<<'\\n';\r\n}\r\n\r\nint main(){\r\n    int T;\r\n    cin>>T;\r\n    while (T--) solve();\r\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"2025重庆大学程序设计新生赛暨邀请赛/C 说好的幸福呢 II-AI.cpp","code":"#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\n\nvoid solve(){\n    int n,l,r;\n    string s;\n    cin>>n>>s>>l>>r;\n\n    // 用 1 开始的下标表示位置。\n    // 整个字符串的“01 数量 - 10 数量”等于：\n    // 所有字符为 1 的位置 i 的 (2*i-n-1) 之和。\n    // 原因：每个 1 的贡献为前面 0 的数量减后面 0 的数量；\n    // 改用前后总字符数后，多算的 1-1 配对在求和时相互抵消。\n    // 因此幸福字符串恰好满足这个和为 0。\n    ll fixed=0;\n    for (int i=1;i<=n;i++){\n        if ((i<l or i>r) and s[i-1]=='1') fixed+=2LL*i-n-1;\n    }\n    ll target=-fixed; // 区间内部选出的 1 必须贡献 target。\n    int m=r-l+1;\n\n    // 枚举区间里填入多少个 1，记为 b。\n    // 权值从 2*l-n-1 到 2*r-n-1，按步长 2 递增。\n    // 最小和：选择最左侧的 b 个位置。\n    // 最大和：选择最右侧的 b 个位置。\n    // 固定 b 后，两端之间所有同奇偶性的和都能取得。\n    for (ll b=0;b<=m;b++){\n        ll low=b*(2LL*l-n-1)+b*(b-1);\n        ll high=b*(2LL*r-n-1)-b*(b-1);\n        if (low<=target and target<=high and (target-low)%2==0){\n            cout<<\"Yes\"<<'\\n';\n            return;\n        }\n    }\n    cout<<\"No\"<<'\\n';\n    // 每组 O(n)，总复杂度 O(所有字符串长度之和)。\n}\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int T;\n    cin>>T;\n    while (T--) solve();\n}\n"}],"statement":"","links":[],"number":"C","hasIssues":false},{"id":"cqu2025-B","title":"去码头整点...","source":"2025 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2025","category":"模拟与实现","tags":["分支","字典映射"],"level":"基础","summary":"把输入的单个字符映射成固定输出。","caution":"固定字符串的大小写与标点要完全匹配。","versions":[{"name":"hyper 原稿","language":"Python","status":"original","path":"2025重庆大学程序设计新生赛暨邀请赛/B 去码头整点...-hyper.py","code":"a=input()\r\nif a==\"F\":\r\n    print(\"Fish!\")\r\nelif a==\"C\":\r\n    print(\"Chips!\")\r\nelif a==\"P\":\r\n    print(\"???\")"}],"statement":"","links":[],"number":"B","hasIssues":false},{"id":"cqu2025-A","title":"星际数据流优化","source":"2025 重庆大学新生赛","platform":"校内竞赛","date":"","group":"c2025","category":"动态规划","tags":["有限状态","费用最小化"],"level":"挑战","summary":"用 9 个状态记录上一次操作费用，逐个字符选择下一次读取或跳过。","caution":"状态编号并非实际费用；不可达状态相加前要判断。","versions":[{"name":"hyper 原稿","language":"C++","status":"original","path":"2025重庆大学程序设计新生赛暨邀请赛/A 星际数据流优化-hyper.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\nconst ll INF=LLONG_MAX;\r\n\r\nint main(){\r\n    ll pretoken;\r\n    vector<ll> dp(9,INF);\r\n    string s;\r\n    cin>>pretoken>>s;\r\n    ll n=(ll)s.size();\r\n    const vector<ll> token={1,64,52,42,34,28,23,19,16};\r\n    ll start=0;\r\n    if (pretoken>1){\r\n        for (ll i=1;i<9;i++){\r\n            if (token[i]==pretoken) start=i;\r\n        }\r\n    }\r\n    dp[start]=0;\r\n    for (char c : s){\r\n        vector<ll> ndp(9,INF);\r\n        for (ll i=0;i<9;i++){ \r\n            if (dp[i]==INF) continue; \r\n            if (c=='p') ndp[0]=min(ndp[0],dp[i]+1);\r\n            ll next=min(i+1,8LL);\r\n            ndp[next]=min(ndp[next],dp[i]+token[next]);\r\n        }\r\n        dp.swap(ndp);\r\n    }\r\n    cout<<*min_element(dp.begin(),dp.end())<<'\\n';\r\n}"},{"name":"AI 参考","language":"C++","status":"reference","path":"2025重庆大学程序设计新生赛暨邀请赛/A 星际数据流优化-AI.cpp","code":"#include <bits/stdc++.h>\r\nusing namespace std;\r\nusing ll = long long;\r\n\r\nint main(){\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    ll pretoken;\r\n    string s;\r\n    cin>>pretoken>>s;\r\n\r\n    // DP（Dynamic Programming，动态规划）：\r\n    // 后续读取的费用只与上一次操作的消耗有关，不必保存完整操作序列。\r\n    // 用 9 个状态表示上一次操作：\r\n    // 状态 0：上一次是 p，消耗为 1。\r\n    // 状态 1~8：上一次是 r，消耗依次为 64,52,42,34,28,23,19,16。\r\n    // 注意状态编号不是实际消耗，实际消耗要通过 token[j] 取得。\r\n    const vector<ll> token={1,64,52,42,34,28,23,19,16};\r\n    const ll INF=LLONG_MAX/4; // 足够大的值，表示该状态暂时无法到达。\r\n\r\n    // dp[j]：处理完当前前缀，最后一次操作处于状态 j 的最小总消耗。\r\n    // 初始时还没有处理任何字符，只有虚拟前序操作对应的状态可达。\r\n    vector<ll> dp(9,INF);\r\n    int start=0;\r\n    if (pretoken>1){\r\n        for (int j=1;j<9;j++){\r\n            if (token[j]==pretoken) start=j;\r\n        }\r\n    }\r\n    // pretoken 为 0 或 1 时，下一次读取都按冷启动处理，对应状态 0。\r\n    // 虚拟前序操作本身不计入答案，所以初始化的总费用为 0。\r\n    dp[start]=0;\r\n\r\n    for (char c : s){\r\n        // ndp（next dp）：处理完这个字符之后的状态。\r\n        // 每轮重新初始化，避免沿用旧状态或在同一字符上重复转移。\r\n        vector<ll> ndp(9,INF);\r\n        for (int j=0;j<9;j++){\r\n            if (dp[j]==INF) continue; // 不可达状态不能转移。\r\n\r\n            // 选择一：执行 p，费用为 1，读取状态被重置。\r\n            // 只有原字符是 p 才能这样做，目标块 r 不能跳过。\r\n            if (c=='p'){\r\n                ndp[0]=min(ndp[0],dp[j]+1);\r\n            }\r\n\r\n            // 选择二：执行 r。\r\n            // 原字符是 r 时必须读取；原字符是 p 时可以主动改为 r。\r\n            // 前一次是 p：本次消耗为 64，对应状态 1。\r\n            // 前一次是 r：费用沿 64→52→42→34→28→23→19→16 递减。\r\n            // 这正是 max(16,ceil(0.8*前一次消耗))，无需使用浮点数。\r\n            // 到达状态 8 后继续读取仍是 16，所以编号不能超过 8。\r\n            int next=min(j+1,8);\r\n            ndp[next]=min(ndp[next],dp[j]+token[next]);\r\n        }\r\n        // 所有选择都完成后，再用新状态替换旧状态。\r\n        dp.swap(ndp);\r\n    }\r\n\r\n    // 最后一次操作可以是任意状态，取其中最小的总消耗。\r\n    cout<<*min_element(dp.begin(),dp.end())<<'\\n';\r\n    // 时间复杂度 O(9*|s|)，DP 额外空间 O(9)。\r\n}\r\n"}],"statement":"","links":[],"number":"A","hasIssues":false}],"counts":{"problems":88,"versions":131,"posters":47,"categories":12}};
